["Sıra Dışı Bir Şey Yok"] = "SIRA DIŞI BİR ŞEY YOK",
["Sırada 12 numaralı konteynere ateş tuzağı kurmak var."] = "SIRADA 12 NUMARALI KONTEYNERE ATEŞ TUZAĞI KURMAK VAR.",
["Sırada Araştırma Merkezi var. Neo-2'den söz eden bütün belgeleri toplamalıyız."] = "SIRADA ARAŞTIRMA MERKEZİ VAR. NEO-2'DEN SÖZ EDEN BÜTÜN BELGELERİ TOPLAMALIYIZ.",
