["Sırada ana Kasa Dairesi'ne erişmek var. İki Anahtar Kartı terminaliyle kontrol ediliyor. İkisinin de birkaç saniye arayla etkinleştirilmesi gerek. O yüzden iki Anahtar Kartı bulun."] = "SIRADA ANA KASA DAİRESİ'NE ERİŞMEK VAR. İKİ ANAHTAR KARTI TERMİNALİYLE KONTROL EDİLİYOR. İKİSİNİN DE BİRKAÇ SANİYE ARAYLA ETKİNLEŞTİRİLMESİ GEREK. O YÜZDEN İKİ ANAHTAR KARTI BULUN.",
["Sırada bilgisayar var."] = "SIRADA BİLGİSAYAR VAR.",
["Sırada güvenlik kapısını aşıp Kasa Dairesi'ne erişmek var."] = "SIRADA GÜVENLİK KAPISINI AŞIP KASA DAİRESİ'NE ERİŞMEK VAR.",
["Sırada güvenlik kutusu bulmak var. Üç tane var. Sistem kırma cihazını takın, ben de sisteme kaba kuvvet saldırısı yapayım. Kimsenin işlemi kesmesine izin vermeyin."] = "SIRADA GÜVENLİK KUTUSU BULMAK VAR. ÜÇ TANE VAR. SİSTEM KIRMA CİHAZINI TAKIN, BEN DE SİSTEME KABA KUVVET SALDIRISI YAPAYIM. KİMSENİN İŞLEMİ KESMESİNE İZİN VERMEYİN.",
["Sırada havalandırması güvenlik merkezine bağlı olan odayı bulmak var. Muhafızları uyku gazıyla bayıltmak için kullanabiliriz. Yani planlar lazım. Arşive bakın."] = "SIRADA HAVALANDIRMASI GÜVENLİK MERKEZİNE BAĞLI OLAN ODAYI BULMAK VAR. MUHAFIZLARI UYKU GAZIYLA BAYILTMAK İÇİN KULLANABİLİRİZ. YANİ PLANLAR LAZIM. ARŞİVE BAKIN.",
["Sırada kapıyı geçip çiftlik evine gitmek var. Gemma, Esteban'ın dizüstündeki istihbarat için bize iyi para verecek."] = "SIRADA KAPIYI GEÇİP ÇİFTLİK EVİNE GİTMEK VAR. GEMMA, ESTEBAN'IN DİZÜSTÜNDEKİ İSTİHBARAT İÇİN BİZE İYİ PARA VERECEK.",
["Sırada kasa dairesi bölümüne girmenin bir yolunu bulmak var."] = "SIRADA KASA DAİRESİ BÖLÜMÜNE GİRMENİN BİR YOLUNU BULMAK VAR.",
["Sırada kasa dairesinin kapısı var. İki Anahtar Kartı terminaliyle açılıyor. İkisini de olabildiğince çabuk okutun. Anladınız mı? Şimdi iki Anahtar Kartı bulun."] = "SIRADA KASA DAİRESİNİN KAPISI VAR. İKİ ANAHTAR KARTI TERMİNALİYLE AÇILIYOR. İKİSİNİ DE OLABİLDİĞİNCE ÇABUK OKUTUN. ANLADINIZ MI? ŞİMDİ İKİ ANAHTAR KARTI BULUN.",
["Sırada komuta merkezinin havalandırmasını tıkamak var. Keegan'ın içerideki adamı işinizi görecek aletler sakladı."] = "SIRADA KOMUTA MERKEZİNİN HAVALANDIRMASINI TIKAMAK VAR. KEEGAN'IN İÇERİDEKİ ADAMI İŞİNİZİ GÖRECEK ALETLER SAKLADI.",
["Sırada malikanenin kendisine girmenin yolunu bulmak var."] = "SIRADA MALİKANENİN KENDİSİNE GİRMENİN YOLUNU BULMAK VAR.",
["Sırada o lazer alarmını halletmek var."] = "SIRADA O LAZER ALARMINI HALLETMEK VAR.",
["Sırada silah prototipleri var. Buralarda bir yerde olmalılar. Ne kadar çok alırsanız o kadar çok satarız."] = "SIRADA SİLAH PROTOTİPLERİ VAR. BURALARDA BİR YERDE OLMALILAR. NE KADAR ÇOK ALIRSANIZ O KADAR ÇOK SATARIZ.",
["Sırada yaşlı Locke'un sisteme güzel, küçük bir bilgisayar virüsü yerleştirmesi var."] = "SIRADA YAŞLI LOCKE'UN SİSTEME GÜZEL, KÜÇÜK BİR BİLGİSAYAR VİRÜSÜ YERLEŞTİRMESİ VAR.",
["Sırada çiftlik evine gidip Gemma için o dizüstü bilgisayarı bulun. Kapıyı patlatmak için C4 kullanabilirsiniz."] = "SIRADA ÇİFTLİK EVİNE GİDİP GEMMA İÇİN O DİZÜSTÜ BİLGİSAYARI BULUN. KAPIYI PATLATMAK İÇİN C4 KULLANABİLİRSİNİZ.",
["Sıradaki adım etiketi kodlamak. Bilgisayara götürün!"] = "SIRADAKİ ADIM ETİKETİ KODLAMAK. BİLGİSAYARA GÖTÜRÜN!",
["Sıradaki adım kimlik doğrulama. Biraz sürecek, gözünüz sayaçta olsun."] = "SIRADAKİ ADIM KİMLİK DOĞRULAMA. BİRAZ SÜRECEK, GÖZÜNÜZ SAYAÇTA OLSUN.",
["Sıradaki adım yukarı çıkmak. Kartınızı resepsiyon masasında kullanarak yolu açabilirim."] = "SIRADAKİ ADIM YUKARI ÇIKMAK. KARTINIZI RESEPSİYON MASASINDA KULLANARAK YOLU AÇABİLİRİM.",
