["Sıçan Hector mıymış!? Dünyada çok aptal suçlu olduğunu söylerdi. Bizi kazıklayabileceğini sandığına göre onlardan biri de kendisiymiş."] = "SIÇAN HECTOR MIYMIŞ!? DÜNYADA ÇOK APTAL SUÇLU OLDUĞUNU SÖYLERDİ. BİZİ KAZIKLAYABİLECEĞİNİ SANDIĞINA GÖRE ONLARDAN BİRİ DE KENDİSİYMİŞ.",
["Sıçan aşağı mı atladı...? Hayır. Olamaz."] = "SIÇAN AŞAĞI MI ATLADI...? HAYIR. OLAMAZ.",
["Sıçanımız iyice saklanmış. Kapıyı geçmek için şifre VE iki Anahtar Kartı gerekecek. Aramaya başlayın."] = "SIÇANIMIZ İYİCE SAKLANMIŞ. KAPIYI GEÇMEK İÇİN ŞİFRE VE İKİ ANAHTAR KARTI GEREKECEK. ARAMAYA BAŞLAYIN.",
["Sıçtık!"] = "SIÇTIK!",
["Sıçtık! Kasanın kodu neydi dostum? O dosyaları yakmamız gerek!"] = "SIÇTIK! KASANIN KODU NEYDİ DOSTUM? O DOSYALARI YAKMAMIZ GEREK!",
["Sıçtık! O kapılar hava geçirmez sanıyordum! Suya dokunmayın, dostlar. O kopuk kablolardan gelen akım sizi fena çarpar!"] = "SIÇTIK! O KAPILAR HAVA GEÇİRMEZ SANIYORDUM! SUYA DOKUNMAYIN, DOSTLAR. O KOPUK KABLOLARDAN GELEN AKIM SİZİ FENA ÇARPAR!",
["Sıçtık! Orada bir şey yanıyor. Yangını söndürün, çabuk!"] = "SIÇTIK! ORADA BİR ŞEY YANIYOR. YANGINI SÖNDÜRÜN, ÇABUK!",
["Sıçtık! Ufak bir sorun var, sunucu ağır şifreli. Şifreleme anahtarları Güvenlik Ofisinde tutuluyor. Alıp buraya getirmeniz gerek!"] = "SIÇTIK! UFAK BİR SORUN VAR, SUNUCU AĞIR ŞİFRELİ. ŞİFRELEME ANAHTARLARI GÜVENLİK OFİSİNDE TUTULUYOR. ALIP BURAYA GETİRMENİZ GEREK!",
["Sıçtık! Vinçte elektrik sorunu var. Düzeltin, çabuk! Şansımızı zorlamak istemeyiz!"] = "SIÇTIK! VİNÇTE ELEKTRİK SORUNU VAR. DÜZELTİN, ÇABUK! ŞANSIMIZI ZORLAMAK İSTEMEYİZ!",
["Sıçtık! Şoförü vurdular! Şoförü vurdular! Başka bir seçenek lazım, dayanın!"] = "SIÇTIK! ŞOFÖRÜ VURDULAR! ŞOFÖRÜ VURDULAR! BAŞKA BİR SEÇENEK LAZIM, DAYANIN!",
["Sıçtık, FBI şefi olay yerinden kaçtı. Retina tarayıcısını yakın zamanda kullanamayacağız. B planına geçme vakti."] = "SIÇTIK, FBI ŞEFİ OLAY YERİNDEN KAÇTI. RETİNA TARAYICISINI YAKIN ZAMANDA KULLANAMAYACAĞIZ. B PLANINA GEÇME VAKTİ.",
["Sıçtık, FBI'ın güvenli evin yanındaki evlerde hazır ekipleri var. Size geliyorlar!"] = "SIÇTIK, FBI'IN GÜVENLİ EVİN YANINDAKİ EVLERDE HAZIR EKİPLERİ VAR. SİZE GELİYORLAR!",
["Sıçtık, alarm! Güvenlik odasını bulmanız gerek. Burası kilitliyken hiçbir şey yapamayız!"] = "SIÇTIK, ALARM! GÜVENLİK ODASINI BULMANIZ GEREK. BURASI KİLİTLİYKEN HİÇBİR ŞEY YAPAMAYIZ!",
["Sıçtık, ağır takviye geliyor. Çıkmak istiyorsanız ganimetle birlikte atlasanız iyi olur."] = "SIÇTIK, AĞIR TAKVİYE GELİYOR. ÇIKMAK İSTİYORSANIZ GANİMETLE BİRLİKTE ATLASANIZ İYİ OLUR.",
["Sıçtık, bir şey unuttum. O Kasa Dairesinde kaset bulursanız onları da alın lütfen... Şey, ben... Bilmiyorum, belki... Belki sonra bir yerde yakarsınız, tamam mı?"] = "SIÇTIK, BİR ŞEY UNUTTUM. O KASA DAİRESİNDE KASET BULURSANIZ ONLARI DA ALIN LÜTFEN... ŞEY, BEN... BİLMİYORUM, BELKİ... BELKİ SONRA BİR YERDE YAKARSINIZ, TAMAM MI?",
["Sıçtık, biri alarma ulaştı. Tamam, B planı vakti."] = "SIÇTIK, BİRİ ALARMA ULAŞTI. TAMAM, B PLANI VAKTİ.",
["Sıçtık, dışarıda sürünenler var. Pencerelere dikkat!"] = "SIÇTIK, DIŞARIDA SÜRÜNENLER VAR. PENCERELERE DİKKAT!",
["Sıçtık, dışarıdaki elektrik kutusu yandı! Bir yangın söndürücü bulup çabucak söndürün!"] = "SIÇTIK, DIŞARIDAKİ ELEKTRİK KUTUSU YANDI! BİR YANGIN SÖNDÜRÜCÜ BULUP ÇABUCAK SÖNDÜRÜN!",
["Sıçtık, gaz, gaz!!! Çıkın! Hızlanın!"] = "SIÇTIK, GAZ, GAZ!!! ÇIKIN! HIZLANIN!",
["Sıçtık, o bok yiyen herifler kilit açmayı durdurdu. Yeniden başlatın!"] = "SIÇTIK, O BOK YİYEN HERİFLER KİLİT AÇMAYI DURDURDU. YENİDEN BAŞLATIN!",
["Sıçtık, polis az önce ağır takviye çağırdı!"] = "SIÇTIK, POLİS AZ ÖNCE AĞIR TAKVİYE ÇAĞIRDI!",
["Sıçtık, polis burada!"] = "SIÇTIK, POLİS BURADA!",
["Sıçtık. Belki federaller akıllanıyordur. Alarm sunucuda güvenlik kalkanı tetikledi. Onu da matkapla delmeliyiz."] = "SIÇTIK. BELKİ FEDERALLER AKILLANIYORDUR. ALARM SUNUCUDA GÜVENLİK KALKANI TETİKLEDİ. ONU DA MATKAPLA DELMELİYİZ.",
["Sıçtık. GenSec'in hakkını vermek gerek. Güvenli kapı yapmayı gerçekten biliyorlar."] = "SIÇTIK. GENSEC'İN HAKKINI VERMEK GEREK. GÜVENLİ KAPI YAPMAYI GERÇEKTEN BİLİYORLAR.",
["Sıçtık. Görüyor musunuz? Yukarıda bir şey patladı. Piroteknik ekibi, düzeltin!"] = "SIÇTIK. GÖRÜYOR MUSUNUZ? YUKARIDA BİR ŞEY PATLADI. PİROTEKNİK EKİBİ, DÜZELTİN!",
["Sıçtık. Paralı asker birlikleri binayı kuşatıyor. Logoyu tanımıyorum... Şeye benziyor... Köpek balığı mı?"] = "SIÇTIK. PARALI ASKER BİRLİKLERİ BİNAYI KUŞATIYOR. LOGOYU TANIMIYORUM... ŞEYE BENZİYOR... KÖPEK BALIĞI MI?",
