["Tam isabet! İlk defa bir domuzun yardımı dokundu."] = "TAM İSABET! İLK DEFA BİR DOMUZUN YARDIMI DOKUNDU.",
["Tam isabet! İyi misiniz? Ne çarpışmaydı ama! O nakil araçlarına girişin!"] = "TAM İSABET! İYİ MİSİNİZ? NE ÇARPIŞMAYDI AMA! O NAKİL ARAÇLARINA GİRİŞİN!",
["Tam isabet, evet! Artık peşimize takılmalarını hiç dert etmeden uçup gidebiliriz!"] = "TAM İSABET, EVET! ARTIK PEŞİMİZE TAKILMALARINI HİÇ DERT ETMEDEN UÇUP GİDEBİLİRİZ!",
["Tam isabet. Devam edin millet."] = "TAM İSABET. DEVAM EDİN MİLLET.",
["Tam isabet. Planın özeti: Eve girin, laboratuvarı bulun, motoru alın, bu havaalanına dönün, kaçın. İyi şanslar."] = "TAM İSABET. PLANIN ÖZETİ: EVE GİRİN, LABORATUVARI BULUN, MOTORU ALIN, BU HAVAALANINA DÖNÜN, KAÇIN. İYİ ŞANSLAR.",
["Tam kararında basınç oluşturmamız gerek. Matkabı patlatacak kadar olsun ama çok da olmasın, yoksa kaçacak vaktiniz kalmaz."] = "TAM KARARINDA BASINÇ OLUŞTURMAMIZ GEREK. MATKABI PATLATACAK KADAR OLSUN AMA ÇOK DA OLMASIN, YOKSA KAÇACAK VAKTİNİZ KALMAZ.",
["Tam kaç kamera var emin değilim."] = "TAM KAÇ KAMERA VAR EMİN DEĞİLİM.",
