["Tam orada! Bedelini ödetin!"] = "TAM ORADA! BEDELİNİ ÖDETİN!",
["Tam orada, görüntüde... kasa dairesi bu."] = "TAM ORADA, GÖRÜNTÜDE... KASA DAİRESİ BU.",
["Tam ortasına. Alex iyi bıraktı."] = "TAM ORTASINA. ALEX İYİ BIRAKTI.",
["Tam otomatik dosta selam vermeyi unutma."] = "TAM OTOMATİK DOSTA SELAM VERMEYİ UNUTMA.",
["Tam oturdu!"] = "TAM OTURDU!",
["Tam oturdu."] = "TAM OTURDU.",
["Tam oyun hakkında bilgi."] = "TAM OYUN HAKKINDA BİLGİ.",
["Tam size göre yeni bir iş buldum."] = "TAM SİZE GÖRE YENİ BİR İŞ BULDUM.",
["Tam sürümü oynamak için yükleme tamamlandıktan sonra oyunu yeniden başlatmalısın."] = "TAM SÜRÜMÜ OYNAMAK İÇİN YÜKLEME TAMAMLANDIKTAN SONRA OYUNU YENİDEN BAŞLATMALISIN.",
["Tam tepenizdeler... Siktir..."] = "TAM TEPENİZDELER... SİKTİR...",
["Tam yerine bıraktım."] = "TAM YERİNE BIRAKTIM.",
["Tam yerine gelmişiz galiba. Aradığımız silahlar bunlar."] = "TAM YERİNE GELMİŞİZ GALİBA. ARADIĞIMIZ SİLAHLAR BUNLAR.",
["Tam yerine, evet."] = "TAM YERİNE, EVET.",
["Tam yol ileri ekip! Demiryollarını gideceğimiz yere yarın varalım diye yapmadık! Oraya DÜN varmış olmak istiyorum! Çuf çuf, dallamalar!"] = "TAM YOL İLERİ EKİP! DEMİRYOLLARINI GİDECEĞİMİZ YERE YARIN VARALIM DİYE YAPMADIK! ORAYA DÜN VARMIŞ OLMAK İSTİYORUM! ÇUF ÇUF, DALLAMALAR!",
["Tam yük oldu. Dayanın. Helikopter geri gelecek."] = "TAM YÜK OLDU. DAYANIN. HELİKOPTER GERİ GELECEK.",
["Tam zamanında yetiştik ama durumunun dengelenmesi için şuradaki defibrilatörle şok vermek gerekecek. Hemen kullanın!"] = "TAM ZAMANINDA YETİŞTİK AMA DURUMUNUN DENGELENMESİ İÇİN ŞURADAKİ DEFİBRİLATÖRLE ŞOK VERMEK GEREKECEK. HEMEN KULLANIN!",
["Tam zamanında. Bu sefer doğru kabloyu keselim, ha?"] = "TAM ZAMANINDA. BU SEFER DOĞRU KABLOYU KESELİM, HA?",
["Tam zamanında... "] = "TAM ZAMANINDA... ",
["Tam öğle vakti rakibinin 20 fit karşısında dururken tarzını konuşturmak isteyen silahşora. (Ya da sadece matkabın işini bitirmesini bekleyene.)"] = "TAM ÖĞLE VAKTİ RAKİBİNİN 20 FİT KARŞISINDA DURURKEN TARZINI KONUŞTURMAK İSTEYEN SİLAHŞORA. (YA DA SADECE MATKABIN İŞİNİ BİTİRMESİNİ BEKLEYENE.)",
["Tam İsabet"] = "TAM İSABET",
["Tam şuradaki kapıdan geçin. Twitch bekliyor!"] = "TAM ŞURADAKİ KAPIDAN GEÇİN. TWITCH BEKLİYOR!",
["Tamam"] = "TAMAM",
["Tamam Bain. Bitirelim şu boktan işi."] = "TAMAM BAIN. BİTİRELİM ŞU BOKTAN İŞİ.",
["Tamam Dallas. Birlikte çalışalı iki yıl oldu; hâlâ gereken yeteneğe sahip olduğunu görmeliyim. Basit bir işle başlayacağız, tamam mı? Bir tanıdığım geçenlerde kokain alışverişinde aşağılık bir mafyacı tarafından soyuldu. Gece kulübüne girip çalınan kokaini bulmanı ve geri almanı istiyorum. Kolay, değil mi? "] = "TAMAM DALLAS. BİRLİKTE ÇALIŞALI İKİ YIL OLDU; HÂLÂ GEREKEN YETENEĞE SAHİP OLDUĞUNU GÖRMELİYİM. BASİT BİR İŞLE BAŞLAYACAĞIZ, TAMAM MI? BİR TANIDIĞIM GEÇENLERDE KOKAİN ALIŞVERİŞİNDE AŞAĞILIK BİR MAFYACI TARAFINDAN SOYULDU. GECE KULÜBÜNE GİRİP ÇALINAN KOKAİNİ BULMANI VE GERİ ALMANI İSTİYORUM. KOLAY, DEĞİL Mİ? ",
["Tamam Dallas. Birlikte çalışmayalı iki yıl oldu. Sende hâlâ o becerinin olduğunu görmem gerekiyor. Basit bir şeyle başlayalım, olur mu? Bir tanıdığım geçenlerde kokain alışverişinde aşağılık bir mafya herifine soyulmuş. Gece kulübüne girip çalınan kokaini bulmaya ve geri almaya çalışmanı istiyorum. Kolay, değil mi?"] = "TAMAM DALLAS. BİRLİKTE ÇALIŞMAYALI İKİ YIL OLDU. SENDE HÂLÂ O BECERİNİN OLDUĞUNU GÖRMEM GEREKİYOR. BASİT BİR ŞEYLE BAŞLAYALIM, OLUR MU? BİR TANIDIĞIM GEÇENLERDE KOKAİN ALIŞVERİŞİNDE AŞAĞILIK BİR MAFYA HERİFİNE SOYULMUŞ. GECE KULÜBÜNE GİRİP ÇALINAN KOKAİNİ BULMAYA VE GERİ ALMAYA ÇALIŞMANI İSTİYORUM. KOLAY, DEĞİL Mİ?",
["Tamam Twitch... Sıra sende. Kulaklarınızı kapatsanız iyi olur dostlar."] = "TAMAM TWITCH... SIRA SENDE. KULAKLARINIZI KAPATSANIZ İYİ OLUR DOSTLAR.",
