["Tamam ama bir daha olursa alarmı çalarım lan."] = "TAMAM AMA BİR DAHA OLURSA ALARMI ÇALARIM LAN.",
["Tamam ama gelip bir bakacağız."] = "TAMAM AMA GELİP BİR BAKACAĞIZ.",
["Tamam ama hâlâ hangisi olduğunu bulup o takip cihazını kamyonun altına takmanız gerekiyor... Ya da çıkıp gidin."] = "TAMAM AMA HÂLÂ HANGİSİ OLDUĞUNU BULUP O TAKİP CİHAZINI KAMYONUN ALTINA TAKMANIZ GEREKİYOR... YA DA ÇIKIP GİDİN.",
["Tamam ama nasıl... ?"] = "TAMAM AMA NASIL... ?",
["Tamam ama oraya birkaç adam gönderiyoruz."] = "TAMAM AMA ORAYA BİRKAÇ ADAM GÖNDERİYORUZ.",
["Tamam ama sesine ne oldu? Tuhaf geliyor."] = "TAMAM AMA SESİNE NE OLDU? TUHAF GELİYOR.",
["Tamam bakın, anlaşma şöyle."] = "TAMAM BAKIN, ANLAŞMA ŞÖYLE.",
["Tamam bakın, anlaşma şöyle:"] = "TAMAM BAKIN, ANLAŞMA ŞÖYLE:",
["Tamam bakın, yapmanızı istediğim şu:"] = "TAMAM BAKIN, YAPMANIZI İSTEDİĞİM ŞU:",
["Tamam beyler! Bir çanta daha, Hector'ın payı tamam. Sonra asıl para kazanmaya başlayabiliriz."] = "TAMAM BEYLER! BİR ÇANTA DAHA, HECTOR'IN PAYI TAMAM. SONRA ASIL PARA KAZANMAYA BAŞLAYABİLİRİZ.",
["Tamam beyler! Oradan defolup gitme vakti!"] = "TAMAM BEYLER! ORADAN DEFOLUP GİTME VAKTİ!",
["Tamam beyler, burada olduğu söylenen bir evrak çantası da lazım. Onu bulun!"] = "TAMAM BEYLER, BURADA OLDUĞU SÖYLENEN BİR EVRAK ÇANTASI DA LAZIM. ONU BULUN!",
["Tamam beyler, doğru anda alışverişi bozun; sonra Alex limuzini oradan kaldıracak."] = "TAMAM BEYLER, DOĞRU ANDA ALIŞVERİŞİ BOZUN; SONRA ALEX LİMUZİNİ ORADAN KALDIRACAK.",
["Tamam beyler. Cabot'un adamları mağazanın dışında sizi bekleyecek. Söylediğine göre hızlı ve kolay olmalı. Şu profesyonel L.A. gangsterlerine Payday Gang'in neler yapabildiğini gösterin."] = "TAMAM BEYLER. CABOT'UN ADAMLARI MAĞAZANIN DIŞINDA SİZİ BEKLEYECEK. SÖYLEDİĞİNE GÖRE HIZLI VE KOLAY OLMALI. ŞU PROFESYONEL L.A. GANGSTERLERİNE PAYDAY GANG'İN NELER YAPABİLDİĞİNİ GÖSTERİN.",
["Tamam doktorlar, MIT becerilerinizi konuşturun. Doğru füzyon motorunu bulun. Hadi!"] = "TAMAM DOKTORLAR, MIT BECERİLERİNİZİ KONUŞTURUN. DOĞRU FÜZYON MOTORUNU BULUN. HADİ!",
["Tamam donut oğlanı. Bunu çıkaracağım, sen de konuşacaksın, capisci? Bizi kim tuzağa düşürdü?"] = "TAMAM DONUT OĞLANI. BUNU ÇIKARACAĞIM, SEN DE KONUŞACAKSIN, CAPİSCİ? BİZİ KİM TUZAĞA DÜŞÜRDÜ?",
["Tamam dostlar, bağlanmak için biraz zaman verin."] = "TAMAM DOSTLAR, BAĞLANMAK İÇİN BİRAZ ZAMAN VERİN.",
["Tamam dostlar, bu cevizi kırma vakti. İçeri bir yol bulun."] = "TAMAM DOSTLAR, BU CEVİZİ KIRMA VAKTİ. İÇERİ BİR YOL BULUN.",
["Tamam dostlar, bu iş uzun zamandır pişiyordu. Hesap sorma vakti, ha?"] = "TAMAM DOSTLAR, BU İŞ UZUN ZAMANDIR PİŞİYORDU. HESAP SORMA VAKTİ, HA?",
["Tamam dostlar, buna bayılacaksınız! Kışın ortasında küçük bir vurkaç, ha?"] = "TAMAM DOSTLAR, BUNA BAYILACAKSINIZ! KIŞIN ORTASINDA KÜÇÜK BİR VURKAÇ, HA?",
["Tamam dostlar, doğru yer bu. Ana alana çıkıp vinci kullanın."] = "TAMAM DOSTLAR, DOĞRU YER BU. ANA ALANA ÇIKIP VİNCİ KULLANIN.",
["Tamam dostlar, gereken her şeyi aldınız. Oradan çıkma vakti!"] = "TAMAM DOSTLAR, GEREKEN HER ŞEYİ ALDINIZ. ORADAN ÇIKMA VAKTİ!",
["Tamam dostlar, gitme vaktiniz geldi. Mümkünse yanınıza fazladan ganimet alın."] = "TAMAM DOSTLAR, GİTME VAKTİNİZ GELDİ. MÜMKÜNSE YANINIZA FAZLADAN GANİMET ALIN.",
["Tamam dostlar, hazırlanın!"] = "TAMAM DOSTLAR, HAZIRLANIN!",
["Tamam dostlar, hazırlanın. Unutmayın, Murky'nin en iyi adamları burada. Oyalanmayın."] = "TAMAM DOSTLAR, HAZIRLANIN. UNUTMAYIN, MURKY'NİN EN İYİ ADAMLARI BURADA. OYALANMAYIN.",
["Tamam dostlar, polislerin gelmesine fazla zaman yok. Gidip bankanın içine bakın."] = "TAMAM DOSTLAR, POLİSLERİN GELMESİNE FAZLA ZAMAN YOK. GİDİP BANKANIN İÇİNE BAKIN.",
["Tamam dostlar, rehinemizi beladan uzak ve güvende tutalım, olur mu?"] = "TAMAM DOSTLAR, REHİNEMİZİ BELADAN UZAK VE GÜVENDE TUTALIM, OLUR MU?",
["Tamam dostlar, silah laboratuvarına gitmelisiniz. Kutulardan birini bitişik odada tutuyorlar sanırım."] = "TAMAM DOSTLAR, SİLAH LABORATUVARINA GİTMELİSİNİZ. KUTULARDAN BİRİNİ BİTİŞİK ODADA TUTUYORLAR SANIRIM.",
["Tamam dostlar, şimdi o testereyi çıkarın."] = "TAMAM DOSTLAR, ŞİMDİ O TESTEREYİ ÇIKARIN.",
["Tamam dostlar. Asansöre ulaşmanız gerekiyor. Kameralar, muhafızlar ve metal dedektörleri var. Ne yapacağınızı biliyorsunuz."] = "TAMAM DOSTLAR. ASANSÖRE ULAŞMANIZ GEREKİYOR. KAMERALAR, MUHAFIZLAR VE METAL DEDEKTÖRLERİ VAR. NE YAPACAĞINIZI BİLİYORSUNUZ.",
["Tamam dostlar. Bain'i kurtarma vakti."] = "TAMAM DOSTLAR. BAIN'İ KURTARMA VAKTİ.",
["Tamam dostlar. Başka bir rehine pazarlığının zamanı geldi. Tabii ki dostane bir iş. Bu kez Golden Grin Casino'yu vuruyoruz; fişlerinizi koruyun ve bahisleri fazla yükseltmeyin."] = "TAMAM DOSTLAR. BAŞKA BİR REHİNE PAZARLIĞININ ZAMANI GELDİ. TABİİ Kİ DOSTANE BİR İŞ. BU KEZ GOLDEN GRIN CASINO'YU VURUYORUZ; FİŞLERİNİZİ KORUYUN VE BAHİSLERİ FAZLA YÜKSELTMEYİN.",
["Tamam dostlar. Biraz açılıp zor günler için yeni gelir yollarını güvenceye alma zamanı. Bu kasabanın polisleri rehine pazarlıklarında oldukça yüklü ödemeler yapmalarıyla tanınıyor; biz de bu küçük gerçeği kullanacağız. Güzel paraları hemen vermeyecekler. Ben daha fazlasını koparmaya çalışırken mümkün olduğunca uzun dayanıp sabretmelisiniz. Unutmayın, hem büyük vurgun hem de serbest kalmanız için pazarlık edemem; yakalanmayın, tamam mı?"] = "TAMAM DOSTLAR. BİRAZ AÇILIP ZOR GÜNLER İÇİN YENİ GELİR YOLLARINI GÜVENCEYE ALMA ZAMANI. BU KASABANIN POLİSLERİ REHİNE PAZARLIKLARINDA OLDUKÇA YÜKLÜ ÖDEMELER YAPMALARIYLA TANINIYOR; BİZ DE BU KÜÇÜK GERÇEĞİ KULLANACAĞIZ. GÜZEL PARALARI HEMEN VERMEYECEKLER. BEN DAHA FAZLASINI KOPARMAYA ÇALIŞIRKEN MÜMKÜN OLDUĞUNCA UZUN DAYANIP SABRETMELİSİNİZ. UNUTMAYIN, HEM BÜYÜK VURGUN HEM DE SERBEST KALMANIZ İÇİN PAZARLIK EDEMEM; YAKALANMAYIN, TAMAM MI?",
["Tamam dostlar. Bu işte Vlad'a yardım etmeliyiz. Washington'daki mevcut işlerimizden epey uzaklaşmamızı gerektirse de ona borçlu olduğumuzu düşünüyorum. Mexico City'nin hemen güneyindeki küçük bir kasabada bulunan San Martín Bank'e girmemizi istiyor. Tam olarak ne çalacağımızı bu kadar gizlemesi beni biraz endişelendiriyor ama görünce anlayacağınızı söylüyor. Şu salakla her şey bilmece ama sizi işin içinden çıkaracak kurnaz bir planım var. Bankayı Coyopa karteli işletiyor. Şu \"Buluc\" denen adam hakkında okuduklarıma göre tam bir pislik. Yine de işleyiş bakımından oldukça standart olmalı. Kesin sonradan pişman olacağım sözler bunlar!"] = "TAMAM DOSTLAR. BU İŞTE VLAD'A YARDIM ETMELİYİZ. WASHINGTON'DAKİ MEVCUT İŞLERİMİZDEN EPEY UZAKLAŞMAMIZI GEREKTİRSE DE ONA BORÇLU OLDUĞUMUZU DÜŞÜNÜYORUM. MEXİCO CİTY'NİN HEMEN GÜNEYİNDEKİ KÜÇÜK BİR KASABADA BULUNAN SAN MARTÍN BANK'E GİRMEMİZİ İSTİYOR. TAM OLARAK NE ÇALACAĞIMIZI BU KADAR GİZLEMESİ BENİ BİRAZ ENDİŞELENDİRİYOR AMA GÖRÜNCE ANLAYACAĞINIZI SÖYLÜYOR. ŞU SALAKLA HER ŞEY BİLMECE AMA SİZİ İŞİN İÇİNDEN ÇIKARACAK KURNAZ BİR PLANIM VAR. BANKAYI COYOPA KARTELİ İŞLETİYOR. ŞU \"BULUC\" DENEN ADAM HAKKINDA OKUDUKLARIMA GÖRE TAM BİR PİSLİK. YİNE DE İŞLEYİŞ BAKIMINDAN OLDUKÇA STANDART OLMALI. KESİN SONRADAN PİŞMAN OLACAĞIM SÖZLER BUNLAR!",
["Tamam dostlar. Buluc'un şarap mahzenini bulun. Malikaneye girmenin güzel, sessiz bir yolu."] = "TAMAM DOSTLAR. BULUC'UN ŞARAP MAHZENİNİ BULUN. MALİKANEYE GİRMENİN GÜZEL, SESSİZ BİR YOLU.",
["Tamam dostlar. Gitme vakti."] = "TAMAM DOSTLAR. GİTME VAKTİ.",
["Tamam dostlar. Hadi yapalım şu işi. Bankaya girin."] = "TAMAM DOSTLAR. HADİ YAPALIM ŞU İŞİ. BANKAYA GİRİN.",
["Tamam dostlar. Helikoptere gidin!"] = "TAMAM DOSTLAR. HELİKOPTERE GİDİN!",
["Tamam dostlar. O pislik Yufu Wang, yukarıda, kulenin en tepesinde saklanıyor. Aklınızı başınızda tutun ve bol ganimetle dönün."] = "TAMAM DOSTLAR. O PİSLİK YUFU WANG, YUKARIDA, KULENİN EN TEPESİNDE SAKLANIYOR. AKLINIZI BAŞINIZDA TUTUN VE BOL GANİMETLE DÖNÜN.",
["Tamam dostlar. SERA aşağıdaki etkinlik salonunda karbon yakalama prototipini tanıtmaya hazırlanıyor. Bir bakın."] = "TAMAM DOSTLAR. SERA AŞAĞIDAKİ ETKİNLİK SALONUNDA KARBON YAKALAMA PROTOTİPİNİ TANITMAYA HAZIRLANIYOR. BİR BAKIN.",
["Tamam dostlar. Siz işe koyulun, ihtiyar Locke sizi kesin kısa sürede pişirmeye başlatır!"] = "TAMAM DOSTLAR. SİZ İŞE KOYULUN, İHTİYAR LOCKE SİZİ KESİN KISA SÜREDE PİŞİRMEYE BAŞLATIR!",
["Tamam dostlar. Twitch sizi almak için hazır bekliyor. Ona izin vereyim. Biraz dayanın, olur mu?"] = "TAMAM DOSTLAR. TWITCH SİZİ ALMAK İÇİN HAZIR BEKLİYOR. ONA İZİN VEREYİM. BİRAZ DAYANIN, OLUR MU?",
["Tamam dostlar. Uçağa yakıt doldurma vakti."] = "TAMAM DOSTLAR. UÇAĞA YAKIT DOLDURMA VAKTİ.",
["Tamam dostlar... gitme vakti."] = "TAMAM DOSTLAR... GİTME VAKTİ.",
["Tamam dostlarım! South Portico yakınlarına ineceğiz. Her yerde Murky var, hazır olun. PEOC'ye girmek için Anahtar Kartı gerekecek. Bence aramaya West Wing'den başlamalıyız."] = "TAMAM DOSTLARIM! SOUTH PORTİCO YAKINLARINA İNECEĞİZ. HER YERDE MURKY VAR, HAZIR OLUN. PEOC'YE GİRMEK İÇİN ANAHTAR KARTI GEREKECEK. BENCE ARAMAYA WEST WİNG'DEN BAŞLAMALIYIZ.",
["Tamam dostlarım, dışarı çıkıp Mr Pink'i alsanız iyi olur, ha?"] = "TAMAM DOSTLARIM, DIŞARI ÇIKIP MR PİNK'İ ALSANIZ İYİ OLUR, HA?",
["Tamam dostlarım, kımıldayın! Kaçış aracınız geldi. Çabuk çabuk."] = "TAMAM DOSTLARIM, KIMILDAYIN! KAÇIŞ ARACINIZ GELDİ. ÇABUK ÇABUK.",
["Tamam dostlarım, neredeyse kurtuldunuz. Biraz daha..."] = "TAMAM DOSTLARIM, NEREDEYSE KURTULDUNUZ. BİRAZ DAHA...",
["Tamam dostlarım, role girme vakti."] = "TAMAM DOSTLARIM, ROLE GİRME VAKTİ.",
["Tamam dostlarım, uğruna geldiğimiz adam bu. İşini bitirin."] = "TAMAM DOSTLARIM, UĞRUNA GELDİĞİMİZ ADAM BU. İŞİNİ BİTİRİN.",
["Tamam dostlarım, şimdi ganimet çantalarını helikoptere taşıyalım. Oyalanmayın artık!"] = "TAMAM DOSTLARIM, ŞİMDİ GANİMET ÇANTALARINI HELİKOPTERE TAŞIYALIM. OYALANMAYIN ARTIK!",
["Tamam dostlarım, şu gişe kapısını testereyle açıp Kasa Dairesi'nin bulunduğu odaya girin."] = "TAMAM DOSTLARIM, ŞU GİŞE KAPISINI TESTEREYLE AÇIP KASA DAİRESİ'NİN BULUNDUĞU ODAYA GİRİN.",
["Tamam dostlarım. Bu işi sakin sakin bitirelim. Önce güvenlik girişini geçmeliyiz. Çok zor olmasa gerek ama gidip kapılara bir bakın."] = "TAMAM DOSTLARIM. BU İŞİ SAKİN SAKİN BİTİRELİM. ÖNCE GÜVENLİK GİRİŞİNİ GEÇMELİYİZ. ÇOK ZOR OLMASA GEREK AMA GİDİP KAPILARA BİR BAKIN.",
["Tamam dostlarım. Diski servis asansörüyle aşağı gönderin. Shayu'nun adamları ilgilenir."] = "TAMAM DOSTLARIM. DİSKİ SERVİS ASANSÖRÜYLE AŞAĞI GÖNDERİN. SHAYU'NUN ADAMLARI İLGİLENİR.",
["Tamam dostlarım. Etrafa bir bakın."] = "TAMAM DOSTLARIM. ETRAFA BİR BAKIN.",
["Tamam dostlarım. Ganimeti helikoptere yükleyin."] = "TAMAM DOSTLARIM. GANİMETİ HELİKOPTERE YÜKLEYİN.",
["Tamam dostlarım. Kutulardan birini arkeoloji odasında tutuyorlar gibi. Şimdi oraya gidin, olur mu?"] = "TAMAM DOSTLARIM. KUTULARDAN BİRİNİ ARKEOLOJİ ODASINDA TUTUYORLAR GİBİ. ŞİMDİ ORAYA GİDİN, OLUR MU?",
["Tamam dostlarım. Pişirmeye başlayalım. İhtiyar Locke dünyanın en iyi aşçısı değil, o yüzden malı tatmasanız iyi olur, ha?"] = "TAMAM DOSTLARIM. PİŞİRMEYE BAŞLAYALIM. İHTİYAR LOCKE DÜNYANIN EN İYİ AŞÇISI DEĞİL, O YÜZDEN MALI TATMASANIZ İYİ OLUR, HA?",
["Tamam dostum ama şaklabanlığı bırak."] = "TAMAM DOSTUM AMA ŞAKLABANLIĞI BIRAK.",
["Tamam dostum, hemen oraya bir ekip gönderiyorum."] = "TAMAM DOSTUM, HEMEN ORAYA BİR EKİP GÖNDERİYORUM.",
["Tamam dostum, ne yaptığını biliyorsun. Sadece bu bok sonra dönüp götümüzü ısırmasın istiyorum."] = "TAMAM DOSTUM, NE YAPTIĞINI BİLİYORSUN. SADECE BU BOK SONRA DÖNÜP GÖTÜMÜZÜ ISIRMASIN İSTİYORUM.",
["Tamam ekip, Anahtar Kartını bulma vakti. Doğum günü çocuğu hâlâ buralardadır, gidip bulun!"] = "TAMAM EKİP, ANAHTAR KARTINI BULMA VAKTİ. DOĞUM GÜNÜ ÇOCUĞU HÂLÂ BURALARDADIR, GİDİP BULUN!",
["Tamam ekip, Elephant'tan bir bildiri aldık. Bize yardım etmek istediğini iddia ediyor. Görünüşe göre 1900'lerin başında bir Kataru üyesi, onun 'aile yadigârı' dediği bir şeyi çalmış. Bu kişi sonra para verip Antarktika'ya giden ünlü Shacklethorne seferine katılmış. Elephant'a göre varlığı, yolculuğu baştan lanetlemiş. Elephant ketum davransa da bunların tanıdık gelmesi tesadüf değil. Gemi ve mürettebatı kaybolmuştu. Yakın zamanda enkaz, planlanan rotadan uzakta buzların arasında ezilmiş hâlde bulundu. Enkazdan birkaç mil ötede de korkunç biçimde ölmüş görünen mumyalanmış bir ceset, bir kızak ve eser koleksiyonu buldular. Çıkarılan eşyalar bir grup yozlaşmış sosyeteye gizlice açık artırmayla satılacak. Elephant bu eşyalardan birinin mutfaktaki cihazda bize yardım edeceğini söylüyor. Bu iş bana tuhaf hissettiriyor. Fazla yakından tanıdık geliyor."] = "TAMAM EKİP, ELEPHANT'TAN BİR BİLDİRİ ALDIK. BİZE YARDIM ETMEK İSTEDİĞİNİ İDDİA EDİYOR. GÖRÜNÜŞE GÖRE 1900'LERİN BAŞINDA BİR KATARU ÜYESİ, ONUN 'AİLE YADİGÂRI' DEDİĞİ BİR ŞEYİ ÇALMIŞ. BU KİŞİ SONRA PARA VERİP ANTARKTİKA'YA GİDEN ÜNLÜ SHACKLETHORNE SEFERİNE KATILMIŞ. ELEPHANT'A GÖRE VARLIĞI, YOLCULUĞU BAŞTAN LANETLEMİŞ. ELEPHANT KETUM DAVRANSA DA BUNLARIN TANIDIK GELMESİ TESADÜF DEĞİL. GEMİ VE MÜRETTEBATI KAYBOLMUŞTU. YAKIN ZAMANDA ENKAZ, PLANLANAN ROTADAN UZAKTA BUZLARIN ARASINDA EZİLMİŞ HÂLDE BULUNDU. ENKAZDAN BİRKAÇ MİL ÖTEDE DE KORKUNÇ BİÇİMDE ÖLMÜŞ GÖRÜNEN MUMYALANMIŞ BİR CESET, BİR KIZAK VE ESER KOLEKSİYONU BULDULAR. ÇIKARILAN EŞYALAR BİR GRUP YOZLAŞMIŞ SOSYETEYE GİZLİCE AÇIK ARTIRMAYLA SATILACAK. ELEPHANT BU EŞYALARDAN BİRİNİN MUTFAKTAKİ CİHAZDA BİZE YARDIM EDECEĞİNİ SÖYLÜYOR. BU İŞ BANA TUHAF HİSSETTİRİYOR. FAZLA YAKINDAN TANIDIK GELİYOR.",
["Tamam ekip, altyapılarını ortadan kaldırma vakti. Bütün verilerini tuttukları, sıkı korunan ofise girmemiz gerek. Ana sunucuyu bulup ortadan kaldırın."] = "TAMAM EKİP, ALTYAPILARINI ORTADAN KALDIRMA VAKTİ. BÜTÜN VERİLERİNİ TUTTUKLARI, SIKI KORUNAN OFİSE GİRMEMİZ GEREK. ANA SUNUCUYU BULUP ORTADAN KALDIRIN.",
["Tamam ekip, artık defolup gitmeye yetecek kadar aldınız. Daha fazlasını istiyorsanız gözetim odasına erişimim gerekiyor. İçeri girince gerisini hallederim."] = "TAMAM EKİP, ARTIK DEFOLUP GİTMEYE YETECEK KADAR ALDINIZ. DAHA FAZLASINI İSTİYORSANIZ GÖZETİM ODASINA ERİŞİMİM GEREKİYOR. İÇERİ GİRİNCE GERİSİNİ HALLEDERİM.",
["Tamam ekip, beklediğimiz gibi polisler geldi. Binayı basmadan sokak seviyesinde indirmek daha kolay."] = "TAMAM EKİP, BEKLEDİĞİMİZ GİBİ POLİSLER GELDİ. BİNAYI BASMADAN SOKAK SEVİYESİNDE İNDİRMEK DAHA KOLAY.",
["Tamam ekip, biraz elmasın peşine düşüyoruz gibi."] = "TAMAM EKİP, BİRAZ ELMASIN PEŞİNE DÜŞÜYORUZ GİBİ.",
["Tamam ekip, birbirinizi kutlayacak vakit yok. Oradan en... şey... kısa sürede çıkın."] = "TAMAM EKİP, BİRBİRİNİZİ KUTLAYACAK VAKİT YOK. ORADAN EN... ŞEY... KISA SÜREDE ÇIKIN.",
["Tamam ekip, burada bir sürü vitrin var. Kırıp kapın, ganimet çantalarını ağzına kadar doldurun. "] = "TAMAM EKİP, BURADA BİR SÜRÜ VİTRİN VAR. KIRIP KAPIN, GANİMET ÇANTALARINI AĞZINA KADAR DOLDURUN. ",
["Tamam ekip, dikkat dağıtarak Mr Blonde'a yardım edelim. Alışveriş caddesinden çıkıp polisleri uzaklaştırın."] = "TAMAM EKİP, DİKKAT DAĞITARAK MR BLONDE'A YARDIM EDELİM. ALIŞVERİŞ CADDESİNDEN ÇIKIP POLİSLERİ UZAKLAŞTIRIN.",
["Tamam ekip, dikkat dağıtarak Mr Blonde'a yardım edelim. Big John's Burger Joint'in yanındaki pazardan çıkıp polisleri peşinize takın."] = "TAMAM EKİP, DİKKAT DAĞITARAK MR BLONDE'A YARDIM EDELİM. BİG JOHN'S BURGER JOİNT'İN YANINDAKİ PAZARDAN ÇIKIP POLİSLERİ PEŞİNİZE TAKIN.",
["Tamam ekip, dikkat dağıtarak Mr Blonde'a yardım edelim. Jack Rabbit Slim's'in yanındaki pazardan çıkarak polisleri uzaklaştırın."] = "TAMAM EKİP, DİKKAT DAĞITARAK MR BLONDE'A YARDIM EDELİM. JACK RABBİT SLİM'S'İN YANINDAKİ PAZARDAN ÇIKARAK POLİSLERİ UZAKLAŞTIRIN.",
["Tamam ekip, ekipmanınızı hazırlayın. En iyi yaptığımız iş bu, banka soygunu. Ganimet çantalarını kontrol edin, cep telefonlarını evde bırakın, eldivenleri alın, silahları doldurun ve parayı almaya hazır olun."] = "TAMAM EKİP, EKİPMANINIZI HAZIRLAYIN. EN İYİ YAPTIĞIMIZ İŞ BU, BANKA SOYGUNU. GANİMET ÇANTALARINI KONTROL EDİN, CEP TELEFONLARINI EVDE BIRAKIN, ELDİVENLERİ ALIN, SİLAHLARI DOLDURUN VE PARAYI ALMAYA HAZIR OLUN.",
["Tamam ekip, eşyalarınızı toplayıp Washington D.C.'ye gidin. Sturr adında bir beyefendinin peşindeyiz. Bay Sturr, pis ve kocaman bir şirketle anlaşarak çok para kazanmak isteyen sinsi bir IRS çalışanı. Ama bence o parayı daha iyi kullanabiliriz. Yapalım."] = "TAMAM EKİP, EŞYALARINIZI TOPLAYIP WASHINGTON D.C.'YE GİDİN. STURR ADINDA BİR BEYEFENDİNİN PEŞİNDEYİZ. BAY STURR, PİS VE KOCAMAN BİR ŞİRKETLE ANLAŞARAK ÇOK PARA KAZANMAK İSTEYEN SİNSİ BİR IRS ÇALIŞANI. AMA BENCE O PARAYI DAHA İYİ KULLANABİLİRİZ. YAPALIM.",
["Tamam ekip, geliyorlar! Savunmak için iyi bir mevzi bulun! Neredeyse bitti!"] = "TAMAM EKİP, GELİYORLAR! SAVUNMAK İÇİN İYİ BİR MEVZİ BULUN! NEREDEYSE BİTTİ!",
["Tamam ekip, güzel. Şimdi sıkı tutunun."] = "TAMAM EKİP, GÜZEL. ŞİMDİ SIKI TUTUNUN.",
["Tamam ekip, hedef bu. İnsanları yere yatırın, kameraları indirin, matkabı çalıştırın. Noktada görüşürüz."] = "TAMAM EKİP, HEDEF BU. İNSANLARI YERE YATIRIN, KAMERALARI İNDİRİN, MATKABI ÇALIŞTIRIN. NOKTADA GÖRÜŞÜRÜZ.",
["Tamam ekip, hâlâ kaçabiliriz. Hazır olduğunuzda minibüse."] = "TAMAM EKİP, HÂLÂ KAÇABİLİRİZ. HAZIR OLDUĞUNUZDA MİNİBÜSE.",
["Tamam ekip, ileride Chavez'in evi var."] = "TAMAM EKİP, İLERİDE CHAVEZ'İN EVİ VAR.",
["Tamam ekip, işte bu. Kamyonlar gitmeye hazırlanıyor gibi. Acele edip konteyneri taşıyanı bulun. GPS hazır. Harekete geçin."] = "TAMAM EKİP, İŞTE BU. KAMYONLAR GİTMEYE HAZIRLANIYOR GİBİ. ACELE EDİP KONTEYNERİ TAŞIYANI BULUN. GPS HAZIR. HAREKETE GEÇİN.",
["Tamam ekip, konsolun sistemini kırmalısınız."] = "TAMAM EKİP, KONSOLUN SİSTEMİNİ KIRMALISINIZ.",
["Tamam ekip, ne için geldiğimizi biliyorsunuz. Gidin!"] = "TAMAM EKİP, NE İÇİN GELDİĞİMİZİ BİLİYORSUNUZ. GİDİN!",
["Tamam ekip, yola koyulalım. The Butcher bu işte ciddi... Unutmayın, Ernesto Sosa'yı öldürüp ganimeti çalmanız gerek."] = "TAMAM EKİP, YOLA KOYULALIM. THE BUTCHER BU İŞTE CİDDİ... UNUTMAYIN, ERNESTO SOSA'YI ÖLDÜRÜP GANİMETİ ÇALMANIZ GEREK.",
["Tamam ekip. Aynı şey. Çıkıp kafesi kurun."] = "TAMAM EKİP. AYNI ŞEY. ÇIKIP KAFESİ KURUN.",
["Tamam ekip. Bu kuyumcunun birkaç vitrininde orta değerde mücevher ve altın sergileniyor. "] = "TAMAM EKİP. BU KUYUMCUNUN BİRKAÇ VİTRİNİNDE ORTA DEĞERDE MÜCEVHER VE ALTIN SERGİLENİYOR. ",
["Tamam ekip. Geldik."] = "TAMAM EKİP. GELDİK.",
["Tamam ekip. Gösteri yapma vakti."] = "TAMAM EKİP. GÖSTERİ YAPMA VAKTİ.",
["Tamam ekip. Kereste fabrikasına girmenin bir yolunu bulmalıyız. Delilik olabilir ama az önce hacklediğimiz uçaksavarı kullansak? Yönünü değiştirip duvarı havaya uçursak?"] = "TAMAM EKİP. KERESTE FABRİKASINA GİRMENİN BİR YOLUNU BULMALIYIZ. DELİLİK OLABİLİR AMA AZ ÖNCE HACKLEDİĞİMİZ UÇAKSAVARI KULLANSAK? YÖNÜNÜ DEĞİŞTİRİP DUVARI HAVAYA UÇURSAK?",
["Tamam ekip. Nasıl olduğunu biliyorsunuz, banka baskını. Telefonları bırakın, zihninizi tam alarma alın, eldivenleri geçirin. Bu banka şubesini vuracağız. Şehrin her yerindeler."] = "TAMAM EKİP. NASIL OLDUĞUNU BİLİYORSUNUZ, BANKA BASKINI. TELEFONLARI BIRAKIN, ZİHNİNİZİ TAM ALARMA ALIN, ELDİVENLERİ GEÇİRİN. BU BANKA ŞUBESİNİ VURACAĞIZ. ŞEHRİN HER YERİNDELER.",
["Tamam ekip. Polisteki köstebeğim bunu halleder. Adamlarını temizliğe yollayıp bölgenin arandığını, bir şey bulunmadığını bildirecek. Burada olduğunuzu kimse bilmeyecek. Rahatlayabilirsiniz."] = "TAMAM EKİP. POLİSTEKİ KÖSTEBEĞİM BUNU HALLEDER. ADAMLARINI TEMİZLİĞE YOLLAYIP BÖLGENİN ARANDIĞINI, BİR ŞEY BULUNMADIĞINI BİLDİRECEK. BURADA OLDUĞUNUZU KİMSE BİLMEYECEK. RAHATLAYABİLİRSİNİZ.",
["Tamam ekip. Tren sahası tam önünüzde. İçeri sızabileceğiniz birkaç yol olmalı, seçimlerinizi akıllıca yapın."] = "TAMAM EKİP. TREN SAHASI TAM ÖNÜNÜZDE. İÇERİ SIZABİLECEĞİNİZ BİRKAÇ YOL OLMALI, SEÇİMLERİNİZİ AKILLICA YAPIN.",
["Tamam ekip. Uygun bir kodun bulunabileceği birkaç terminal buldum. Sistemlerini biraz kırmanız gerekiyor."] = "TAMAM EKİP. UYGUN BİR KODUN BULUNABİLECEĞİ BİRKAÇ TERMİNAL BULDUM. SİSTEMLERİNİ BİRAZ KIRMANIZ GEREKİYOR.",
["Tamam ekip..."] = "TAMAM EKİP...",
["Tamam ekip... Locke'u size bağlıyorum."] = "TAMAM EKİP... LOCKE'U SİZE BAĞLIYORUM.",
["Tamam gerzekler, Vlad için bu kadarı yeter. Hazır hissettiğinizde çıkın oradan."] = "TAMAM GERZEKLER, VLAD İÇİN BU KADARI YETER. HAZIR HİSSETTİĞİNİZDE ÇIKIN ORADAN.",
["Tamam gerzekler, yapalım şu işi. Sunucu odasında Vlad'in hangi konteynerde olduğunu bulabileceğiniz bir kamera yayını var. Konteynerin tesisteki yerini bulmak için kontrol odasında eşleşen bir sevkiyat manifestosu arayın."] = "TAMAM GERZEKLER, YAPALIM ŞU İŞİ. SUNUCU ODASINDA VLAD'İN HANGİ KONTEYNERDE OLDUĞUNU BULABİLECEĞİNİZ BİR KAMERA YAYINI VAR. KONTEYNERİN TESİSTEKİ YERİNİ BULMAK İÇİN KONTROL ODASINDA EŞLEŞEN BİR SEVKİYAT MANİFESTOSU ARAYIN.",
["Tamam gerzekler. Sizi bir-"] = "TAMAM GERZEKLER. SİZİ BİR-",
["Tamam harika, şimdi sonraki adım."] = "TAMAM HARİKA, ŞİMDİ SONRAKİ ADIM.",
["Tamam herkes, şoför burada ama sokağın diğer tarafına park etmiş! Şu yaya geçidinden karşıya geçin."] = "TAMAM HERKES, ŞOFÖR BURADA AMA SOKAĞIN DİĞER TARAFINA PARK ETMİŞ! ŞU YAYA GEÇİDİNDEN KARŞIYA GEÇİN.",
["Tamam hödükler, Vlad'ın intikamını alırken bir bok yığını para kazanma vakti. The Black Cat birkaç saate uluslararası sularda olacak, içini boşaltacağız. Jiu Feng'in içeride barmen olarak çalışan bir adamı var. Bize ekipman ve geminin işleyişi hakkında bilgi verecek. Triad özellikle savunmasız olduğu için Vlad'a işkence eden aşağılık Xun Kang'ı gemiye koyduklarını biliyoruz, en iyi adamlarından biriymiş. Gemideki kumarhaneyi Li Deng adlı bir aptalın yönettiğini de biliyoruz. Anlaşılan gürültücü bir soytarıymış, Golden Dagger içinde pek saygı görmüyormuş. Muhtemelen güvenlik yetkisini paylaşıyorlar. Gemiye binince işi sıkı tutmalısınız. Sahil güvenlik bölgede devriye geziyor, siz ‘Bak, lanet bir yüzen porsuk!’ diyemeden adamlarını gemiye çıkarırlar. Yani saçmalamak yok, tamam mı?"] = "TAMAM HÖDÜKLER, VLAD'IN İNTİKAMINI ALIRKEN BİR BOK YIĞINI PARA KAZANMA VAKTİ. THE BLACK CAT BİRKAÇ SAATE ULUSLARARASI SULARDA OLACAK, İÇİNİ BOŞALTACAĞIZ. JIU FENG'İN İÇERİDE BARMEN OLARAK ÇALIŞAN BİR ADAMI VAR. BİZE EKİPMAN VE GEMİNİN İŞLEYİŞİ HAKKINDA BİLGİ VERECEK. TRİAD ÖZELLİKLE SAVUNMASIZ OLDUĞU İÇİN VLAD'A İŞKENCE EDEN AŞAĞILIK XUN KANG'I GEMİYE KOYDUKLARINI BİLİYORUZ, EN İYİ ADAMLARINDAN BİRİYMİŞ. GEMİDEKİ KUMARHANEYİ Lİ DENG ADLI BİR APTALIN YÖNETTİĞİNİ DE BİLİYORUZ. ANLAŞILAN GÜRÜLTÜCÜ BİR SOYTARIYMIŞ, GOLDEN DAGGER İÇİNDE PEK SAYGI GÖRMÜYORMUŞ. MUHTEMELEN GÜVENLİK YETKİSİNİ PAYLAŞIYORLAR. GEMİYE BİNİNCE İŞİ SIKI TUTMALISINIZ. SAHİL GÜVENLİK BÖLGEDE DEVRİYE GEZİYOR, SİZ ‘BAK, LANET BİR YÜZEN PORSUK!’ DİYEMEDEN ADAMLARINI GEMİYE ÇIKARIRLAR. YANİ SAÇMALAMAK YOK, TAMAM MI?",
["Tamam hödükler, gidip ofisini bulun!"] = "TAMAM HÖDÜKLER, GİDİP OFİSİNİ BULUN!",
["Tamam hödükler. Lobideki güvenliği geçip asansöre ulaşmanız gerekiyor. Muhafızlar, kameralar ve metal dedektörleri var. Ne yapacağınızı biliyorsunuz, değil mi? Harekete geçin."] = "TAMAM HÖDÜKLER. LOBİDEKİ GÜVENLİĞİ GEÇİP ASANSÖRE ULAŞMANIZ GEREKİYOR. MUHAFIZLAR, KAMERALAR VE METAL DEDEKTÖRLERİ VAR. NE YAPACAĞINIZI BİLİYORSUNUZ, DEĞİL Mİ? HAREKETE GEÇİN.",
["Tamam hödükler. O tünel girişini bulma vakti. "] = "TAMAM HÖDÜKLER. O TÜNEL GİRİŞİNİ BULMA VAKTİ. ",
["Tamam korsanlar, gemiye çıkıp ganimeti alın. Sessiz kalın."] = "TAMAM KORSANLAR, GEMİYE ÇIKIP GANİMETİ ALIN. SESSİZ KALIN.",
["Tamam kovboylar, sizi burada bırakıyorum. Malları almam için çağırana kadar etrafta döneceğim."] = "TAMAM KOVBOYLAR, SİZİ BURADA BIRAKIYORUM. MALLARI ALMAM İÇİN ÇAĞIRANA KADAR ETRAFTA DÖNECEĞİM.",
["Tamam kumarbazlar. Kumar oynama vakti."] = "TAMAM KUMARBAZLAR. KUMAR OYNAMA VAKTİ.",
["Tamam millet! Bir çanta daha. Hector'ı memnun etmek için tek çanta lazım."] = "TAMAM MİLLET! BİR ÇANTA DAHA. HECTOR'I MEMNUN ETMEK İÇİN TEK ÇANTA LAZIM.",
["Tamam millet! Sizi çıkarmak için bir minibüs geliyor!"] = "TAMAM MİLLET! SİZİ ÇIKARMAK İÇİN BİR MİNİBÜS GELİYOR!",
["Tamam millet, ASIM geçildi. İzlerimiz artık silindi."] = "TAMAM MİLLET, ASIM GEÇİLDİ. İZLERİMİZ ARTIK SİLİNDİ.",
["Tamam millet, Big John's Burger Joint tarafından çıkarsanız umarım polisler peşinize takılır da Blonde arabayı oradan çıkarabilir."] = "TAMAM MİLLET, BİG JOHN'S BURGER JOİNT TARAFINDAN ÇIKARSANIZ UMARIM POLİSLER PEŞİNİZE TAKILIR DA BLONDE ARABAYI ORADAN ÇIKARABİLİR.",
["Tamam millet, Bile dönene kadar mevziyi koruma vakti. Cehennemi yaşatın!"] = "TAMAM MİLLET, BILE DÖNENE KADAR MEVZİYİ KORUMA VAKTİ. CEHENNEMİ YAŞATIN!",
["Tamam millet, Hector için bir çanta daha lazım, sonra gidebiliriz."] = "TAMAM MİLLET, HECTOR İÇİN BİR ÇANTA DAHA LAZIM, SONRA GİDEBİLİRİZ.",
["Tamam millet, Hector'la konuştum. Mendoza'nın ileri gelenleri ülkeden kaçıyor ama Hector henüz gitmelerine razı değil. Nereye gittiklerini öğrenmek istiyor. "] = "TAMAM MİLLET, HECTOR'LA KONUŞTUM. MENDOZA'NIN İLERİ GELENLERİ ÜLKEDEN KAÇIYOR AMA HECTOR HENÜZ GİTMELERİNE RAZI DEĞİL. NEREYE GİTTİKLERİNİ ÖĞRENMEK İSTİYOR. ",
["Tamam millet, Jack Rabbit Slim's tarafından çıkarsanız umarım polisler peşinize takılır da Blonde arabayı oradan çıkarabilir."] = "TAMAM MİLLET, JACK RABBİT SLİM'S TARAFINDAN ÇIKARSANIZ UMARIM POLİSLER PEŞİNİZE TAKILIR DA BLONDE ARABAYI ORADAN ÇIKARABİLİR.",
["Tamam millet, Vlad size bankaya giriş yolu ayarladı."] = "TAMAM MİLLET, VLAD SİZE BANKAYA GİRİŞ YOLU AYARLADI.",
["Tamam millet, Vlad tüyo verdi. Bir gece kulübü soyacağız."] = "TAMAM MİLLET, VLAD TÜYO VERDİ. BİR GECE KULÜBÜ SOYACAĞIZ.",
["Tamam millet, Vlad'dan bir iş daha aldık. Gece kulübü soyacağız."] = "TAMAM MİLLET, VLAD'DAN BİR İŞ DAHA ALDIK. GECE KULÜBÜ SOYACAĞIZ.",
["Tamam millet, adamım banka kasa dairesi için termal matkabı otoparka sakladı. Önce onu alın. Muhafızlara dikkat edin, kameraları kollayın; kamera varsa genelde bir güvenlik odası da vardır... Para vakti."] = "TAMAM MİLLET, ADAMIM BANKA KASA DAİRESİ İÇİN TERMAL MATKABI OTOPARKA SAKLADI. ÖNCE ONU ALIN. MUHAFIZLARA DİKKAT EDİN, KAMERALARI KOLLAYIN; KAMERA VARSA GENELDE BİR GÜVENLİK ODASI DA VARDIR... PARA VAKTİ.",
["Tamam millet, adamım bankayı vurmak için uygun bir zaman olduğunu söylüyor. Anlaşılan Harvest & Trustee banka müdürü ağzını kapalı tutmalıymış. İçeride her şey olabilir."] = "TAMAM MİLLET, ADAMIM BANKAYI VURMAK İÇİN UYGUN BİR ZAMAN OLDUĞUNU SÖYLÜYOR. ANLAŞILAN HARVEST & TRUSTEE BANKA MÜDÜRÜ AĞZINI KAPALI TUTMALIYMIŞ. İÇERİDE HER ŞEY OLABİLİR.",
["Tamam millet, alternatif kaçış helikopteri yolladım. Yakında burada!"] = "TAMAM MİLLET, ALTERNATİF KAÇIŞ HELİKOPTERİ YOLLADIM. YAKINDA BURADA!",
["Tamam millet, ağır işti! Doğru motor teslim edildi, şimdi kilit altında. Paramız geliyor!"] = "TAMAM MİLLET, AĞIR İŞTİ! DOĞRU MOTOR TESLİM EDİLDİ, ŞİMDİ KİLİT ALTINDA. PARAMIZ GELİYOR!",
["Tamam millet, balonu yeniden kaldırmanız gerekecek!"] = "TAMAM MİLLET, BALONU YENİDEN KALDIRMANIZ GEREKECEK!",
["Tamam millet, banka orada. İçinde ne var bilmiyorum ama güzel olacak..."] = "TAMAM MİLLET, BANKA ORADA. İÇİNDE NE VAR BİLMİYORUM AMA GÜZEL OLACAK...",
["Tamam millet, bankaya girin. Kasa Dairesi'ni bulup matkapla açın. Kimsenin alarmı çalıştırmasına ya da kaçmasına izin vermeyin."] = "TAMAM MİLLET, BANKAYA GİRİN. KASA DAİRESİ'Nİ BULUP MATKAPLA AÇIN. KİMSENİN ALARMI ÇALIŞTIRMASINA YA DA KAÇMASINA İZİN VERMEYİN.",
["Tamam millet, bağlantım sağ olsun, banka kasa dairesini açmak için gereken termal matkabı otoparkta bir yere saklamış. Alın, sonra kasa dairesine girişin."] = "TAMAM MİLLET, BAĞLANTIM SAĞ OLSUN, BANKA KASA DAİRESİNİ AÇMAK İÇİN GEREKEN TERMAL MATKABI OTOPARKTA BİR YERE SAKLAMIŞ. ALIN, SONRA KASA DAİRESİNE GİRİŞİN.",
["Tamam millet, bu işin en iyisi sizsiniz. D.C.'ye ciddi olduğumuzu gösterelim. Para vakti."] = "TAMAM MİLLET, BU İŞİN EN İYİSİ SİZSİNİZ. D.C.'YE CİDDİ OLDUĞUMUZU GÖSTERELİM. PARA VAKTİ.",
["Tamam millet, burada neyin tehlikede olduğunu biliyorsunuz. McKendrick'in seçimleri kazanmak için o paraya ihtiyacı var. Çalabilirseniz ayağının altından halıyı çekmiş olursunuz. Eğlencesini bozalım, hevesini kursağında bırakalım. O nankör piçin yaptığını yanına bırakmayalım. O parayı alın. Charon'ın verdiği dosyada bir şey daha buldum. Yatta bir sunucu var. İçinde yasa dışı yabancı banka hesaplarının şifreleri bulunuyor, bazılarını McKendrick de kullanıyor. O sunucuyu çalarsanız güzel para kaldırırız. (duraklar) Ha, evet... Az kalsın unutuyordum... Bu gece yatta McKendrick için bağış gecesi var. Televizyon falan da olacak. Ama parti daha çok üst güvertede, o yüzden sessizce sızarsanız kimse fark etmeden girip çıkabilirsiniz."] = "TAMAM MİLLET, BURADA NEYİN TEHLİKEDE OLDUĞUNU BİLİYORSUNUZ. MCKENDRİCK'İN SEÇİMLERİ KAZANMAK İÇİN O PARAYA İHTİYACI VAR. ÇALABİLİRSENİZ AYAĞININ ALTINDAN HALIYI ÇEKMİŞ OLURSUNUZ. EĞLENCESİNİ BOZALIM, HEVESİNİ KURSAĞINDA BIRAKALIM. O NANKÖR PİÇİN YAPTIĞINI YANINA BIRAKMAYALIM. O PARAYI ALIN. CHARON'IN VERDİĞİ DOSYADA BİR ŞEY DAHA BULDUM. YATTA BİR SUNUCU VAR. İÇİNDE YASA DIŞI YABANCI BANKA HESAPLARININ ŞİFRELERİ BULUNUYOR, BAZILARINI MCKENDRİCK DE KULLANIYOR. O SUNUCUYU ÇALARSANIZ GÜZEL PARA KALDIRIRIZ. (DURAKLAR) HA, EVET... AZ KALSIN UNUTUYORDUM... BU GECE YATTA MCKENDRİCK İÇİN BAĞIŞ GECESİ VAR. TELEVİZYON FALAN DA OLACAK. AMA PARTİ DAHA ÇOK ÜST GÜVERTEDE, O YÜZDEN SESSİZCE SIZARSANIZ KİMSE FARK ETMEDEN GİRİP ÇIKABİLİRSİNİZ.",
["Tamam millet, burayı arayın. Bir yerde Kasaları var, muhtemelen onun içindedir."] = "TAMAM MİLLET, BURAYI ARAYIN. BİR YERDE KASALARI VAR, MUHTEMELEN ONUN İÇİNDEDİR.",
["Tamam millet, dikkat dağıtıp Mr Blonde'a yardım edelim. Çarşıdan dışarı çıkarak polisleri peşinize çekin."] = "TAMAM MİLLET, DİKKAT DAĞITIP MR BLONDE'A YARDIM EDELİM. ÇARŞIDAN DIŞARI ÇIKARAK POLİSLERİ PEŞİNİZE ÇEKİN.",
["Tamam millet, doğru anda anlaşmayı bozun. Sonra Alex limuzini oradan kaldıracak. Hazır olun!"] = "TAMAM MİLLET, DOĞRU ANDA ANLAŞMAYI BOZUN. SONRA ALEX LİMUZİNİ ORADAN KALDIRACAK. HAZIR OLUN!",
["Tamam millet, etrafı arayın. Adresin orada bir yerde olduğunu biliyorum."] = "TAMAM MİLLET, ETRAFI ARAYIN. ADRESİN ORADA BİR YERDE OLDUĞUNU BİLİYORUM.",
["Tamam millet, geldim. Demek bu arabaları mahvetmemiz gerek, öyle mi? Şunu suya atalım. Mıknatısı bağlayın!"] = "TAMAM MİLLET, GELDİM. DEMEK BU ARABALARI MAHVETMEMİZ GEREK, ÖYLE Mİ? ŞUNU SUYA ATALIM. MIKNATISI BAĞLAYIN!",
["Tamam millet, girdiniz."] = "TAMAM MİLLET, GİRDİNİZ.",
["Tamam millet, girip Kasa Dairesini arıyoruz. Kartel olsun olmasın, sonuçta banka, değil mi?"] = "TAMAM MİLLET, GİRİP KASA DAİRESİNİ ARIYORUZ. KARTEL OLSUN OLMASIN, SONUÇTA BANKA, DEĞİL Mİ?",
["Tamam millet, gitme vakti!"] = "TAMAM MİLLET, GİTME VAKTİ!",
["Tamam millet, harika iş ama siz ---. Hareket var ---."] = "TAMAM MİLLET, HARİKA İŞ AMA SİZ ---. HAREKET VAR ---.",
["Tamam millet, her şey plana göre giderse fark edilmeden çıkabiliriz. Kalabalığa karışıp sıvışın."] = "TAMAM MİLLET, HER ŞEY PLANA GÖRE GİDERSE FARK EDİLMEDEN ÇIKABİLİRİZ. KALABALIĞA KARIŞIP SIVIŞIN.",
["Tamam millet, herkes trene."] = "TAMAM MİLLET, HERKES TRENE.",
["Tamam millet, ilk parti boşaltıldı. Birazdan geri geliyorum..."] = "TAMAM MİLLET, İLK PARTİ BOŞALTILDI. BİRAZDAN GERİ GELİYORUM...",
["Tamam millet, iyi bir nokta. Tren sahasını neredeyse tamamen görebiliyorsunuz. Devriye muhafızlarını ve kameraları takip edin."] = "TAMAM MİLLET, İYİ BİR NOKTA. TREN SAHASINI NEREDEYSE TAMAMEN GÖREBİLİYORSUNUZ. DEVRİYE MUHAFIZLARINI VE KAMERALARI TAKİP EDİN.",
["Tamam millet, içeri girip eserleri bulun. Kırmızı çıkartmalı tabloları istiyoruz. Muhafızlara ve kameralara dikkat edin."] = "TAMAM MİLLET, İÇERİ GİRİP ESERLERİ BULUN. KIRMIZI ÇIKARTMALI TABLOLARI İSTİYORUZ. MUHAFIZLARA VE KAMERALARA DİKKAT EDİN.",
["Tamam millet, içerideki adamım Kasa Dairesi için gereken termal matkabı arka tarafa sakladı. Etrafı kolaçan edip bulun. Hazır olunca Kasa Dairesi'ne yönelin. Bu iş altın gibi olacak."] = "TAMAM MİLLET, İÇERİDEKİ ADAMIM KASA DAİRESİ İÇİN GEREKEN TERMAL MATKABI ARKA TARAFA SAKLADI. ETRAFI KOLAÇAN EDİP BULUN. HAZIR OLUNCA KASA DAİRESİ'NE YÖNELİN. BU İŞ ALTIN GİBİ OLACAK.",
["Tamam millet, içerideki adamım kasa dairesi için gereken termal kargıyı arka tarafa sakladı. Etrafı araştırıp bulun."] = "TAMAM MİLLET, İÇERİDEKİ ADAMIM KASA DAİRESİ İÇİN GEREKEN TERMAL KARGIYI ARKA TARAFA SAKLADI. ETRAFI ARAŞTIRIP BULUN.",
["Tamam millet, işe yaradı! Ev açıldı!"] = "TAMAM MİLLET, İŞE YARADI! EV AÇILDI!",
["Tamam millet, işte geliyorlar. O vinci hareket ettirin!"] = "TAMAM MİLLET, İŞTE GELİYORLAR. O VİNCİ HAREKET ETTİRİN!",
["Tamam millet, kamyonlar gitmek üzere. Oy makineleri hangisindeyse bulup GPS'i takın. Buralarda ipucu olmalı."] = "TAMAM MİLLET, KAMYONLAR GİTMEK ÜZERE. OY MAKİNELERİ HANGİSİNDEYSE BULUP GPS'İ TAKIN. BURALARDA İPUCU OLMALI.",
["Tamam millet, kamyonlar her an gidebilir. Oy makineleri hangisindeyse bulun ve GPS takip cihazını takın. Buralarda ipucu verebilecek bir şey olmalı."] = "TAMAM MİLLET, KAMYONLAR HER AN GİDEBİLİR. OY MAKİNELERİ HANGİSİNDEYSE BULUN VE GPS TAKİP CİHAZINI TAKIN. BURALARDA İPUCU VEREBİLECEK BİR ŞEY OLMALI.",
["Tamam millet, kapıları açın. Levye gibi bir şey bulun."] = "TAMAM MİLLET, KAPILARI AÇIN. LEVYE GİBİ BİR ŞEY BULUN.",
["Tamam millet, kendinize gelin. Yakalayın onu."] = "TAMAM MİLLET, KENDİNİZE GELİN. YAKALAYIN ONU.",
["Tamam millet, kimlik doğrulama bitmek üzere. Zamanlayıcıyı gözleyin."] = "TAMAM MİLLET, KİMLİK DOĞRULAMA BİTMEK ÜZERE. ZAMANLAYICIYI GÖZLEYİN.",
["Tamam millet, komşulara görünmeyin. Kimse mavilileri çağırmasın."] = "TAMAM MİLLET, KOMŞULARA GÖRÜNMEYİN. KİMSE MAVİLİLERİ ÇAĞIRMASIN.",
["Tamam millet, kuleden ayrılıp buradan çıkma vakti. Köprü boyunca ilerleyin!"] = "TAMAM MİLLET, KULEDEN AYRILIP BURADAN ÇIKMA VAKTİ. KÖPRÜ BOYUNCA İLERLEYİN!",
["Tamam millet, kulübe bakan ofis işte orada."] = "TAMAM MİLLET, KULÜBE BAKAN OFİS İŞTE ORADA.",
["Tamam millet, kusursuz bir iş istiyorum. Önce matkabı otoparktan alın. Sonra içeri girip Kasa Dairesi'ne yönelin. Güvenlikçilere ve kameralara dikkat edin. "] = "TAMAM MİLLET, KUSURSUZ BİR İŞ İSTİYORUM. ÖNCE MATKABI OTOPARKTAN ALIN. SONRA İÇERİ GİRİP KASA DAİRESİ'NE YÖNELİN. GÜVENLİKÇİLERE VE KAMERALARA DİKKAT EDİN. ",
["Tamam millet, kusursuz bir vurgun istiyorum. Bu ekip için 10 dakikada girip çıkmak sorun olmaz. Hızlanalım."] = "TAMAM MİLLET, KUSURSUZ BİR VURGUN İSTİYORUM. BU EKİP İÇİN 10 DAKİKADA GİRİP ÇIKMAK SORUN OLMAZ. HIZLANALIM.",
["Tamam millet, matkap kilitle uğraşırken biz kapıların manyetik mührünü halledeceğiz. Uygun bir terminal bulayım."] = "TAMAM MİLLET, MATKAP KİLİTLE UĞRAŞIRKEN BİZ KAPILARIN MANYETİK MÜHRÜNÜ HALLEDECEĞİZ. UYGUN BİR TERMİNAL BULAYIM.",
["Tamam millet, o altının peşine düşün!"] = "TAMAM MİLLET, O ALTININ PEŞİNE DÜŞÜN!",
["Tamam millet, o kapıyı açın! Bakalım içeride kim var."] = "TAMAM MİLLET, O KAPIYI AÇIN! BAKALIM İÇERİDE KİM VAR.",
["Tamam millet, oradan çıkma vakti geldi."] = "TAMAM MİLLET, ORADAN ÇIKMA VAKTİ GELDİ.",
["Tamam millet, oradan çıkmanın tek yolu o kapılar."] = "TAMAM MİLLET, ORADAN ÇIKMANIN TEK YOLU O KAPILAR.",
["Tamam millet, size ne ayarladım söyleyeyim: Bir kaçış helikopteri buldum, sonra teşekkür edersiniz. Yolda!"] = "TAMAM MİLLET, SİZE NE AYARLADIM SÖYLEYEYİM: BİR KAÇIŞ HELİKOPTERİ BULDUM, SONRA TEŞEKKÜR EDERSİNİZ. YOLDA!",
["Tamam millet, sizi alacak araç geldi. Şu geçitten geçin; sokağın öbür tarafında."] = "TAMAM MİLLET, SİZİ ALACAK ARAÇ GELDİ. ŞU GEÇİTTEN GEÇİN; SOKAĞIN ÖBÜR TARAFINDA.",
["Tamam millet, sizi alacak şoför geldi! Arkanızdaki sokakta!"] = "TAMAM MİLLET, SİZİ ALACAK ŞOFÖR GELDİ! ARKANIZDAKİ SOKAKTA!",
["Tamam millet, sizi almak için şimdi geri dönüyorum."] = "TAMAM MİLLET, SİZİ ALMAK İÇİN ŞİMDİ GERİ DÖNÜYORUM.",
["Tamam millet, sıradakini bağlayın."] = "TAMAM MİLLET, SIRADAKİNİ BAĞLAYIN.",
["Tamam millet, telefonu açın. Şu takası aradan çıkaralım."] = "TAMAM MİLLET, TELEFONU AÇIN. ŞU TAKASI ARADAN ÇIKARALIM.",
["Tamam millet, yeniden bağlandım."] = "TAMAM MİLLET, YENİDEN BAĞLANDIM.",
["Tamam millet, çantaları almaya bir tekne geliyor. Önce gidip onları taşıma için güvene alın."] = "TAMAM MİLLET, ÇANTALARI ALMAYA BİR TEKNE GELİYOR. ÖNCE GİDİP ONLARI TAŞIMA İÇİN GÜVENE ALIN.",
["Tamam millet, çantaları minibüse götürün!"] = "TAMAM MİLLET, ÇANTALARI MİNİBÜSE GÖTÜRÜN!",
["Tamam millet, çatıdan karşıya geçin!"] = "TAMAM MİLLET, ÇATIDAN KARŞIYA GEÇİN!",
["Tamam millet, çıkma vakti. Kuleden ayrılıp köprü boyunca ilerleyin."] = "TAMAM MİLLET, ÇIKMA VAKTİ. KULEDEN AYRILIP KÖPRÜ BOYUNCA İLERLEYİN.",
["Tamam millet, üç dakikalık fırsatımız var. Harekete geçin!"] = "TAMAM MİLLET, ÜÇ DAKİKALIK FIRSATIMIZ VAR. HAREKETE GEÇİN!",
["Tamam millet, şimdi Ernesto'nun zemin kasasını soyacağız. Eminim harika şeylerle doludur. Araziye girdiğiniz yerin yakınında saklı vinçler var. Gidip alın ve bağlayın."] = "TAMAM MİLLET, ŞİMDİ ERNESTO'NUN ZEMİN KASASINI SOYACAĞIZ. EMİNİM HARİKA ŞEYLERLE DOLUDUR. ARAZİYE GİRDİĞİNİZ YERİN YAKININDA SAKLI VİNÇLER VAR. GİDİP ALIN VE BAĞLAYIN.",
["Tamam millet, şimdi dışarı çıkıp kafesi kurun!"] = "TAMAM MİLLET, ŞİMDİ DIŞARI ÇIKIP KAFESİ KURUN!",
["Tamam millet, şoför geldi! Arkanızdaki sokakta!"] = "TAMAM MİLLET, ŞOFÖR GELDİ! ARKANIZDAKİ SOKAKTA!",
["Tamam millet. 57 numaralı konteyneri uzaktan açıyorum. Koşmaya hazır olun."] = "TAMAM MİLLET. 57 NUMARALI KONTEYNERİ UZAKTAN AÇIYORUM. KOŞMAYA HAZIR OLUN.",
["Tamam millet. Adımınıza dikkat edin. Komşular polisi hızlı aramaya koymuştur."] = "TAMAM MİLLET. ADIMINIZA DİKKAT EDİN. KOMŞULAR POLİSİ HIZLI ARAMAYA KOYMUŞTUR.",
["Tamam millet. Araba parçalıyormuşuz. Mıknatısı bağlayın, bu yüzmeye gidiyor!"] = "TAMAM MİLLET. ARABA PARÇALIYORMUŞUZ. MIKNATISI BAĞLAYIN, BU YÜZMEYE GİDİYOR!",
["Tamam millet. Bile EMP'yi kereste fabrikasının hemen dışına bıraktı. Gidip alın!"] = "TAMAM MİLLET. BILE EMP'Yİ KERESTE FABRİKASININ HEMEN DIŞINA BIRAKTI. GİDİP ALIN!",
["Tamam millet. Cabot'ın adamları dükkânın dışında sizi bekleyecek. Söylediğine göre hızlı ve kolay olmalı. Bu profesyonel LA gangsterlerine Payday Gang'in neler yapabildiğini gösterin."] = "TAMAM MİLLET. CABOT'IN ADAMLARI DÜKKÂNIN DIŞINDA SİZİ BEKLEYECEK. SÖYLEDİĞİNE GÖRE HIZLI VE KOLAY OLMALI. BU PROFESYONEL LA GANGSTERLERİNE PAYDAY GANG'İN NELER YAPABİLDİĞİNİ GÖSTERİN.",
["Tamam millet. Denekleri arayıp tarayıcıya götürmelisiniz. Aşağı yukarı aynı görünüyor olmaları lazım."] = "TAMAM MİLLET. DENEKLERİ ARAYIP TARAYICIYA GÖTÜRMELİSİNİZ. AŞAĞI YUKARI AYNI GÖRÜNÜYOR OLMALARI LAZIM.",
["Tamam millet. Doğrudan kaynağa gidiyoruz. Orada ihtiyacımız olan bilgi var, bir de yakınında olmak istemeyeceğimiz kadar çok kolluk kuvveti. Sunucu odalarını bulup bankayla ilgili bilgiyi alın. Gerisini ben yaparım."] = "TAMAM MİLLET. DOĞRUDAN KAYNAĞA GİDİYORUZ. ORADA İHTİYACIMIZ OLAN BİLGİ VAR, BİR DE YAKININDA OLMAK İSTEMEYECEĞİMİZ KADAR ÇOK KOLLUK KUVVETİ. SUNUCU ODALARINI BULUP BANKAYLA İLGİLİ BİLGİYİ ALIN. GERİSİNİ BEN YAPARIM.",
["Tamam millet. Elephant size brifingi verdi, neyin peşinde olduğumuzu biliyorsunuz. BCI başlığını ve bilgisayar yazılımını bulmamız gerek. Başarırsanız çok para kazanacağız."] = "TAMAM MİLLET. ELEPHANT SİZE BRİFİNGİ VERDİ, NEYİN PEŞİNDE OLDUĞUMUZU BİLİYORSUNUZ. BCI BAŞLIĞINI VE BİLGİSAYAR YAZILIMINI BULMAMIZ GEREK. BAŞARIRSANIZ ÇOK PARA KAZANACAĞIZ.",
["Tamam millet. Girelim. Sessiz ya da gürültülü, bu herifi istediğiniz gibi öldürebilirsiniz."] = "TAMAM MİLLET. GİRELİM. SESSİZ YA DA GÜRÜLTÜLÜ, BU HERİFİ İSTEDİĞİNİZ GİBİ ÖLDÜREBİLİRSİNİZ.",
["Tamam millet. Hedefi bulup oradan çıkarın."] = "TAMAM MİLLET. HEDEFİ BULUP ORADAN ÇIKARIN.",
["Tamam millet. Helikopter döndü, yeniden yüklemeye başlayın!"] = "TAMAM MİLLET. HELİKOPTER DÖNDÜ, YENİDEN YÜKLEMEYE BAŞLAYIN!",
["Tamam millet. Herkes hazır mı? Burayı boşaltalım. "] = "TAMAM MİLLET. HERKES HAZIR MI? BURAYI BOŞALTALIM. ",
["Tamam millet. Kiminle iş yaptığınızı unutmayın. Locke'ta bir bit yeniği var. Bu işte bize anlattığından fazlası olduğuna eminim. Gözünüzü dört açın."] = "TAMAM MİLLET. KİMİNLE İŞ YAPTIĞINIZI UNUTMAYIN. LOCKE'TA BİR BİT YENİĞİ VAR. BU İŞTE BİZE ANLATTIĞINDAN FAZLASI OLDUĞUNA EMİNİM. GÖZÜNÜZÜ DÖRT AÇIN.",
["Tamam millet. Kullanabilmek için önce şu güzelliği şarj etmemiz lazım. Biraz sürecek."] = "TAMAM MİLLET. KULLANABİLMEK İÇİN ÖNCE ŞU GÜZELLİĞİ ŞARJ ETMEMİZ LAZIM. BİRAZ SÜRECEK.",
["Tamam millet. Role girme vakti."] = "TAMAM MİLLET. ROLE GİRME VAKTİ.",
["Tamam millet. Unutmayın: bilgisayar, kan örneği, doğrulama ve asansörle defolup gitme. Ha, umarım güvenlik kameralarını indirecek bir şey getirmişsinizdir."] = "TAMAM MİLLET. UNUTMAYIN: BİLGİSAYAR, KAN ÖRNEĞİ, DOĞRULAMA VE ASANSÖRLE DEFOLUP GİTME. HA, UMARIM GÜVENLİK KAMERALARINI İNDİRECEK BİR ŞEY GETİRMİŞSİNİZDİR.",
["Tamam millet. Çalıştığımız gibi vinçle konteynerleri taşıyın."] = "TAMAM MİLLET. ÇALIŞTIĞIMIZ GİBİ VİNÇLE KONTEYNERLERİ TAŞIYIN.",
["Tamam millet. İşte Locke... Yukarıda dikkatli olun."] = "TAMAM MİLLET. İŞTE LOCKE... YUKARIDA DİKKATLİ OLUN.",
["Tamam millet. İşte bu. Gelmiş Geçmiş En Büyük Soygun. Bunun için çalıştınız. Siktiğimin Beyaz Saray'ı! İçeride bütün sorunlarımızın cevabı var. Bunun önemli bir parçası da bir dizi belge: Hâlâ yasal ve geçerli olan ama üzerlerinde hiç isim bulunmayan başkanlık afları! Onları alırsanız hiçbir ceza almadan kurtulup emekli olabilirsiniz. Fazla vaktim kalmadı; lanet Murky virüsü her saniye bedenimin biraz daha fazlasını yiyip bitiriyor ama kahretsin, bu işi sonuna kadar götüreceğim. Bunu benim yerime Locke yönetecek ama merak etmeyin... Buralarda olacağım. Oval Ofis'i de çok dağıtmayın, anladınız mı?"] = "TAMAM MİLLET. İŞTE BU. GELMİŞ GEÇMİŞ EN BÜYÜK SOYGUN. BUNUN İÇİN ÇALIŞTINIZ. SİKTİĞİMİN BEYAZ SARAY'I! İÇERİDE BÜTÜN SORUNLARIMIZIN CEVABI VAR. BUNUN ÖNEMLİ BİR PARÇASI DA BİR DİZİ BELGE: HÂLÂ YASAL VE GEÇERLİ OLAN AMA ÜZERLERİNDE HİÇ İSİM BULUNMAYAN BAŞKANLIK AFLARI! ONLARI ALIRSANIZ HİÇBİR CEZA ALMADAN KURTULUP EMEKLİ OLABİLİRSİNİZ. FAZLA VAKTİM KALMADI; LANET MURKY VİRÜSÜ HER SANİYE BEDENİMİN BİRAZ DAHA FAZLASINI YİYİP BİTİRİYOR AMA KAHRETSİN, BU İŞİ SONUNA KADAR GÖTÜRECEĞİM. BUNU BENİM YERİME LOCKE YÖNETECEK AMA MERAK ETMEYİN... BURALARDA OLACAĞIM. OVAL OFİS'İ DE ÇOK DAĞITMAYIN, ANLADINIZ MI?",
["Tamam millet... Buradaki binalar yaklaşmayı zorlaştırıyor. Sizi alabilmem için daha yüksek bir yere çıkmanız gerek."] = "TAMAM MİLLET... BURADAKİ BİNALAR YAKLAŞMAYI ZORLAŞTIRIYOR. SİZİ ALABİLMEM İÇİN DAHA YÜKSEK BİR YERE ÇIKMANIZ GEREK.",
["Tamam millet: Girin, termal mızrakla Kasa Dairesini yarın, parayı yakın ve filme almayı unutmayın."] = "TAMAM MİLLET: GİRİN, TERMAL MIZRAKLA KASA DAİRESİNİ YARIN, PARAYI YAKIN VE FİLME ALMAYI UNUTMAYIN.",
["Tamam o zaman. Hmm... Fiziksel delil de var diyor."] = "TAMAM O ZAMAN. HMM... FİZİKSEL DELİL DE VAR DİYOR.",
["Tamam otuzbirciler. Bunu patron için yapıyoruz."] = "TAMAM OTUZBİRCİLER. BUNU PATRON İÇİN YAPIYORUZ.",
["Tamam palyaçolar, gözünüz yolda olsun."] = "TAMAM PALYAÇOLAR, GÖZÜNÜZ YOLDA OLSUN.",
["Tamam palyaçolar, istediğiniz her şeyi aldınız. Ama bir gün bunun hesabını vereceksiniz!"] = "TAMAM PALYAÇOLAR, İSTEDİĞİNİZ HER ŞEYİ ALDINIZ. AMA BİR GÜN BUNUN HESABINI VERECEKSİNİZ!",
["Tamam palyaçolar, istediğinizi aldınız. Para serbest bırakıldı, rehinenin geri alındığı doğrulandı."] = "TAMAM PALYAÇOLAR, İSTEDİĞİNİZİ ALDINIZ. PARA SERBEST BIRAKILDI, REHİNENİN GERİ ALINDIĞI DOĞRULANDI.",
["Tamam palyaçolar, sözünüzü tuttunuz. Rehine güvende, fidyeyi de aktardık."] = "TAMAM PALYAÇOLAR, SÖZÜNÜZÜ TUTTUNUZ. REHİNE GÜVENDE, FİDYEYİ DE AKTARDIK.",
["Tamam pislikler, buraya kadar. Ölü ya da diri, bizimle geliyorsunuz."] = "TAMAM PİSLİKLER, BURAYA KADAR. ÖLÜ YA DA DİRİ, BİZİMLE GELİYORSUNUZ.",
["Tamam pislikler, şansınızı kullandınız. Sizi almaya geliyoruz."] = "TAMAM PİSLİKLER, ŞANSINIZI KULLANDINIZ. SİZİ ALMAYA GELİYORUZ.",
["Tamam salaklar, DC'deki işlerimiz kritik noktada olsa da bu soygunu Vlad için yapıyoruz. Sizi Buluc'u kendini en güvende hissettiği yerde, Meksika kıyısı açıklarındaki ada malikânesinde indirmeye gönderiyorum. Coyopa'nın The Dentist ve Kataru'yla bağlantıları bozulduğundan Buluc, gangster özentisi Amerikalı ahmaklara maskeli balo düzenleyerek bağlantı ağını genişletmeye çalışıyor. Ona ulaşmak için tam zamanı! Yerin kesin ayrıntılarını edinmek zordu ama malikânenin gelişmiş gözetleme sistemine girdim ve... şey... bilgi için birkaç kişiye 'rüşvet verdim' diyelim. Gün batımında giriyoruz. Ama unutmayın: Federales, Buluc'un kirli cebinde. Gürültü çıkarırsanız ağır çatışma bekleyin, tamam mı?"] = "TAMAM SALAKLAR, DC'DEKİ İŞLERİMİZ KRİTİK NOKTADA OLSA DA BU SOYGUNU VLAD İÇİN YAPIYORUZ. SİZİ BULUC'U KENDİNİ EN GÜVENDE HİSSETTİĞİ YERDE, MEKSİKA KIYISI AÇIKLARINDAKİ ADA MALİKÂNESİNDE İNDİRMEYE GÖNDERİYORUM. COYOPA'NIN THE DENTIST VE KATARU'YLA BAĞLANTILARI BOZULDUĞUNDAN BULUC, GANGSTER ÖZENTİSİ AMERİKALI AHMAKLARA MASKELİ BALO DÜZENLEYEREK BAĞLANTI AĞINI GENİŞLETMEYE ÇALIŞIYOR. ONA ULAŞMAK İÇİN TAM ZAMANI! YERİN KESİN AYRINTILARINI EDİNMEK ZORDU AMA MALİKÂNENİN GELİŞMİŞ GÖZETLEME SİSTEMİNE GİRDİM VE... ŞEY... BİLGİ İÇİN BİRKAÇ KİŞİYE 'RÜŞVET VERDİM' DİYELİM. GÜN BATIMINDA GİRİYORUZ. AMA UNUTMAYIN: FEDERALES, BULUC'UN KİRLİ CEBİNDE. GÜRÜLTÜ ÇIKARIRSANIZ AĞIR ÇATIŞMA BEKLEYİN, TAMAM MI?",
["Tamam salaklar, hızlı davranmalıyız. Vlad'ın bize sadakatinin bir sınırı var. Onu kırarlarsa başımız büyük belaya girer. Jiu Feng'in rıhtım tesisindeki adamı bol istihbarat verdi. Mekânda kapsamlı gözetleme var; bunu avantajımıza kullanabiliriz. Vlad'ı bulunca içerideki adam onu taşımaya yardım edecek. Jiu Feng sizi tekneyle bizzat çıkarmaya gönüllü oldu. Bunu yaptıktan sonra o ahmak Ukraynalı bize kesinlikle borçlu kalacak!"] = "TAMAM SALAKLAR, HIZLI DAVRANMALIYIZ. VLAD'IN BİZE SADAKATİNİN BİR SINIRI VAR. ONU KIRARLARSA BAŞIMIZ BÜYÜK BELAYA GİRER. JIU FENG'İN RIHTIM TESİSİNDEKİ ADAMI BOL İSTİHBARAT VERDİ. MEKÂNDA KAPSAMLI GÖZETLEME VAR; BUNU AVANTAJIMIZA KULLANABİLİRİZ. VLAD'I BULUNCA İÇERİDEKİ ADAM ONU TAŞIMAYA YARDIM EDECEK. JIU FENG SİZİ TEKNEYLE BİZZAT ÇIKARMAYA GÖNÜLLÜ OLDU. BUNU YAPTIKTAN SONRA O AHMAK UKRAYNALI BİZE KESİNLİKLE BORÇLU KALACAK!",
["Tamam sensei. Hazır olduğunuzda haber verin yeter."] = "TAMAM SENSEİ. HAZIR OLDUĞUNUZDA HABER VERİN YETER.",
["Tamam sersemler! Gürültü koparın, göğsünüzü gere gere!"] = "TAMAM SERSEMLER! GÜRÜLTÜ KOPARIN, GÖĞSÜNÜZÜ GERE GERE!",
["Tamam sersemler! Uçuşan tuğlalara dikkat edin..."] = "TAMAM SERSEMLER! UÇUŞAN TUĞLALARA DİKKAT EDİN...",
["Tamam sersemler, o helikoptere binin!"] = "TAMAM SERSEMLER, O HELİKOPTERE BİNİN!",
["Tamam sersemler. Kasa dairesine gitme vakti."] = "TAMAM SERSEMLER. KASA DAİRESİNE GİTME VAKTİ.",
["Tamam sersemler. İşe koyulalım. Bilgilerimize göre Triad bu dükkânı paravan olarak kullanıyor."] = "TAMAM SERSEMLER. İŞE KOYULALIM. BİLGİLERİMİZE GÖRE TRİAD BU DÜKKÂNI PARAVAN OLARAK KULLANIYOR.",
["Tamam sizi aptallar! Elinizi çabuk tutun. Güverteye adım attığınız an ateş serbest. Hızlı bitirin, sahil güvenliğin adam yollaması uzun sürmez! "] = "TAMAM SİZİ APTALLAR! ELİNİZİ ÇABUK TUTUN. GÜVERTEYE ADIM ATTIĞINIZ AN ATEŞ SERBEST. HIZLI BİTİRİN, SAHİL GÜVENLİĞİN ADAM YOLLAMASI UZUN SÜRMEZ! ",
["Tamam sizi aptallar, Vlad'a bu kadar yeter. Hazır olur olmaz çıkın oradan!"] = "TAMAM SİZİ APTALLAR, VLAD'A BU KADAR YETER. HAZIR OLUR OLMAZ ÇIKIN ORADAN!",
["Tamam sizi aptallar, şimdi gayet sıradan davranma vakti. Maskelerinizi çıkarıp sakince yürüyerek çıkın. "] = "TAMAM SİZİ APTALLAR, ŞİMDİ GAYET SIRADAN DAVRANMA VAKTİ. MASKELERİNİZİ ÇIKARIP SAKİNCE YÜRÜYEREK ÇIKIN. ",
["Tamam sizi aptallar. Hadi sizi bankaya yürütelim."] = "TAMAM SİZİ APTALLAR. HADİ SİZİ BANKAYA YÜRÜTELİM.",
["Tamam soyguncular! Şu Domuz Kumbarası'nı bulalım."] = "TAMAM SOYGUNCULAR! ŞU DOMUZ KUMBARASI'NI BULALIM.",
["Tamam tamam, bana öyle bakmayın. Sırf hayatımı kurtarmaya geldiğinizi sanacak kadar salak değilim. Rust'ı ben de tanıyorum, unuttunuz mu? Bebeğini gerçekten geri istediğini biliyorum. Olacaksa gereken parçaları siz getirmelisiniz."] = "TAMAM TAMAM, BANA ÖYLE BAKMAYIN. SIRF HAYATIMI KURTARMAYA GELDİĞİNİZİ SANACAK KADAR SALAK DEĞİLİM. RUST'I BEN DE TANIYORUM, UNUTTUNUZ MU? BEBEĞİNİ GERÇEKTEN GERİ İSTEDİĞİNİ BİLİYORUM. OLACAKSA GEREKEN PARÇALARI SİZ GETİRMELİSİNİZ.",
["Tamam tamam, iki!"] = "TAMAM TAMAM, İKİ!",
["Tamam tamam, kamyon gitmek üzere... Doğru olduğunu düşünüyorsanız işaretleseniz iyi olur."] = "TAMAM TAMAM, KAMYON GİTMEK ÜZERE... DOĞRU OLDUĞUNU DÜŞÜNÜYORSANIZ İŞARETLESENİZ İYİ OLUR.",
["Tamam tamam, maskeni tak artık."] = "TAMAM TAMAM, MASKENİ TAK ARTIK.",
["Tamam çocuklar, kaçış arabamız burada ama polisler tepesinde."] = "TAMAM ÇOCUKLAR, KAÇIŞ ARABAMIZ BURADA AMA POLİSLER TEPESİNDE.",
["Tamam şefler, adamınızı buradan çıkaralım. Binin!"] = "TAMAM ŞEFLER, ADAMINIZI BURADAN ÇIKARALIM. BİNİN!",
["Tamam!"] = "TAMAM!",
["Tamam! Bitirelim şu işi. Malı pikaba koyun, istediğinizi alın."] = "TAMAM! BİTİRELİM ŞU İŞİ. MALI PİKABA KOYUN, İSTEDİĞİNİZİ ALIN.",
["Tamam! Bundan fazlası tamamen bonus!"] = "TAMAM! BUNDAN FAZLASI TAMAMEN BONUS!",
["Tamam! Burada gerçek bir skandal var. Devletin silahlarını haydut bir devlete satmış, karşılığında altın almış. Demokratlar bundan hoşlanmayacak."] = "TAMAM! BURADA GERÇEK BİR SKANDAL VAR. DEVLETİN SİLAHLARINI HAYDUT BİR DEVLETE SATMIŞ, KARŞILIĞINDA ALTIN ALMIŞ. DEMOKRATLAR BUNDAN HOŞLANMAYACAK.",
["Tamam! Evrak çantasını alın!"] = "TAMAM! EVRAK ÇANTASINI ALIN!",
["Tamam! Gel babana!"] = "TAMAM! GEL BABANA!",
["Tamam! Helikopter geldi! Gidin!"] = "TAMAM! HELİKOPTER GELDİ! GİDİN!",
["Tamam! Helikopter rıhtıma gidiyor millet; yağmurdan kaçarken..."] = "TAMAM! HELİKOPTER RIHTIMA GİDİYOR MİLLET; YAĞMURDAN KAÇARKEN...",
["Tamam! Helikopter yakında geliyor olmalı!"] = "TAMAM! HELİKOPTER YAKINDA GELİYOR OLMALI!",
["Tamam! Hepsi bu kadar! Güzel!"] = "TAMAM! HEPSİ BU KADAR! GÜZEL!",
["Tamam! Konvoyu durdurduk. Şimdi açın ve ganimeti güvenceye alın!"] = "TAMAM! KONVOYU DURDURDUK. ŞİMDİ AÇIN VE GANİMETİ GÜVENCEYE ALIN!",
["Tamam! Köprü yerine döndü! Şimdi arabaya binip defolun oradan!"] = "TAMAM! KÖPRÜ YERİNE DÖNDÜ! ŞİMDİ ARABAYA BİNİP DEFOLUN ORADAN!",
["Tamam! Matkap o kapıyı açmalı!"] = "TAMAM! MATKAP O KAPIYI AÇMALI!",
["Tamam! Minibüs yakında geliyor olmalı!"] = "TAMAM! MİNİBÜS YAKINDA GELİYOR OLMALI!",
["Tamam! Sadece bir tane daha."] = "TAMAM! SADECE BİR TANE DAHA.",
["Tamam! Sağ olun!"] = "TAMAM! SAĞ OLUN!",
["Tamam! Sokak lambası tarih oldu. Keçiyi alın!"] = "TAMAM! SOKAK LAMBASI TARİH OLDU. KEÇİYİ ALIN!",
["Tamam! Tamam, boş. Aramaya devam edin işte!"] = "TAMAM! TAMAM, BOŞ. ARAMAYA DEVAM EDİN İŞTE!",
["Tamam! Tekne yakında gelmiş olur!"] = "TAMAM! TEKNE YAKINDA GELMİŞ OLUR!",
["Tamam! Yeterince aldınız... Ya da daha fazlası için kalabilirsiniz."] = "TAMAM! YETERİNCE ALDINIZ... YA DA DAHA FAZLASI İÇİN KALABİLİRSİNİZ.",
["Tamam! Zepline işaret verin. Vegas usulü yapın. Biraz havai fişek bulup ateşleyin."] = "TAMAM! ZEPLİNE İŞARET VERİN. VEGAS USULÜ YAPIN. BİRAZ HAVAİ FİŞEK BULUP ATEŞLEYİN.",
["Tamam! İnceleyebilmemiz için buraya getirecek."] = "TAMAM! İNCELEYEBİLMEMİZ İÇİN BURAYA GETİRECEK.",
["Tamam! İşimiz tamam. Sanırım gereken her şeyi aldım. Artık masaüstü bilgisayarına erişebilirsiniz."] = "TAMAM! İŞİMİZ TAMAM. SANIRIM GEREKEN HER ŞEYİ ALDIM. ARTIK MASAÜSTÜ BİLGİSAYARINA ERİŞEBİLİRSİNİZ.",
["Tamam! Şifreyi aldık! Zaman kilidini başlatın."] = "TAMAM! ŞİFREYİ ALDIK! ZAMAN KİLİDİNİ BAŞLATIN.",
["Tamam! Şimdi bir benzin bidonu bulup her şeyi tutuşturmak için vurun. Biraz sanat yakalım!"] = "TAMAM! ŞİMDİ BİR BENZİN BİDONU BULUP HER ŞEYİ TUTUŞTURMAK İÇİN VURUN. BİRAZ SANAT YAKALIM!",
["Tamam! Şimdi gidip benzin bidonu bulun. Tabloları yakmak için ona ateş edin."] = "TAMAM! ŞİMDİ GİDİP BENZİN BİDONU BULUN. TABLOLARI YAKMAK İÇİN ONA ATEŞ EDİN.",
["Tamam! Şimdi çalışırlarken vinçleri koruyun yeter."] = "TAMAM! ŞİMDİ ÇALIŞIRLARKEN VİNÇLERİ KORUYUN YETER.",
["Tamam! Şimdi çantaları kamyona koyun. En az dört çanta lazım."] = "TAMAM! ŞİMDİ ÇANTALARI KAMYONA KOYUN. EN AZ DÖRT ÇANTA LAZIM.",
["Tamam! Şimdi çantayı kafese götürün. Doldurduğumuzda adamımız uçakla üzerinden geçip alacak. Tıpkı James gibi."] = "TAMAM! ŞİMDİ ÇANTAYI KAFESE GÖTÜRÜN. DOLDURDUĞUMUZDA ADAMIMIZ UÇAKLA ÜZERİNDEN GEÇİP ALACAK. TIPKI JAMES GİBİ.",
["Tamam! Şimdi şunu yapmanızı istiyorum..."] = "TAMAM! ŞİMDİ ŞUNU YAPMANIZI İSTİYORUM...",
["Tamam, 'acil' bir e-postayla onu dışarı çıkaralım. Yakınınızda kullanabileceğimiz, ele geçirilmiş başka bir bilgisayar var."] = "TAMAM, 'ACİL' BİR E-POSTAYLA ONU DIŞARI ÇIKARALIM. YAKININIZDA KULLANABİLECEĞİMİZ, ELE GEÇİRİLMİŞ BAŞKA BİR BİLGİSAYAR VAR.",
["Tamam, 18 tane daha lazım, hadi!"] = "TAMAM, 18 TANE DAHA LAZIM, HADİ!",
["Tamam, 3 tane daha, sonra buradan çıkabiliriz."] = "TAMAM, 3 TANE DAHA, SONRA BURADAN ÇIKABİLİRİZ.",
["Tamam, 5 tablo sayıyorum. "] = "TAMAM, 5 TABLO SAYIYORUM. ",
["Tamam, ASIM'i geçtik. Neye uğradıklarını şaşıracaklar."] = "TAMAM, ASIM'İ GEÇTİK. NEYE UĞRADIKLARINI ŞAŞIRACAKLAR.",
["Tamam, Alex onu oradan kaldıracak. Gafil avlanmayalım. Hazırlanın!"] = "TAMAM, ALEX ONU ORADAN KALDIRACAK. GAFİL AVLANMAYALIM. HAZIRLANIN!",
["Tamam, AÇILIN!"] = "TAMAM, AÇILIN!",
["Tamam, B planı helikopter. Bekleyin..."] = "TAMAM, B PLANI HELİKOPTER. BEKLEYİN...",
["Tamam, B planı vakti!"] = "TAMAM, B PLANI VAKTİ!",
["Tamam, B planına geçmeliyiz."] = "TAMAM, B PLANINA GEÇMELİYİZ.",
["Tamam, BCI teknolojisi artık emin ellerde. Yine de vagona dönüp daha fazla ganimet alabilirsiniz. Hepsi iyi para eder."] = "TAMAM, BCI TEKNOLOJİSİ ARTIK EMİN ELLERDE. YİNE DE VAGONA DÖNÜP DAHA FAZLA GANİMET ALABİLİRSİNİZ. HEPSİ İYİ PARA EDER.",
["Tamam, Bain şimdi çatıya gidiyor. Peşinden gitmeye devam edin."] = "TAMAM, BAIN ŞİMDİ ÇATIYA GİDİYOR. PEŞİNDEN GİTMEYE DEVAM EDİN.",
["Tamam, Bain'i şu helikoptere bindirelim de buradan gidelim!"] = "TAMAM, BAIN'İ ŞU HELİKOPTERE BİNDİRELİM DE BURADAN GİDELİM!",
["Tamam, Bain'in hapishanenin tam neresinde tutulduğunu ya da ne durumda olduğunu bilmiyoruz. Üstelik her yerde Murky pislikleri var. Bu iş çok çabuk gürültüye dönecek, ha? Okyanusa dökülen kanalizasyon sisteminden giriyorsunuz."] = "TAMAM, BAIN'İN HAPİSHANENİN TAM NERESİNDE TUTULDUĞUNU YA DA NE DURUMDA OLDUĞUNU BİLMİYORUZ. ÜSTELİK HER YERDE MURKY PİSLİKLERİ VAR. BU İŞ ÇOK ÇABUK GÜRÜLTÜYE DÖNECEK, HA? OKYANUSA DÖKÜLEN KANALİZASYON SİSTEMİNDEN GİRİYORSUNUZ.",
["Tamam, Bile için fazla beklemeniz gerekmeyecek."] = "TAMAM, BILE İÇİN FAZLA BEKLEMENİZ GEREKMEYECEK.",
["Tamam, Bile termal mızrağı bıraktı! Alın da gösteriye devam edelim."] = "TAMAM, BILE TERMAL MIZRAĞI BIRAKTI! ALIN DA GÖSTERİYE DEVAM EDELİM.",
["Tamam, Bile yolda. Sahte paraları taşıyacak."] = "TAMAM, BILE YOLDA. SAHTE PARALARI TAŞIYACAK.",
["Tamam, Bile çatıda. Bir an önce ona gidin."] = "TAMAM, BILE ÇATIDA. BİR AN ÖNCE ONA GİDİN.",
["Tamam, Bile şimdi tam gaz size geliyor! "] = "TAMAM, BILE ŞİMDİ TAM GAZ SİZE GELİYOR! ",
["Tamam, C4 orada. Buyurun alın!"] = "TAMAM, C4 ORADA. BUYURUN ALIN!",
["Tamam, C4 yerde. Alın!"] = "TAMAM, C4 YERDE. ALIN!",
["Tamam, C4'ü Kasaya atıp patlatarak açın. Su işini yapacak."] = "TAMAM, C4'Ü KASAYA ATIP PATLATARAK AÇIN. SU İŞİNİ YAPACAK.",
["Tamam, C4'ü kapıya yerleştirin. "] = "TAMAM, C4'Ü KAPIYA YERLEŞTİRİN. ",
["Tamam, C4'ün hepsi bu. Garaja inin. İçerideki adamımız patlatmanız gereken yeri işaretledi."] = "TAMAM, C4'ÜN HEPSİ BU. GARAJA İNİN. İÇERİDEKİ ADAMIMIZ PATLATMANIZ GEREKEN YERİ İŞARETLEDİ.",
["Tamam, CFO'yu bulun. Ana kod onda!"] = "TAMAM, CFO'YU BULUN. ANA KOD ONDA!",
["Tamam, Commissar şehir merkezindeki köhne bir apartmana sığınmış. Neyle karşılaşacağımızı bilmiyorum ama sizi sessizce sokmanın bir yolunu buldum. Yola çıkalım."] = "TAMAM, COMMİSSAR ŞEHİR MERKEZİNDEKİ KÖHNE BİR APARTMANA SIĞINMIŞ. NEYLE KARŞILAŞACAĞIMIZI BİLMİYORUM AMA SİZİ SESSİZCE SOKMANIN BİR YOLUNU BULDUM. YOLA ÇIKALIM.",
["Tamam, Commissar'ın adresini aldık. Eski bir apartman kompleksi. Köhne bir çöplük. Nasıl bir güvenlikle karşılaşacağınızı söylemek zor. Hazırlanın da bitirelim şu işi."] = "TAMAM, COMMİSSAR'IN ADRESİNİ ALDIK. ESKİ BİR APARTMAN KOMPLEKSİ. KÖHNE BİR ÇÖPLÜK. NASIL BİR GÜVENLİKLE KARŞILAŞACAĞINIZI SÖYLEMEK ZOR. HAZIRLANIN DA BİTİRELİM ŞU İŞİ.",
["Tamam, DC'ye alışmak için kolay bir iş bu."] = "TAMAM, DC'YE ALIŞMAK İÇİN KOLAY BİR İŞ BU.",
["Tamam, DC'yi partide tutmak için gereken bu kadar! Ama Baltimore, Harrisburg, Philly de var. Siz yapmaya devam edin, ben almaya, Doğu Yakası da dans etmeye devam etsin, ha? Ya da gidebilirsiniz."] = "TAMAM, DC'Yİ PARTİDE TUTMAK İÇİN GEREKEN BU KADAR! AMA BALTİMORE, HARRİSBURG, PHİLLY DE VAR. SİZ YAPMAYA DEVAM EDİN, BEN ALMAYA, DOĞU YAKASI DA DANS ETMEYE DEVAM ETSİN, HA? YA DA GİDEBİLİRSİNİZ.",
["Tamam, EMP parçalarını çalmak için gereken her şey bizde. Trenlere dönün."] = "TAMAM, EMP PARÇALARINI ÇALMAK İÇİN GEREKEN HER ŞEY BİZDE. TRENLERE DÖNÜN.",
["Tamam, Ernesto'nun evini yağmalama vakti. Ofisinde bir zemin Kasası var. O çekme vinçlerini zemine bağlayıp kaldıralım."] = "TAMAM, ERNESTO'NUN EVİNİ YAĞMALAMA VAKTİ. OFİSİNDE BİR ZEMİN KASASI VAR. O ÇEKME VİNÇLERİNİ ZEMİNE BAĞLAYIP KALDIRALIM.",
["Tamam, FBI şefi canlı lazım. Gözünüzü açık tutun, öldürmeyin."] = "TAMAM, FBI ŞEFİ CANLI LAZIM. GÖZÜNÜZÜ AÇIK TUTUN, ÖLDÜRMEYİN.",
["Tamam, Gabriel düştü. Gazı kapatın, sonra gidip Anahtar Kartını alın. Bu sırayla."] = "TAMAM, GABRİEL DÜŞTÜ. GAZI KAPATIN, SONRA GİDİP ANAHTAR KARTINI ALIN. BU SIRAYLA.",
["Tamam, GenSec yaklaşıyor. Gaza basın. Hadi! Hadi!"] = "TAMAM, GENSEC YAKLAŞIYOR. GAZA BASIN. HADİ! HADİ!",
["Tamam, Hector bir şoför gönderdi, yakında burada olur."] = "TAMAM, HECTOR BİR ŞOFÖR GÖNDERDİ, YAKINDA BURADA OLUR.",
["Tamam, Hector bunu kaydetmemizi istiyor, önce kamerayı kurun."] = "TAMAM, HECTOR BUNU KAYDETMEMİZİ İSTİYOR, ÖNCE KAMERAYI KURUN.",
["Tamam, Hector bunu kaydetmemizi istiyor. Önce kamerayı kurun."] = "TAMAM, HECTOR BUNU KAYDETMEMİZİ İSTİYOR. ÖNCE KAMERAYI KURUN.",
["Tamam, Hector için artık sadece iki çanta daha lazım."] = "TAMAM, HECTOR İÇİN ARTIK SADECE İKİ ÇANTA DAHA LAZIM.",
["Tamam, Kasa Dairesi açıldı!"] = "TAMAM, KASA DAİRESİ AÇILDI!",
["Tamam, Kasa Dairesi için gereken termal matkap otoparkta bir yerde. Baskına başlamadan önce alın. Sonra Kasa Dairesine girişebilirsiniz. Kameralara ve banka çalışanlarına dikkat edin. İçeri girmeden önce ödevinizi yapın ve unutmayın: Nakit kraldır."] = "TAMAM, KASA DAİRESİ İÇİN GEREKEN TERMAL MATKAP OTOPARKTA BİR YERDE. BASKINA BAŞLAMADAN ÖNCE ALIN. SONRA KASA DAİRESİNE GİRİŞEBİLİRSİNİZ. KAMERALARA VE BANKA ÇALIŞANLARINA DİKKAT EDİN. İÇERİ GİRMEDEN ÖNCE ÖDEVİNİZİ YAPIN VE UNUTMAYIN: NAKİT KRALDIR.",
["Tamam, Kasa Dairesi'ne doğru deliyor. Siz onu koruyun."] = "TAMAM, KASA DAİRESİ'NE DOĞRU DELİYOR. SİZ ONU KORUYUN.",
["Tamam, Kasa Dairesi'nin güvenlik sorumluluğunu paylaşmışlar. Şifreyi Li Deng'den almalısınız. Xun Kang'ın el izini almak için de evrak çantasındaki o yapışkan mumu kullanın. "] = "TAMAM, KASA DAİRESİ'NİN GÜVENLİK SORUMLULUĞUNU PAYLAŞMIŞLAR. ŞİFREYİ Lİ DENG'DEN ALMALISINIZ. XUN KANG'IN EL İZİNİ ALMAK İÇİN DE EVRAK ÇANTASINDAKİ O YAPIŞKAN MUMU KULLANIN. ",
["Tamam, Kasa Dairesinin sistemine eriştim. Açmak için bana biraz zaman verin."] = "TAMAM, KASA DAİRESİNİN SİSTEMİNE ERİŞTİM. AÇMAK İÇİN BANA BİRAZ ZAMAN VERİN.",
["Tamam, Kasa'yı tamamen deldi."] = "TAMAM, KASA'YI TAMAMEN DELDİ.",
["Tamam, Kento hakkında bildiklerini alabilmemiz için şu Kazuo denen adamı hapisten çıkarma vakti. Başka tesise konvoyla nakledilmesi için biraz, şey... sorun çıkardım. Konvoya pusu kurup mahkûmu kurtaracağız. Sessiz olmayacak, millet. Mahkûm kamyonlarını durdurmak için aşırı önlemler gerekecek. Bir de evet, Kazuo onu kurtaracağımızı bilmiyor. Büyük sürpriz yaşayacak!"] = "TAMAM, KENTO HAKKINDA BİLDİKLERİNİ ALABİLMEMİZ İÇİN ŞU KAZUO DENEN ADAMI HAPİSTEN ÇIKARMA VAKTİ. BAŞKA TESİSE KONVOYLA NAKLEDİLMESİ İÇİN BİRAZ, ŞEY... SORUN ÇIKARDIM. KONVOYA PUSU KURUP MAHKÛMU KURTARACAĞIZ. SESSİZ OLMAYACAK, MİLLET. MAHKÛM KAMYONLARINI DURDURMAK İÇİN AŞIRI ÖNLEMLER GEREKECEK. BİR DE EVET, KAZUO ONU KURTARACAĞIMIZI BİLMİYOR. BÜYÜK SÜRPRİZ YAŞAYACAK!",
["Tamam, Lao Che deposunu arıyorsunuz. Vlad onların konteynerlerinden birinde."] = "TAMAM, LAO CHE DEPOSUNU ARIYORSUNUZ. VLAD ONLARIN KONTEYNERLERİNDEN BİRİNDE.",
["Tamam, Lo Pan deposunu arıyorsunuz. Vlad konteynerlerinden birinde."] = "TAMAM, LO PAN DEPOSUNU ARIYORSUNUZ. VLAD KONTEYNERLERİNDEN BİRİNDE.",
["Tamam, Lán Tàiyáng deposunu arıyorsunuz. Vlad konteynerlerinden birinde."] = "TAMAM, LÁN TÀİYÁNG DEPOSUNU ARIYORSUNUZ. VLAD KONTEYNERLERİNDEN BİRİNDE.",
["Tamam, Mendoza otobüsü köprüde. Demek on dakika içinde inip işini bitireceğiz. Otobüsü vurun, adamlarını öldürün, parayı alın. Basit."] = "TAMAM, MENDOZA OTOBÜSÜ KÖPRÜDE. DEMEK ON DAKİKA İÇİNDE İNİP İŞİNİ BİTİRECEĞİZ. OTOBÜSÜ VURUN, ADAMLARINI ÖLDÜRÜN, PARAYI ALIN. BASİT.",
["Tamam, Mitchell'ı bulun. Adamımız o."] = "TAMAM, MITCHELL'I BULUN. ADAMIMIZ O.",
["Tamam, Moretta hareket edebilir ama kaptanı ikna etmeliyiz. Haberleşme frekanslarını bulun. Bence oradaki bilgisayarlardan birinde. Ben iyi kaptanımızı motorları çalıştırmaya ikna ederim."] = "TAMAM, MORETTA HAREKET EDEBİLİR AMA KAPTANI İKNA ETMELİYİZ. HABERLEŞME FREKANSLARINI BULUN. BENCE ORADAKİ BİLGİSAYARLARDAN BİRİNDE. BEN İYİ KAPTANIMIZI MOTORLARI ÇALIŞTIRMAYA İKNA EDERİM.",
["Tamam, Noel Baba'yı bulup kurtarın!"] = "TAMAM, NOEL BABA'YI BULUP KURTARIN!",
["Tamam, Noel'i çalmadan o serserileri indirin. Sonra atölyeye."] = "TAMAM, NOEL'İ ÇALMADAN O SERSERİLERİ İNDİRİN. SONRA ATÖLYEYE.",
["Tamam, Petersson dosyası bu. Yoğun bakımda izole etmişler, ona ulaşmalısınız. Doktorculuk oynama vakti millet."] = "TAMAM, PETERSSON DOSYASI BU. YOĞUN BAKIMDA İZOLE ETMİŞLER, ONA ULAŞMALISINIZ. DOKTORCULUK OYNAMA VAKTİ MİLLET.",
["Tamam, Rust'ın nazlı götüne şık bir sele lazım, değil mi? Arka bahçede eski bir sığınak var. İçeri girin, ihtiyacımız olanı bulursunuz."] = "TAMAM, RUST'IN NAZLI GÖTÜNE ŞIK BİR SELE LAZIM, DEĞİL Mİ? ARKA BAHÇEDE ESKİ BİR SIĞINAK VAR. İÇERİ GİRİN, İHTİYACIMIZ OLANI BULURSUNUZ.",
["Tamam, Salem'e gidip açık artırma başlamadan hemen önce şatafatlı zengin ahmakların partisinden eseri çalacağız, değil mi? Hava karardıktan sonra gireceksiniz; sis ve yağmur da var. Yapabiliyorsanız bütün işi sessizce halletmeye çalışın. Eski bir malikâne ama güvenlik sistemleri sağlam ve bolca yükseltilmiş. Bu şartlarda polisin dikkatini ne kadar az çekersek o kadar iyi. Ama çatışmaya geçmek zorundaysanız işi çabucak bitirin."] = "TAMAM, SALEM'E GİDİP AÇIK ARTIRMA BAŞLAMADAN HEMEN ÖNCE ŞATAFATLI ZENGİN AHMAKLARIN PARTİSİNDEN ESERİ ÇALACAĞIZ, DEĞİL Mİ? HAVA KARARDIKTAN SONRA GİRECEKSİNİZ; SİS VE YAĞMUR DA VAR. YAPABİLİYORSANIZ BÜTÜN İŞİ SESSİZCE HALLETMEYE ÇALIŞIN. ESKİ BİR MALİKÂNE AMA GÜVENLİK SİSTEMLERİ SAĞLAM VE BOLCA YÜKSELTİLMİŞ. BU ŞARTLARDA POLİSİN DİKKATİNİ NE KADAR AZ ÇEKERSEK O KADAR İYİ. AMA ÇATIŞMAYA GEÇMEK ZORUNDAYSANIZ İŞİ ÇABUCAK BİTİRİN.",
["Tamam, Salem'e gidip müzayede başlamadan hemen önce zengin aptalların şık partisinden eseri çalacağız, ha? Hava karardıktan sonra gireceksiniz. Sisli ve yağmurlu, mümkünse bütün işi sessizce yapmaya çalışın. Eski bir malikâne ama güvenlik sistemleri oldukça sağlam, birçok yenileme yapılmış. Bu şartlarda adamların dikkatini ne kadar az çekersek o kadar iyi. Ama ses çıkarmanız gerekirse çabuk çabuk bitirin."] = "TAMAM, SALEM'E GİDİP MÜZAYEDE BAŞLAMADAN HEMEN ÖNCE ZENGİN APTALLARIN ŞIK PARTİSİNDEN ESERİ ÇALACAĞIZ, HA? HAVA KARARDIKTAN SONRA GİRECEKSİNİZ. SİSLİ VE YAĞMURLU, MÜMKÜNSE BÜTÜN İŞİ SESSİZCE YAPMAYA ÇALIŞIN. ESKİ BİR MALİKÂNE AMA GÜVENLİK SİSTEMLERİ OLDUKÇA SAĞLAM, BİRÇOK YENİLEME YAPILMIŞ. BU ŞARTLARDA ADAMLARIN DİKKATİNİ NE KADAR AZ ÇEKERSEK O KADAR İYİ. AMA SES ÇIKARMANIZ GEREKİRSE ÇABUK ÇABUK BİTİRİN.",
["Tamam, Tasteful kulübünü ziyaret edip, şey, nakit rezervlerini özgürleştireceğiz. Özel bir şey yok. Müdürün ofisini bulun, kalabalığı kontrol edin, tek parça çıktığımızdan emin olun."] = "TAMAM, TASTEFUL KULÜBÜNÜ ZİYARET EDİP, ŞEY, NAKİT REZERVLERİNİ ÖZGÜRLEŞTİRECEĞİZ. ÖZEL BİR ŞEY YOK. MÜDÜRÜN OFİSİNİ BULUN, KALABALIĞI KONTROL EDİN, TEK PARÇA ÇIKTIĞIMIZDAN EMİN OLUN.",
["Tamam, Taxman sunucuya gidiyor... sanırım."] = "TAMAM, TAXMAN SUNUCUYA GİDİYOR... SANIRIM.",
["Tamam, Tin Boy'u çalın!"] = "TAMAM, TİN BOY'U ÇALIN!",
["Tamam, Vlad için her zamanki iş. Tacı alacağız, isterseniz mücevherleri de. Tacı aldığınız sürece bu işi istediğiniz gibi yapabilirsiniz. Bitince minibüse dönün. "] = "TAMAM, VLAD İÇİN HER ZAMANKİ İŞ. TACI ALACAĞIZ, İSTERSENİZ MÜCEVHERLERİ DE. TACI ALDIĞINIZ SÜRECE BU İŞİ İSTEDİĞİNİZ GİBİ YAPABİLİRSİNİZ. BİTİNCE MİNİBÜSE DÖNÜN. ",
["Tamam, Vlad memnun görünüyor. İstediğiniz zaman gidebilirsiniz dostlar!"] = "TAMAM, VLAD MEMNUN GÖRÜNÜYOR. İSTEDİĞİNİZ ZAMAN GİDEBİLİRSİNİZ DOSTLAR!",
["Tamam, Vlad memnun görünüyor. İstediğiniz zaman gidebilirsiniz dostlar."] = "TAMAM, VLAD MEMNUN GÖRÜNÜYOR. İSTEDİĞİNİZ ZAMAN GİDEBİLİRSİNİZ DOSTLAR.",
["Tamam, Vlad'in anlaşmadaki kısmı tamam. Bununla yetinebilir ya da devam edip daha fazla çanta alabilirsiniz."] = "TAMAM, VLAD'İN ANLAŞMADAKİ KISMI TAMAM. BUNUNLA YETİNEBİLİR YA DA DEVAM EDİP DAHA FAZLA ÇANTA ALABİLİRSİNİZ.",
["Tamam, Vlad'ın eski mahallesine yaklaşıyoruz. İçeri girip Vlad'ın parasını alın. Bu insanlara çılgın Vlad'dan kimsenin kaçamayacağını gösterin. Polis tepenize binmeden sıvışın."] = "TAMAM, VLAD'IN ESKİ MAHALLESİNE YAKLAŞIYORUZ. İÇERİ GİRİP VLAD'IN PARASINI ALIN. BU İNSANLARA ÇILGIN VLAD'DAN KİMSENİN KAÇAMAYACAĞINI GÖSTERİN. POLİS TEPENİZE BİNMEDEN SIVIŞIN.",
["Tamam, Yakaladın Beni!"] = "TAMAM, YAKALADIN BENİ!",
["Tamam, adamımız bu. Ganimeti araca yükleyin."] = "TAMAM, ADAMIMIZ BU. GANİMETİ ARACA YÜKLEYİN.",
["Tamam, adamımız parkın yakınındaki bir sokağa geliyor..."] = "TAMAM, ADAMIMIZ PARKIN YAKININDAKİ BİR SOKAĞA GELİYOR...",
["Tamam, adamımızın hangi mahkûm nakil aracında olduğunu bilmiyoruz. Dört kamyonun her birine testere yerleştirseniz iyi olur!"] = "TAMAM, ADAMIMIZIN HANGİ MAHKÛM NAKİL ARACINDA OLDUĞUNU BİLMİYORUZ. DÖRT KAMYONUN HER BİRİNE TESTERE YERLEŞTİRSENİZ İYİ OLUR!",
["Tamam, adresi aldık. Dağlarda, yüksek güvenlikli bir villada yaşıyor. Gözden uzak, lüks bir bölge. Hiç istihbarat olmadan, körlemesine gireceğiz. Silahlanın da gidelim. "] = "TAMAM, ADRESİ ALDIK. DAĞLARDA, YÜKSEK GÜVENLİKLİ BİR VİLLADA YAŞIYOR. GÖZDEN UZAK, LÜKS BİR BÖLGE. HİÇ İSTİHBARAT OLMADAN, KÖRLEMESİNE GİRECEĞİZ. SİLAHLANIN DA GİDELİM. ",
["Tamam, af belgelerimiz kasa dairesinde kilitli. Daha yakından bakın."] = "TAMAM, AF BELGELERİMİZ KASA DAİRESİNDE KİLİTLİ. DAHA YAKINDAN BAKIN.",
["Tamam, aklınızı işe verin. Evde hâlâ başımıza bela olabilecek bir sürü delil var. Halledin."] = "TAMAM, AKLINIZI İŞE VERİN. EVDE HÂLÂ BAŞIMIZA BELA OLABİLECEK BİR SÜRÜ DELİL VAR. HALLEDİN.",
["Tamam, alabileceğim bu kadar."] = "TAMAM, ALABİLECEĞİM BU KADAR.",
["Tamam, alarm kapandı. İyi iş. İstediğiniz gibi girip çıkabilirsiniz."] = "TAMAM, ALARM KAPANDI. İYİ İŞ. İSTEDİĞİNİZ GİBİ GİRİP ÇIKABİLİRSİNİZ.",
["Tamam, alarm kapıda ikinci bir kilidi devreye soktu. Manyetik mühür. Açmak için terminal lazım. Bir tane bulayım."] = "TAMAM, ALARM KAPIDA İKİNCİ BİR KİLİDİ DEVREYE SOKTU. MANYETİK MÜHÜR. AÇMAK İÇİN TERMİNAL LAZIM. BİR TANE BULAYIM.",
["Tamam, aldık, biraz daha dayanın."] = "TAMAM, ALDIK, BİRAZ DAHA DAYANIN.",
["Tamam, aldık. O parolaları çıkarmak için sabırsızlanıyorum!"] = "TAMAM, ALDIK. O PAROLALARI ÇIKARMAK İÇİN SABIRSIZLANIYORUM!",
["Tamam, aldım. Bu bok bitti mi?"] = "TAMAM, ALDIM. BU BOK BİTTİ Mİ?",
["Tamam, aldım. Şimdi mutlu musun?"] = "TAMAM, ALDIM. ŞİMDİ MUTLU MUSUN?",
["Tamam, aldınız, çıkalım buradan!"] = "TAMAM, ALDINIZ, ÇIKALIM BURADAN!",
["Tamam, aldınız. Çıkalım buradan!"] = "TAMAM, ALDINIZ. ÇIKALIM BURADAN!",
["Tamam, aldınız. Şimdi kapıyı açın."] = "TAMAM, ALDINIZ. ŞİMDİ KAPIYI AÇIN.",
["Tamam, aldığım istihbarata göre oralarda bir yerde termit saklanıyor olabilir. Aramaya başlayın. Bulunca bariyerin üstüne koyun."] = "TAMAM, ALDIĞIM İSTİHBARATA GÖRE ORALARDA BİR YERDE TERMİT SAKLANIYOR OLABİLİR. ARAMAYA BAŞLAYIN. BULUNCA BARİYERİN ÜSTÜNE KOYUN.",
["Tamam, alma noktasındayım!"] = "TAMAM, ALMA NOKTASINDAYIM!",
["Tamam, almaya geldiğimi aldım! Beni kamyona götürün de şu şeyleri birleştireyim."] = "TAMAM, ALMAYA GELDİĞİMİ ALDIM! BENİ KAMYONA GÖTÜRÜN DE ŞU ŞEYLERİ BİRLEŞTİREYİM.",
["Tamam, almaya geldiğiniz şeyi aldınız. Yeni bilgiler getirebilecek eski bir tanıdık, değil mi? Onu sıkı kilit altında tutun."] = "TAMAM, ALMAYA GELDİĞİNİZ ŞEYİ ALDINIZ. YENİ BİLGİLER GETİREBİLECEK ESKİ BİR TANIDIK, DEĞİL Mİ? ONU SIKI KİLİT ALTINDA TUTUN.",
["Tamam, altın kasa dairesinde. "] = "TAMAM, ALTIN KASA DAİRESİNDE. ",
["Tamam, altıncı dalga geliyor!"] = "TAMAM, ALTINCI DALGA GELİYOR!",
["Tamam, alınacağınız bölgeyi temizleyin!"] = "TAMAM, ALINACAĞINIZ BÖLGEYİ TEMİZLEYİN!",
["Tamam, alışveriş merkezi ileride. Girin, elinizde ne varsa saldırın ve çıkın. İnsan kaybını en aza indirin. Bu işte zarar mala verilecek, cana değil. Sana diyorum Wolf."] = "TAMAM, ALIŞVERİŞ MERKEZİ İLERİDE. GİRİN, ELİNİZDE NE VARSA SALDIRIN VE ÇIKIN. İNSAN KAYBINI EN AZA İNDİRİN. BU İŞTE ZARAR MALA VERİLECEK, CANA DEĞİL. SANA DİYORUM WOLF.",
["Tamam, ana bilgisayara dönüp ikinci kutuyu aramanız gerekiyor."] = "TAMAM, ANA BİLGİSAYARA DÖNÜP İKİNCİ KUTUYU ARAMANIZ GEREKİYOR.",
["Tamam, anahtar kartını aldım."] = "TAMAM, ANAHTAR KARTINI ALDIM.",
["Tamam, anahtarları bulmanız gerekecek."] = "TAMAM, ANAHTARLARI BULMANIZ GEREKECEK.",
["Tamam, anahtarı aldınız. Mükemmel. Şimdi kullanın!"] = "TAMAM, ANAHTARI ALDINIZ. MÜKEMMEL. ŞİMDİ KULLANIN!",
["Tamam, anahtarı arabada bırakmamışlar. Akıllı polisler."] = "TAMAM, ANAHTARI ARABADA BIRAKMAMIŞLAR. AKILLI POLİSLER.",
["Tamam, anladım. Başlıyoruz."] = "TAMAM, ANLADIM. BAŞLIYORUZ.",
["Tamam, anlaşmayı yaptım. Rehinenin kelepçelerini çıkarın da ekip arkadaşımızı geri alalım."] = "TAMAM, ANLAŞMAYI YAPTIM. REHİNENİN KELEPÇELERİNİ ÇIKARIN DA EKİP ARKADAŞIMIZI GERİ ALALIM.",
["Tamam, anlaşmayı yaptığı videoyu buldum... İnanılmaz. Adam gösterişe bayılıyor."] = "TAMAM, ANLAŞMAYI YAPTIĞI VİDEOYU BULDUM... İNANILMAZ. ADAM GÖSTERİŞE BAYILIYOR.",
["Tamam, anlaştığımız asgari miktar bu. Şoförü çağırıyorum."] = "TAMAM, ANLAŞTIĞIMIZ ASGARİ MİKTAR BU. ŞOFÖRÜ ÇAĞIRIYORUM.",
["Tamam, anlaşılan yakın zamanda sistemi yenilemişler. İşimiz biraz zorlaşıyor."] = "TAMAM, ANLAŞILAN YAKIN ZAMANDA SİSTEMİ YENİLEMİŞLER. İŞİMİZ BİRAZ ZORLAŞIYOR.",
["Tamam, araba anahtarlarını bulun. Wang bir yere kilitlemiş."] = "TAMAM, ARABA ANAHTARLARINI BULUN. WANG BİR YERE KİLİTLEMİŞ.",
["Tamam, araba çalma vakti."] = "TAMAM, ARABA ÇALMA VAKTİ.",
["Tamam, arabayı o konteynerin içine park edip uzaklaşın!"] = "TAMAM, ARABAYI O KONTEYNERİN İÇİNE PARK EDİP UZAKLAŞIN!",
["Tamam, aradığımız bu. Karıştırıcıyı yerleştirin. The Elephant bunun seçimi kazandıracağını söylüyor."] = "TAMAM, ARADIĞIMIZ BU. KARIŞTIRICIYI YERLEŞTİRİN. THE ELEPHANT BUNUN SEÇİMİ KAZANDIRACAĞINI SÖYLÜYOR.",
["Tamam, aradığımız heykel o sandıklardan birinde olmalı ama açmak için levye gerekecek. Dikkatli olun, Jiu Feng sık sık bubi tuzağı kurulduğunu söyledi!"] = "TAMAM, ARADIĞIMIZ HEYKEL O SANDIKLARDAN BİRİNDE OLMALI AMA AÇMAK İÇİN LEVYE GEREKECEK. DİKKATLİ OLUN, JIU FENG SIK SIK BUBİ TUZAĞI KURULDUĞUNU SÖYLEDİ!",
["Tamam, aradığımız o olmalı. Üzerinden parmak izi alın, olur mu?"] = "TAMAM, ARADIĞIMIZ O OLMALI. ÜZERİNDEN PARMAK İZİ ALIN, OLUR MU?",
["Tamam, aradığımız parçanın kenarları altın kaplama."] = "TAMAM, ARADIĞIMIZ PARÇANIN KENARLARI ALTIN KAPLAMA.",
["Tamam, aradığımız taç bu!"] = "TAMAM, ARADIĞIMIZ TAÇ BU!",
["Tamam, aradığımız şey şuradaki zımbırtı. Koruyun, olur mu?"] = "TAMAM, ARADIĞIMIZ ŞEY ŞURADAKİ ZIMBIRTI. KORUYUN, OLUR MU?",
["Tamam, aradığınız şeye benziyor."] = "TAMAM, ARADIĞINIZ ŞEYE BENZİYOR.",
["Tamam, aramaya devam edin."] = "TAMAM, ARAMAYA DEVAM EDİN.",
["Tamam, arayan onlar."] = "TAMAM, ARAYAN ONLAR.",
["Tamam, arka sokaktan geliyorlar."] = "TAMAM, ARKA SOKAKTAN GELİYORLAR.",
["Tamam, artık Vlad'in özel ganimetinin hepsini alabilirsiniz ama fazla gürültü çıkarmayın."] = "TAMAM, ARTIK VLAD'İN ÖZEL GANİMETİNİN HEPSİNİ ALABİLİRSİNİZ AMA FAZLA GÜRÜLTÜ ÇIKARMAYIN.",
["Tamam, artık Vlad'ın bütün mücevherlerini alabilirsiniz. İstediğiniz kamyon dışarıda bekliyor!"] = "TAMAM, ARTIK VLAD'IN BÜTÜN MÜCEVHERLERİNİ ALABİLİRSİNİZ. İSTEDİĞİNİZ KAMYON DIŞARIDA BEKLİYOR!",
["Tamam, artık Vlad'ın bütün özel ganimetini alıp dışarıdaki minibüse götürebilirsiniz."] = "TAMAM, ARTIK VLAD'IN BÜTÜN ÖZEL GANİMETİNİ ALIP DIŞARIDAKİ MİNİBÜSE GÖTÜREBİLİRSİNİZ.",
["Tamam, artık alarmı çalmalıyım!"] = "TAMAM, ARTIK ALARMI ÇALMALIYIM!",
["Tamam, artık duruma ayak uyduracaksınız galiba!"] = "TAMAM, ARTIK DURUMA AYAK UYDURACAKSINIZ GALİBA!",
["Tamam, artık geri dönüş noktasını geçtiniz... Koşun! Koşun! Arkanıza bakmayın!"] = "TAMAM, ARTIK GERİ DÖNÜŞ NOKTASINI GEÇTİNİZ... KOŞUN! KOŞUN! ARKANIZA BAKMAYIN!",
["Tamam, artık gidebiliriz ama yapabiliyorsanız hepsini alın."] = "TAMAM, ARTIK GİDEBİLİRİZ AMA YAPABİLİYORSANIZ HEPSİNİ ALIN.",
["Tamam, artık güvende olmalı. Bahçenin dışındaki masaya işaret fişeği koyun. Helikopteri getirmek için yakın."] = "TAMAM, ARTIK GÜVENDE OLMALI. BAHÇENİN DIŞINDAKİ MASAYA İŞARET FİŞEĞİ KOYUN. HELİKOPTERİ GETİRMEK İÇİN YAKIN.",
["Tamam, artık içerideki adamımızla buluşabilirsiniz. Kapılara gidin."] = "TAMAM, ARTIK İÇERİDEKİ ADAMIMIZLA BULUŞABİLİRSİNİZ. KAPILARA GİDİN.",
["Tamam, artık oyalanamayız. Gözetleme odasındaki bilgisayara erişmemi sağlayın yeter, uzaktan hallederim."] = "TAMAM, ARTIK OYALANAMAYIZ. GÖZETLEME ODASINDAKİ BİLGİSAYARA ERİŞMEMİ SAĞLAYIN YETER, UZAKTAN HALLEDERİM.",
["Tamam, artık tehlikeden uzak olmalı. Avlunun dışındaki masaya bir işaret fişeği koyun. Tahliyeye işaret vermek için yakın."] = "TAMAM, ARTIK TEHLİKEDEN UZAK OLMALI. AVLUNUN DIŞINDAKİ MASAYA BİR İŞARET FİŞEĞİ KOYUN. TAHLİYEYE İŞARET VERMEK İÇİN YAKIN.",
["Tamam, artık tepedesiniz, değil mi? Onu sandalyeye bağlayın, sonra balonu bırakın. Uçak her an gelebilir."] = "TAMAM, ARTIK TEPEDESİNİZ, DEĞİL Mİ? ONU SANDALYEYE BAĞLAYIN, SONRA BALONU BIRAKIN. UÇAK HER AN GELEBİLİR.",
["Tamam, artık yeterince aldık, gidelim!"] = "TAMAM, ARTIK YETERİNCE ALDIK, GİDELİM!",
["Tamam, artık... dürüst olma vakti. Kokain... keçilere dolduruldu. Evet, keçilere. Bir de kaçmışlar. Haha, kurnaz keçiler, ha?! Bulun onları!"] = "TAMAM, ARTIK... DÜRÜST OLMA VAKTİ. KOKAİN... KEÇİLERE DOLDURULDU. EVET, KEÇİLERE. BİR DE KAÇMIŞLAR. HAHA, KURNAZ KEÇİLER, HA?! BULUN ONLARI!",
["Tamam, arıyorum..."] = "TAMAM, ARIYORUM...",
["Tamam, asgari miktarda nakit toplamamız gerekiyor. O miktara ulaşınca size bir araba yollarım. Kalıp daha fazlasını almak isterseniz de buyurun."] = "TAMAM, ASGARİ MİKTARDA NAKİT TOPLAMAMIZ GEREKİYOR. O MİKTARA ULAŞINCA SİZE BİR ARABA YOLLARIM. KALIP DAHA FAZLASINI ALMAK İSTERSENİZ DE BUYURUN.",
["Tamam, asgari miktarımız bu. İsterseniz daha alın ya da çıkın oradan."] = "TAMAM, ASGARİ MİKTARIMIZ BU. İSTERSENİZ DAHA ALIN YA DA ÇIKIN ORADAN.",
["Tamam, asgari nakit miktarına ihtiyacımız var. Toplayınca size arabayı göndereceğim. Kalıp daha fazlasını almak isterseniz de buyurun."] = "TAMAM, ASGARİ NAKİT MİKTARINA İHTİYACIMIZ VAR. TOPLAYINCA SİZE ARABAYI GÖNDERECEĞİM. KALIP DAHA FAZLASINI ALMAK İSTERSENİZ DE BUYURUN.",
["Tamam, ayakkabıları alın!"] = "TAMAM, AYAKKABILARI ALIN!",
["Tamam, ayrılma vakti. Güverteye çıkıp filikalardan birine el koyun."] = "TAMAM, AYRILMA VAKTİ. GÜVERTEYE ÇIKIP FİLİKALARDAN BİRİNE EL KOYUN.",
["Tamam, ayrılma vakti. Yeterince aldığımızı düşünüyorsanız gidebilirsiniz. Ama hepsini almaktan da zarar gelmez."] = "TAMAM, AYRILMA VAKTİ. YETERİNCE ALDIĞIMIZI DÜŞÜNÜYORSANIZ GİDEBİLİRSİNİZ. AMA HEPSİNİ ALMAKTAN DA ZARAR GELMEZ.",
["Tamam, az kaldı. Sunucuyu kapıp minibüse taşıyın. Asılın hadi."] = "TAMAM, AZ KALDI. SUNUCUYU KAPIP MİNİBÜSE TAŞIYIN. ASILIN HADİ.",
["Tamam, açacağım."] = "TAMAM, AÇACAĞIM.",
["Tamam, ağır yükleri kaldırmaya geldim!"] = "TAMAM, AĞIR YÜKLERİ KALDIRMAYA GELDİM!",
["Tamam, bakalım buna nasıl tepki verecek."] = "TAMAM, BAKALIM BUNA NASIL TEPKİ VERECEK.",
["Tamam, bakalım elimizde ne var."] = "TAMAM, BAKALIM ELİMİZDE NE VAR.",
["Tamam, bakalım kasa dairesini şimdi açabilecek miyim."] = "TAMAM, BAKALIM KASA DAİRESİNİ ŞİMDİ AÇABİLECEK MİYİM.",
["Tamam, bakalım yemi yuttu mu."] = "TAMAM, BAKALIM YEMİ YUTTU MU.",
["Tamam, bakalım... hımm... bunun için bir plan lazım..."] = "TAMAM, BAKALIM... HIMM... BUNUN İÇİN BİR PLAN LAZIM...",
["Tamam, balonu bırakın!"] = "TAMAM, BALONU BIRAKIN!",
["Tamam, bana bir iki dakika verin. Bu uçaksavarı devre dışı bırakacağım."] = "TAMAM, BANA BİR İKİ DAKİKA VERİN. BU UÇAKSAVARI DEVRE DIŞI BIRAKACAĞIM.",
["Tamam, banka bu. Önce mekânı kolaçan etmenizi öneririm. Sonra kasa dairesini istediğiniz gibi vurun. Genelde güvenlik odası olur, dikkatli olun."] = "TAMAM, BANKA BU. ÖNCE MEKÂNI KOLAÇAN ETMENİZİ ÖNERİRİM. SONRA KASA DAİRESİNİ İSTEDİĞİNİZ GİBİ VURUN. GENELDE GÜVENLİK ODASI OLUR, DİKKATLİ OLUN.",
["Tamam, banka bu. Önce mekânı kolaçan etmenizi, sonra arka otoparkta bir yerlerdeki termal matkabı almanızı öneririm. Kasa dairesini istediğiniz gibi açın. Genellikle bir güvenlik odası olur, dikkatli olun."] = "TAMAM, BANKA BU. ÖNCE MEKÂNI KOLAÇAN ETMENİZİ, SONRA ARKA OTOPARKTA BİR YERLERDEKİ TERMAL MATKABI ALMANIZI ÖNERİRİM. KASA DAİRESİNİ İSTEDİĞİNİZ GİBİ AÇIN. GENELLİKLE BİR GÜVENLİK ODASI OLUR, DİKKATLİ OLUN.",
["Tamam, bariyer dubalarını halletmeden önce küçük bir sapma yapalım."] = "TAMAM, BARİYER DUBALARINI HALLETMEDEN ÖNCE KÜÇÜK BİR SAPMA YAPALIM.",
["Tamam, barmen şimdiye Li Deng'i ilaçlamış olmalı. Delmek istemiyorsanız anahtarı ondan almak kolay olur."] = "TAMAM, BARMEN ŞİMDİYE Lİ DENG'İ İLAÇLAMIŞ OLMALI. DELMEK İSTEMİYORSANIZ ANAHTARI ONDAN ALMAK KOLAY OLUR.",
["Tamam, baskı kalıplarını hangi trenin taşıdığını biliyoruz. Paravan nakliye şirketinin işaretli olduğu vagonları bulun."] = "TAMAM, BASKI KALIPLARINI HANGİ TRENİN TAŞIDIĞINI BİLİYORUZ. PARAVAN NAKLİYE ŞİRKETİNİN İŞARETLİ OLDUĞU VAGONLARI BULUN.",
["Tamam, baskın vakti. İçeride Garnet ürünleri de görebilirsiniz. Bunca yaptığımızdan sonra hâlâ iş başında olmalarını seviyorum. Bu işe değmesi için en az iki çanta lazım."] = "TAMAM, BASKIN VAKTİ. İÇERİDE GARNET ÜRÜNLERİ DE GÖREBİLİRSİNİZ. BUNCA YAPTIĞIMIZDAN SONRA HÂLÂ İŞ BAŞINDA OLMALARINI SEVİYORUM. BU İŞE DEĞMESİ İÇİN EN AZ İKİ ÇANTA LAZIM.",
["Tamam, bağlantımız bir dakika içinde metro girişini açabilecek. Hazır olun..."] = "TAMAM, BAĞLANTIMIZ BİR DAKİKA İÇİNDE METRO GİRİŞİNİ AÇABİLECEK. HAZIR OLUN...",
["Tamam, bağlantıyı kurun."] = "TAMAM, BAĞLANTIYI KURUN.",
["Tamam, baş küratörü arayın."] = "TAMAM, BAŞ KÜRATÖRÜ ARAYIN.",
["Tamam, başlangıç için 5 bin olmalı."] = "TAMAM, BAŞLANGIÇ İÇİN 5 BİN OLMALI.",
["Tamam, başlıyorum... Wuh duh ma huh tah duh fong kwong duh wai shung!"] = "TAMAM, BAŞLIYORUM... WUH DUH MA HUH TAH DUH FONG KWONG DUH WAİ SHUNG!",
["Tamam, başlıyoruz."] = "TAMAM, BAŞLIYORUZ.",
["Tamam, bekleyin. İki dakikaya oradayım!"] = "TAMAM, BEKLEYİN. İKİ DAKİKAYA ORADAYIM!",
["Tamam, belki taç yakınlardadır. Binanın içinde olmalı."] = "TAMAM, BELKİ TAÇ YAKINLARDADIR. BİNANIN İÇİNDE OLMALI.",
["Tamam, ben bunu düzeltirken soluklanın."] = "TAMAM, BEN BUNU DÜZELTİRKEN SOLUKLANIN.",
["Tamam, beni bağlayın, birkaç saniyede hallederim."] = "TAMAM, BENİ BAĞLAYIN, BİRKAÇ SANİYEDE HALLEDERİM.",
["Tamam, beni buldunuz. Çok eğlenceli dostlarım. Şimdi beni yeniden kaybetmeye ne dersiniz?"] = "TAMAM, BENİ BULDUNUZ. ÇOK EĞLENCELİ DOSTLARIM. ŞİMDİ BENİ YENİDEN KAYBETMEYE NE DERSİNİZ?",
["Tamam, beni dinleyin. O kapılar açılınca çıkmaya hazır olsanız iyi olur."] = "TAMAM, BENİ DİNLEYİN. O KAPILAR AÇILINCA ÇIKMAYA HAZIR OLSANIZ İYİ OLUR.",
["Tamam, beni dizüstü bilgisayara bağlayın. Bu iş kısa sürer."] = "TAMAM, BENİ DİZÜSTÜ BİLGİSAYARA BAĞLAYIN. BU İŞ KISA SÜRER.",
["Tamam, beni izleyin ama görünmeyin."] = "TAMAM, BENİ İZLEYİN AMA GÖRÜNMEYİN.",
["Tamam, beni net duyduğunuzu varsayıyorum. Kaybedecek vaktimiz yok, doğrudan başlayalım."] = "TAMAM, BENİ NET DUYDUĞUNUZU VARSAYIYORUM. KAYBEDECEK VAKTİMİZ YOK, DOĞRUDAN BAŞLAYALIM.",
["Tamam, beni takip edin, sizi çıkaralım. Umarım istediğinizi almışsınızdır."] = "TAMAM, BENİ TAKİP EDİN, SİZİ ÇIKARALIM. UMARIM İSTEDİĞİNİZİ ALMIŞSINIZDIR.",
["Tamam, beni tekrar bağlayın."] = "TAMAM, BENİ TEKRAR BAĞLAYIN.",
["Tamam, beni yakaladınız, fena yakaladınız!"] = "TAMAM, BENİ YAKALADINIZ, FENA YAKALADINIZ!",
["Tamam, beni yeniden bağlayın."] = "TAMAM, BENİ YENİDEN BAĞLAYIN.",
["Tamam, benim kaçma vaktim geldi!"] = "TAMAM, BENİM KAÇMA VAKTİM GELDİ!",
["Tamam, benzin deposu ve egzoz boruları gerekiyor. Atölyede bir tavan lifti var, motorcular onları orada tutuyor. Aşağı indirip bana atın."] = "TAMAM, BENZİN DEPOSU VE EGZOZ BORULARI GEREKİYOR. ATÖLYEDE BİR TAVAN LİFTİ VAR, MOTORCULAR ONLARI ORADA TUTUYOR. AŞAĞI İNDİRİP BANA ATIN.",
["Tamam, beşinci dalga geliyor!"] = "TAMAM, BEŞİNCİ DALGA GELİYOR!",
["Tamam, bifteklere dönmem lazım. Yukarıda tanesi yüz dolar gibi bir şey, biliyorsunuz. Bitirince beni görün, tamam mı? Acele edin."] = "TAMAM, BİFTEKLERE DÖNMEM LAZIM. YUKARIDA TANESİ YÜZ DOLAR GİBİ BİR ŞEY, BİLİYORSUNUZ. BİTİRİNCE BENİ GÖRÜN, TAMAM MI? ACELE EDİN.",
["Tamam, bilgisayar yeniden düzgünce çalışıyor, sisteme sızıyor."] = "TAMAM, BİLGİSAYAR YENİDEN DÜZGÜNCE ÇALIŞIYOR, SİSTEME SIZIYOR.",
["Tamam, bilgisayarı tekrar açın da yarım kalan işimize dönelim."] = "TAMAM, BİLGİSAYARI TEKRAR AÇIN DA YARIM KALAN İŞİMİZE DÖNELİM.",
["Tamam, bilgisayarı yeniden başlatın da tekrar bağlanalım."] = "TAMAM, BİLGİSAYARI YENİDEN BAŞLATIN DA TEKRAR BAĞLANALIM.",
["Tamam, bilişimci gerekecek gibi. Bulun, çabuk çabuk!"] = "TAMAM, BİLİŞİMCİ GEREKECEK GİBİ. BULUN, ÇABUK ÇABUK!",
["Tamam, binayı işaretlediğim bölge panosuna bağlayın. Birkaç sigortayı yakabilirim, böylece önümüzdeki yol da açılır."] = "TAMAM, BİNAYI İŞARETLEDİĞİM BÖLGE PANOSUNA BAĞLAYIN. BİRKAÇ SİGORTAYI YAKABİLİRİM, BÖYLECE ÖNÜMÜZDEKİ YOL DA AÇILIR.",
["Tamam, binin de buradan defolup gidelim."] = "TAMAM, BİNİN DE BURADAN DEFOLUP GİDELİM.",
["Tamam, bir Anahtar Kartı bulundu. Diğerinin peşine düşün."] = "TAMAM, BİR ANAHTAR KARTI BULUNDU. DİĞERİNİN PEŞİNE DÜŞÜN.",
["Tamam, bir aptal gidip kendini oraya kilitlemiş. Gaz tüpü falan bulursanız onu boğup dışarı çıkarabiliriz."] = "TAMAM, BİR APTAL GİDİP KENDİNİ ORAYA KİLİTLEMİŞ. GAZ TÜPÜ FALAN BULURSANIZ ONU BOĞUP DIŞARI ÇIKARABİLİRİZ.",
["Tamam, bir bakalım. Şifre için bir fikrim var. Eve bağlı telefon direğini bulun. İlginç bir telefon görüşmesi yapacağız."] = "TAMAM, BİR BAKALIM. ŞİFRE İÇİN BİR FİKRİM VAR. EVE BAĞLI TELEFON DİREĞİNİ BULUN. İLGİNÇ BİR TELEFON GÖRÜŞMESİ YAPACAĞIZ.",
["Tamam, bir bakalım..."] = "TAMAM, BİR BAKALIM...",
["Tamam, bir bakayım..."] = "TAMAM, BİR BAKAYIM...",
["Tamam, bir düşüneyim... Ne lazım bize? Ha, atölye. Evet. Atölyeye gidin, özel aletleri alet kutularında bulursunuz."] = "TAMAM, BİR DÜŞÜNEYİM... NE LAZIM BİZE? HA, ATÖLYE. EVET. ATÖLYEYE GİDİN, ÖZEL ALETLERİ ALET KUTULARINDA BULURSUNUZ.",
["Tamam, bir fikrim var. Aşağıda ağa bağlı ne bulursanız hacklemenizi istiyorum. Veri tabanlarına erişebilirsem kamyonumuzun nereye gittiğini bulabilirim."] = "TAMAM, BİR FİKRİM VAR. AŞAĞIDA AĞA BAĞLI NE BULURSANIZ HACKLEMENİZİ İSTİYORUM. VERİ TABANLARINA ERİŞEBİLİRSEM KAMYONUMUZUN NEREYE GİTTİĞİNİ BULABİLİRİM.",
["Tamam, bir fikrim var. Küçük bir telefon görüşmesi yapacağız. Evin dışındaki telefona gidin."] = "TAMAM, BİR FİKRİM VAR. KÜÇÜK BİR TELEFON GÖRÜŞMESİ YAPACAĞIZ. EVİN DIŞINDAKİ TELEFONA GİDİN.",
["Tamam, bir fikrim var. Sızmayı değiştirip bunu McKendrick'in rakibi Belediye Başkanı Schwartz için yapmışız gibi gösterebilirim. Suçu onun üzerine atabiliriz. Skandal çıkacaksa işimize yarayan bir skandal olsun!"] = "TAMAM, BİR FİKRİM VAR. SIZMAYI DEĞİŞTİRİP BUNU MCKENDRİCK'İN RAKİBİ BELEDİYE BAŞKANI SCHWARTZ İÇİN YAPMIŞIZ GİBİ GÖSTEREBİLİRİM. SUÇU ONUN ÜZERİNE ATABİLİRİZ. SKANDAL ÇIKACAKSA İŞİMİZE YARAYAN BİR SKANDAL OLSUN!",
["Tamam, bir güvenlik duvarı devre dışı. Sıradakine gidin."] = "TAMAM, BİR GÜVENLİK DUVARI DEVRE DIŞI. SIRADAKİNE GİDİN.",
["Tamam, bir kapı daha! FBI tepemizde, acele edin!"] = "TAMAM, BİR KAPI DAHA! FBI TEPEMİZDE, ACELE EDİN!",
["Tamam, bir saniye."] = "TAMAM, BİR SANİYE.",
["Tamam, bir soluklanın. Gerisini ben yaparım, olur mu?"] = "TAMAM, BİR SOLUKLANIN. GERİSİNİ BEN YAPARIM, OLUR MU?",
["Tamam, bir tane kaldı!"] = "TAMAM, BİR TANE KALDI!",
["Tamam, bir çanta tamam! En az üç tane daha lazım."] = "TAMAM, BİR ÇANTA TAMAM! EN AZ ÜÇ TANE DAHA LAZIM.",
["Tamam, biraz az."] = "TAMAM, BİRAZ AZ.",
["Tamam, biraz azaltın, öldürmek istemiyoruz."] = "TAMAM, BİRAZ AZALTIN, ÖLDÜRMEK İSTEMİYORUZ.",
["Tamam, biraz dayanın."] = "TAMAM, BİRAZ DAYANIN.",
["Tamam, biraz etrafta turlayacağım. İhtiyaç olduğunda hazır olacağım."] = "TAMAM, BİRAZ ETRAFTA TURLAYACAĞIM. İHTİYAÇ OLDUĞUNDA HAZIR OLACAĞIM.",
["Tamam, biraz para yakma vakti."] = "TAMAM, BİRAZ PARA YAKMA VAKTİ.",
["Tamam, biraz sallanıyor ama taşımayı göze almalıyız. Jiu Feng'in bağlantısı dışarıda mini yükleyiciyle bekliyor. Vlad'ı ona götürün, çabuk çabuk."] = "TAMAM, BİRAZ SALLANIYOR AMA TAŞIMAYI GÖZE ALMALIYIZ. JIU FENG'İN BAĞLANTISI DIŞARIDA MİNİ YÜKLEYİCİYLE BEKLİYOR. VLAD'I ONA GÖTÜRÜN, ÇABUK ÇABUK.",
["Tamam, biraz zamana ihtiyacım olacak."] = "TAMAM, BİRAZ ZAMANA İHTİYACIM OLACAK.",
["Tamam, birini aldım!"] = "TAMAM, BİRİNİ ALDIM!",
["Tamam, birkaç dosya eksik. Tanık ifadeleri, Arşivde tutuluyor. O dosyaları getirin!"] = "TAMAM, BİRKAÇ DOSYA EKSİK. TANIK İFADELERİ, ARŞİVDE TUTULUYOR. O DOSYALARI GETİRİN!",
["Tamam, birkaç tanık ifadesi eksik galiba. Kâğıt kopyalarına bakmamız gerek. Arşive gidip alın."] = "TAMAM, BİRKAÇ TANIK İFADESİ EKSİK GALİBA. KÂĞIT KOPYALARINA BAKMAMIZ GEREK. ARŞİVE GİDİP ALIN.",
["Tamam, bitti! Zordu ama evdeki bazı kepenkleri açmayı başardım."] = "TAMAM, BİTTİ! ZORDU AMA EVDEKİ BAZI KEPENKLERİ AÇMAYI BAŞARDIM.",
["Tamam, bitti. Bakalım çılgın Rus'un sırada bizim için ne işi var. "] = "TAMAM, BİTTİ. BAKALIM ÇILGIN RUS'UN SIRADA BİZİM İÇİN NE İŞİ VAR. ",
["Tamam, bitti. Bu kez oldukça iyi para aldık ama muhtemelen daha uzun dayanabilirdik."] = "TAMAM, BİTTİ. BU KEZ OLDUKÇA İYİ PARA ALDIK AMA MUHTEMELEN DAHA UZUN DAYANABİLİRDİK.",
["Tamam, bitti. Gidip hastaya bakın."] = "TAMAM, BİTTİ. GİDİP HASTAYA BAKIN.",
["Tamam, bize uçurarak getiriyor. Kontrol edeceğiz."] = "TAMAM, BİZE UÇURARAK GETİRİYOR. KONTROL EDECEĞİZ.",
["Tamam, boruları görüyor musunuz, sızdırıyor? Duvardan aşağı? Bok olmuş!"] = "TAMAM, BORULARI GÖRÜYOR MUSUNUZ, SIZDIRIYOR? DUVARDAN AŞAĞI? BOK OLMUŞ!",
["Tamam, bu Deng olmalı. Hangi sosyetik pislik dişlerine bunu yaptırır? Özel masaj odasındaki kasayı bulun ve kodu alın."] = "TAMAM, BU DENG OLMALI. HANGİ SOSYETİK PİSLİK DİŞLERİNE BUNU YAPTIRIR? ÖZEL MASAJ ODASINDAKİ KASAYI BULUN VE KODU ALIN.",
["Tamam, bu alışveriş merkezinin sahibi Vlad'a haraç ödemeyi kesmiş. Onun hatası."] = "TAMAM, BU ALIŞVERİŞ MERKEZİNİN SAHİBİ VLAD'A HARAÇ ÖDEMEYİ KESMİŞ. ONUN HATASI.",
["Tamam, bu arada iyileşin. Kokaini bırakın ve bir doktor çantası koyun."] = "TAMAM, BU ARADA İYİLEŞİN. KOKAİNİ BIRAKIN VE BİR DOKTOR ÇANTASI KOYUN.",
["Tamam, bu bebeğe bir taht lazım. Nereden bulacağımızı biliyorum. Şu arka bahçeyi görüyor musunuz? Sığınakta bir dünya eşya saklıyorlar. Gidip şık bir sele getirin."] = "TAMAM, BU BEBEĞE BİR TAHT LAZIM. NEREDEN BULACAĞIMIZI BİLİYORUM. ŞU ARKA BAHÇEYİ GÖRÜYOR MUSUNUZ? SIĞINAKTA BİR DÜNYA EŞYA SAKLIYORLAR. GİDİP ŞIK BİR SELE GETİRİN.",
["Tamam, bu benim hatam."] = "TAMAM, BU BENİM HATAM.",
["Tamam, bu bir banka soygunu ama hedefimiz kiralık kasalar, yani biraz farklı. İçeri girin, muhafızlara ve kameralara dikkat edin, kasa dairesini matkapla açın, sonra kiralık kasalarda ne varsa alın."] = "TAMAM, BU BİR BANKA SOYGUNU AMA HEDEFİMİZ KİRALIK KASALAR, YANİ BİRAZ FARKLI. İÇERİ GİRİN, MUHAFIZLARA VE KAMERALARA DİKKAT EDİN, KASA DAİRESİNİ MATKAPLA AÇIN, SONRA KİRALIK KASALARDA NE VARSA ALIN.",
["Tamam, bu bir başlangıç. Bunun gibi üç tane daha lazım. Alın! Galerinin yanındaki otoparkta duran minibüse götürün, işi bitirelim."] = "TAMAM, BU BİR BAŞLANGIÇ. BUNUN GİBİ ÜÇ TANE DAHA LAZIM. ALIN! GALERİNİN YANINDAKİ OTOPARKTA DURAN MİNİBÜSE GÖTÜRÜN, İŞİ BİTİRELİM.",
["Tamam, bu ciddi anlamda AŞIRIYDI. Vlad bayılacak. Çok işine yarayacak."] = "TAMAM, BU CİDDİ ANLAMDA AŞIRIYDI. VLAD BAYILACAK. ÇOK İŞİNE YARAYACAK.",
["Tamam, bu eğlenceli olacak. Bir gece kulübünü vuruyoruz."] = "TAMAM, BU EĞLENCELİ OLACAK. BİR GECE KULÜBÜNÜ VURUYORUZ.",
["Tamam, bu güzelliğe bir kalp gerekecek. Motor. Onu demek istiyorum. Sanırım kulüp binasının içinde tutuyorlar."] = "TAMAM, BU GÜZELLİĞE BİR KALP GEREKECEK. MOTOR. ONU DEMEK İSTİYORUM. SANIRIM KULÜP BİNASININ İÇİNDE TUTUYORLAR.",
["Tamam, bu güzelliği yürütmek için bir motor gerekecek. Kulüp binasına birkaç tane koyduklarını gördüğüme neredeyse eminim."] = "TAMAM, BU GÜZELLİĞİ YÜRÜTMEK İÇİN BİR MOTOR GEREKECEK. KULÜP BİNASINA BİRKAÇ TANE KOYDUKLARINI GÖRDÜĞÜME NEREDEYSE EMİNİM.",
["Tamam, bu herhâlde ilginç bir şey yapıyor. Deneyin."] = "TAMAM, BU HERHÂLDE İLGİNÇ BİR ŞEY YAPIYOR. DENEYİN.",
["Tamam, bu iş görür! Sırada ne var?"] = "TAMAM, BU İŞ GÖRÜR! SIRADA NE VAR?",
["Tamam, bu iş için termal matkap gerekecek. Adamım bankanın arka tarafına sakladı. Alıp Kasa Dairesinde işe koyulun. Güvenlik kameraları ve bir sürü sivil olduğunu unutmayın. Gidip altını kazanın, millet."] = "TAMAM, BU İŞ İÇİN TERMAL MATKAP GEREKECEK. ADAMIM BANKANIN ARKA TARAFINA SAKLADI. ALIP KASA DAİRESİNDE İŞE KOYULUN. GÜVENLİK KAMERALARI VE BİR SÜRÜ SİVİL OLDUĞUNU UNUTMAYIN. GİDİP ALTINI KAZANIN, MİLLET.",
["Tamam, bu işe yaradı galiba. Taşınabilecek kadar toparlanmış görünüyor, oradan çıkmasına yardım edin. Jiu Feng'in adamı dışarıda mini yükleyiciyle bekliyor. Hepiniz çıkınca onu bir doktor karşılayacak."] = "TAMAM, BU İŞE YARADI GALİBA. TAŞINABİLECEK KADAR TOPARLANMIŞ GÖRÜNÜYOR, ORADAN ÇIKMASINA YARDIM EDİN. JIU FENG'İN ADAMI DIŞARIDA MİNİ YÜKLEYİCİYLE BEKLİYOR. HEPİNİZ ÇIKINCA ONU BİR DOKTOR KARŞILAYACAK.",
["Tamam, bu işleri değiştirir. Aramayı bırakıp bir sunucunun sistemini kırın."] = "TAMAM, BU İŞLERİ DEĞİŞTİRİR. ARAMAYI BIRAKIP BİR SUNUCUNUN SİSTEMİNİ KIRIN.",
["Tamam, bu kadar alabilirim."] = "TAMAM, BU KADAR ALABİLİRİM.",
["Tamam, bu kadar yeter. Kaydı alın da çıkalım buradan."] = "TAMAM, BU KADAR YETER. KAYDI ALIN DA ÇIKALIM BURADAN.",
["Tamam, bu kadar yeter..."] = "TAMAM, BU KADAR YETER...",
["Tamam, bu kadar! Gidiyorum buradan!"] = "TAMAM, BU KADAR! GİDİYORUM BURADAN!",
["Tamam, bu kadar, kaçmam lazım!"] = "TAMAM, BU KADAR, KAÇMAM LAZIM!",
["Tamam, bu kadar. Gizlice çıkalım da ne var ne yok görelim."] = "TAMAM, BU KADAR. GİZLİCE ÇIKALIM DA NE VAR NE YOK GÖRELİM.",
["Tamam, bu kadarı yeter. Pişirmeye devam edebilir ya da çıkabilirsiniz."] = "TAMAM, BU KADARI YETER. PİŞİRMEYE DEVAM EDEBİLİR YA DA ÇIKABİLİRSİNİZ.",
["Tamam, bu küçük bebeği kaldırıp çıkarmamız gerekiyor."] = "TAMAM, BU KÜÇÜK BEBEĞİ KALDIRIP ÇIKARMAMIZ GEREKİYOR.",
["Tamam, bu pisliği temizlediğimize göre sunucu odasını bulma vakti."] = "TAMAM, BU PİSLİĞİ TEMİZLEDİĞİMİZE GÖRE SUNUCU ODASINI BULMA VAKTİ.",
["Tamam, bu yeterli olmalı! Geliyorum."] = "TAMAM, BU YETERLİ OLMALI! GELİYORUM.",
["Tamam, bu yeterli olmalı. Şimdi bilgisayarı tekrar başlatın."] = "TAMAM, BU YETERLİ OLMALI. ŞİMDİ BİLGİSAYARI TEKRAR BAŞLATIN.",
["Tamam, bu zavallı alışveriş merkezini bugünlük yeterince hırpaladık. İyi iş. Vlad amacına ulaştı. Bundan sonra biraz ortalıktan kaybolmalıyız bence."] = "TAMAM, BU ZAVALLI ALIŞVERİŞ MERKEZİNİ BUGÜNLÜK YETERİNCE HIRPALADIK. İYİ İŞ. VLAD AMACINA ULAŞTI. BUNDAN SONRA BİRAZ ORTALIKTAN KAYBOLMALIYIZ BENCE.",
["Tamam, bu... doğru mu? En azından patlamadı. Sıradaki malzemeyi karıştırma vakti."] = "TAMAM, BU... DOĞRU MU? EN AZINDAN PATLAMADI. SIRADAKİ MALZEMEYİ KARIŞTIRMA VAKTİ.",
["Tamam, bulduk! Kodu panik odasında kullanın!"] = "TAMAM, BULDUK! KODU PANİK ODASINDA KULLANIN!",
["Tamam, buldum. Biraz zamana ihtiyacım var."] = "TAMAM, BULDUM. BİRAZ ZAMANA İHTİYACIM VAR.",
["Tamam, buldunuz! Şimdi onu o kulenin tepesine çıkarın!"] = "TAMAM, BULDUNUZ! ŞİMDİ ONU O KULENİN TEPESİNE ÇIKARIN!",
["Tamam, buldunuz. Şimdi o kasayı matkapla açın, muhtemelen nakitle dolu."] = "TAMAM, BULDUNUZ. ŞİMDİ O KASAYI MATKAPLA AÇIN, MUHTEMELEN NAKİTLE DOLU.",
["Tamam, bulduğum bütün bilgiyi bu sunucuya kopyaladım. Sunucuyu alın da çıkalım buradan."] = "TAMAM, BULDUĞUM BÜTÜN BİLGİYİ BU SUNUCUYA KOPYALADIM. SUNUCUYU ALIN DA ÇIKALIM BURADAN.",
["Tamam, buluşma yerindeyim!"] = "TAMAM, BULUŞMA YERİNDEYİM!",
["Tamam, bunda birbirine bağlı iki kilit var gibi. Diğer kilidi bulup ona da bir kırıcı takın."] = "TAMAM, BUNDA BİRBİRİNE BAĞLI İKİ KİLİT VAR GİBİ. DİĞER KİLİDİ BULUP ONA DA BİR KIRICI TAKIN.",
["Tamam, bunda dikkatli olun. Yanlış düğmelere basarsanız neye dönüşeceğinizi kimse bilemez."] = "TAMAM, BUNDA DİKKATLİ OLUN. YANLIŞ DÜĞMELERE BASARSANIZ NEYE DÖNÜŞECEĞİNİZİ KİMSE BİLEMEZ.",
["Tamam, bundan sonra her kuruşa ihtiyacımız olacak herhâlde. Acil durum Krugerrand altınlarıma da Interpol el koydu. O yüzden gidip şu testereyi bulun, olur mu?"] = "TAMAM, BUNDAN SONRA HER KURUŞA İHTİYACIMIZ OLACAK HERHÂLDE. ACİL DURUM KRUGERRAND ALTINLARIMA DA INTERPOL EL KOYDU. O YÜZDEN GİDİP ŞU TESTEREYİ BULUN, OLUR MU?",
["Tamam, bundan sonra ne geliyor..."] = "TAMAM, BUNDAN SONRA NE GELİYOR...",
["Tamam, bunları elden çıkarmaya hemen başlayacağım. Zor olmaz; tam ideal mallar. Güzel iş!"] = "TAMAM, BUNLARI ELDEN ÇIKARMAYA HEMEN BAŞLAYACAĞIM. ZOR OLMAZ; TAM İDEAL MALLAR. GÜZEL İŞ!",
["Tamam, bunları uzaktan patlatacağım. Siz arabalara odaklanın."] = "TAMAM, BUNLARI UZAKTAN PATLATACAĞIM. SİZ ARABALARA ODAKLANIN.",
["Tamam, bunları uzaktan patlatacağım. Şimdi depoya dönün. Kapısı açık!"] = "TAMAM, BUNLARI UZAKTAN PATLATACAĞIM. ŞİMDİ DEPOYA DÖNÜN. KAPISI AÇIK!",
["Tamam, bunu bir daha yapalım. Umarım bu kez olur."] = "TAMAM, BUNU BİR DAHA YAPALIM. UMARIM BU KEZ OLUR.",
["Tamam, bunu devre dışı bıraktım ama hâlâ bir tane daha var!"] = "TAMAM, BUNU DEVRE DIŞI BIRAKTIM AMA HÂLÂ BİR TANE DAHA VAR!",
["Tamam, bunu hallettik. Kârlı bir varlıktı, değil mi?"] = "TAMAM, BUNU HALLETTİK. KÂRLI BİR VARLIKTI, DEĞİL Mİ?",
["Tamam, bunu hâlâ yapabiliriz. Mr Blonde, özel sosu getirdin, değil mi?"] = "TAMAM, BUNU HÂLÂ YAPABİLİRİZ. MR BLONDE, ÖZEL SOSU GETİRDİN, DEĞİL Mİ?",
["Tamam, bunu uçurup götürüyorum!"] = "TAMAM, BUNU UÇURUP GÖTÜRÜYORUM!",
["Tamam, bunun yerine bu bölgeye geliyorum. Çok daha güvenli."] = "TAMAM, BUNUN YERİNE BU BÖLGEYE GELİYORUM. ÇOK DAHA GÜVENLİ.",
["Tamam, bununla yetiniriz."] = "TAMAM, BUNUNLA YETİNİRİZ.",
["Tamam, burada aşağıda."] = "TAMAM, BURADA AŞAĞIDA.",
["Tamam, burada bedava kazanç var. Bu adamlar bodrumda para basıyor. Onları kalıplarından kurtaracağız. Doğru kişiye satarsak milyonlar kazanırız!"] = "TAMAM, BURADA BEDAVA KAZANÇ VAR. BU ADAMLAR BODRUMDA PARA BASIYOR. ONLARI KALIPLARINDAN KURTARACAĞIZ. DOĞRU KİŞİYE SATARSAK MİLYONLAR KAZANIRIZ!",
["Tamam, burada kenara çekip maskelerinizi takın."] = "TAMAM, BURADA KENARA ÇEKİP MASKELERİNİZİ TAKIN.",
["Tamam, burada sonsuza kadar kalamam!"] = "TAMAM, BURADA SONSUZA KADAR KALAMAM!",
["Tamam, burada toparlıyorum, neredeyse bitti. Ayıklanacak çok bilgi olacak. Ama o götü bulacağız. Ötmeden susturacağız."] = "TAMAM, BURADA TOPARLIYORUM, NEREDEYSE BİTTİ. AYIKLANACAK ÇOK BİLGİ OLACAK. AMA O GÖTÜ BULACAĞIZ. ÖTMEDEN SUSTURACAĞIZ.",
["Tamam, buradaki bilim insanları bayağı ileri teknoloji kullanıyor. El izi onayı için baş bilim insanı gerekecek. Nereye saklandığına bakın."] = "TAMAM, BURADAKİ BİLİM İNSANLARI BAYAĞI İLERİ TEKNOLOJİ KULLANIYOR. EL İZİ ONAYI İÇİN BAŞ BİLİM İNSANI GEREKECEK. NEREYE SAKLANDIĞINA BAKIN.",
["Tamam, buradaki işim bitti!"] = "TAMAM, BURADAKİ İŞİM BİTTİ!",
["Tamam, buradaki işimiz bitti. Rögar kapağının altı kanalizasyona açılıyor. Çıkış yolunuz bu!"] = "TAMAM, BURADAKİ İŞİMİZ BİTTİ. RÖGAR KAPAĞININ ALTI KANALİZASYONA AÇILIYOR. ÇIKIŞ YOLUNUZ BU!",
["Tamam, buradan defolma vakti. Gidin!"] = "TAMAM, BURADAN DEFOLMA VAKTİ. GİDİN!",
["Tamam, buradayken biraz ganimet alalım. Ernesto'nun ofisinde zemine gömülü bir kasa var. Girdiğiniz araba yolunun yakınında çekme vinçleri var; alın ve bağlayın."] = "TAMAM, BURADAYKEN BİRAZ GANİMET ALALIM. ERNESTO'NUN OFİSİNDE ZEMİNE GÖMÜLÜ BİR KASA VAR. GİRDİĞİNİZ ARABA YOLUNUN YAKININDA ÇEKME VİNÇLERİ VAR; ALIN VE BAĞLAYIN.",
["Tamam, buradayım ve defolup gitmeye hazırım."] = "TAMAM, BURADAYIM VE DEFOLUP GİTMEYE HAZIRIM.",
["Tamam, buradayım, binin!"] = "TAMAM, BURADAYIM, BİNİN!",
["Tamam, buradayım. Ben çalışırken arkamı kollayın!"] = "TAMAM, BURADAYIM. BEN ÇALIŞIRKEN ARKAMI KOLLAYIN!",
["Tamam, buradayım. Çabuk binin de çıkalım buradan."] = "TAMAM, BURADAYIM. ÇABUK BİNİN DE ÇIKALIM BURADAN.",
["Tamam, buradayım. Çantaları buraya getirin!"] = "TAMAM, BURADAYIM. ÇANTALARI BURAYA GETİRİN!",
["Tamam, buralarda bir sürü pahalı sanat eseri var. Servet değerindedir. Bir yere yığıp yakacağız, onu dışarı çeker."] = "TAMAM, BURALARDA BİR SÜRÜ PAHALI SANAT ESERİ VAR. SERVET DEĞERİNDEDİR. BİR YERE YIĞIP YAKACAĞIZ, ONU DIŞARI ÇEKER.",
["Tamam, burası fazla kızışıyor. Minibüs gidiyor. Size helikopter ayarlayacağım. Sakin olun."] = "TAMAM, BURASI FAZLA KIZIŞIYOR. MİNİBÜS GİDİYOR. SİZE HELİKOPTER AYARLAYACAĞIM. SAKİN OLUN.",
["Tamam, burası güvenli evin. İş dışında zamanını burada geçireceksin. Şimdilik pek bir şey yok ama biraz zaman ver. Üzerinde çalışıyorum. Yakında biraz dekorasyon yapmana da izin vereceğim."] = "TAMAM, BURASI GÜVENLİ EVİN. İŞ DIŞINDA ZAMANINI BURADA GEÇİRECEKSİN. ŞİMDİLİK PEK BİR ŞEY YOK AMA BİRAZ ZAMAN VER. ÜZERİNDE ÇALIŞIYORUM. YAKINDA BİRAZ DEKORASYON YAPMANA DA İZİN VERECEĞİM.",
["Tamam, burası. Taç için girmeden önce keşif yapmak isteyebilirsiniz."] = "TAMAM, BURASI. TAÇ İÇİN GİRMEDEN ÖNCE KEŞİF YAPMAK İSTEYEBİLİRSİNİZ.",
["Tamam, buraya almaya geldiğimiz EMP güvenceye alındı. Ama isterseniz geri dönüp ek ganimet alacak vaktiniz var."] = "TAMAM, BURAYA ALMAYA GELDİĞİMİZ EMP GÜVENCEYE ALINDI. AMA İSTERSENİZ GERİ DÖNÜP EK GANİMET ALACAK VAKTİNİZ VAR.",
["Tamam, buraya kadar başardınız, herifler teklif verdi. Bence daha fazlası için dayanabiliriz."] = "TAMAM, BURAYA KADAR BAŞARDINIZ, HERİFLER TEKLİF VERDİ. BENCE DAHA FAZLASI İÇİN DAYANABİLİRİZ.",
["Tamam, burayı havaya uçuralım. C4 limuzinde. Alın!"] = "TAMAM, BURAYI HAVAYA UÇURALIM. C4 LİMUZİNDE. ALIN!",
["Tamam, bölgedeyim ama polis binanın çevresindeki bütün çatılara keskin nişancı yerleştirmiş. C4'ü bırakabilmem için önce onları indirmelisiniz."] = "TAMAM, BÖLGEDEYİM AMA POLİS BİNANIN ÇEVRESİNDEKİ BÜTÜN ÇATILARA KESKİN NİŞANCI YERLEŞTİRMİŞ. C4'Ü BIRAKABİLMEM İÇİN ÖNCE ONLARI İNDİRMELİSİNİZ.",
["Tamam, bütün dosyalar yüklendi. İşe yaramalı."] = "TAMAM, BÜTÜN DOSYALAR YÜKLENDİ. İŞE YARAMALI.",
["Tamam, bırakın çalışsın. Polisin karşı saldırısı yolda. Uzak tutun."] = "TAMAM, BIRAKIN ÇALIŞSIN. POLİSİN KARŞI SALDIRISI YOLDA. UZAK TUTUN.",
["Tamam, bırakın!"] = "TAMAM, BIRAKIN!",
["Tamam, cam silme platformunu unutun. Çantaları dışarı taşımak için çelik halatları kullanmanız gerekecek!"] = "TAMAM, CAM SİLME PLATFORMUNU UNUTUN. ÇANTALARI DIŞARI TAŞIMAK İÇİN ÇELİK HALATLARI KULLANMANIZ GEREKECEK!",
["Tamam, cankurtaran filikalarını unutun. Daha riskli olsa da her ihtimale karşı bir helikopter bekletiyordum. Ama ateş yakarak ona işaret vermeniz gerek. "] = "TAMAM, CANKURTARAN FİLİKALARINI UNUTUN. DAHA RİSKLİ OLSA DA HER İHTİMALE KARŞI BİR HELİKOPTER BEKLETİYORDUM. AMA ATEŞ YAKARAK ONA İŞARET VERMENİZ GEREK. ",
["Tamam, cephanelik şifresinin rakamları bunlar. Girin!"] = "TAMAM, CEPHANELİK ŞİFRESİNİN RAKAMLARI BUNLAR. GİRİN!",
["Tamam, cesede dönüp sakla."] = "TAMAM, CESEDE DÖNÜP SAKLA.",
["Tamam, daha önce insanların seni izlediğini söylemiştim. Özellikle bir adam seninle ilgileniyor. Bu yeni bağlantıyla büyük bir işe girişebiliriz ama aklındaki iş zor olacak. Hazırlanman gerekiyor. Biraz daha hazır olduğunda geri gel, ben de gerekeni ayarlarım."] = "TAMAM, DAHA ÖNCE İNSANLARIN SENİ İZLEDİĞİNİ SÖYLEMİŞTİM. ÖZELLİKLE BİR ADAM SENİNLE İLGİLENİYOR. BU YENİ BAĞLANTIYLA BÜYÜK BİR İŞE GİRİŞEBİLİRİZ AMA AKLINDAKİ İŞ ZOR OLACAK. HAZIRLANMAN GEREKİYOR. BİRAZ DAHA HAZIR OLDUĞUNDA GERİ GEL, BEN DE GEREKENİ AYARLARIM.",
["Tamam, dansı bırakma vakti."] = "TAMAM, DANSI BIRAKMA VAKTİ.",
["Tamam, dava dosyamı buldum, inceliyorum."] = "TAMAM, DAVA DOSYAMI BULDUM, İNCELİYORUM.",
["Tamam, demek böyle yapmak istiyorsunuz? B planına geçelim!"] = "TAMAM, DEMEK BÖYLE YAPMAK İSTİYORSUNUZ? B PLANINA GEÇELİM!",
["Tamam, demiryolu sahasında yerinizi aldınız. Gözünüz açık olsun. Takım elbiselileri kollayın. Yakınlarda çalışan araç göremiyorum ama bu pek bir şey ifade etmez. Trenin vagonuna gidip bağlantıyı bekleyin."] = "TAMAM, DEMİRYOLU SAHASINDA YERİNİZİ ALDINIZ. GÖZÜNÜZ AÇIK OLSUN. TAKIM ELBİSELİLERİ KOLLAYIN. YAKINLARDA ÇALIŞAN ARAÇ GÖREMİYORUM AMA BU PEK BİR ŞEY İFADE ETMEZ. TRENİN VAGONUNA GİDİP BAĞLANTIYI BEKLEYİN.",
["Tamam, deneklerden biri olmalı. Gereken bilgiyi almak için cesedi tarayıcıya götürün."] = "TAMAM, DENEKLERDEN BİRİ OLMALI. GEREKEN BİLGİYİ ALMAK İÇİN CESEDİ TARAYICIYA GÖTÜRÜN.",
["Tamam, depoda olmalı. Lanet kapıyı matkapla delin."] = "TAMAM, DEPODA OLMALI. LANET KAPIYI MATKAPLA DELİN.",
["Tamam, devam edin! Orada olmalı!"] = "TAMAM, DEVAM EDİN! ORADA OLMALI!",
["Tamam, devre kutusundaki ışıklar karolara karşılık geliyor. Geçerken onları rehber alın. Kimse yanlış karoya basamaz, yoksa iş çok daha fazla karışır!"] = "TAMAM, DEVRE KUTUSUNDAKİ IŞIKLAR KAROLARA KARŞILIK GELİYOR. GEÇERKEN ONLARI REHBER ALIN. KİMSE YANLIŞ KAROYA BASAMAZ, YOKSA İŞ ÇOK DAHA FAZLA KARIŞIR!",
["Tamam, dikkatli olma vakti. Bölgede devriye gezen başka bir güvenlikçi var. Bahse girerim kayıp arkadaşlarını arıyor. Ne olursa olsun bu adamı öldürmeyin. Anlaşıldı mı? Onu öldürmeyin, yoksa sıçtık."] = "TAMAM, DİKKATLİ OLMA VAKTİ. BÖLGEDE DEVRİYE GEZEN BAŞKA BİR GÜVENLİKÇİ VAR. BAHSE GİRERİM KAYIP ARKADAŞLARINI ARIYOR. NE OLURSA OLSUN BU ADAMI ÖLDÜRMEYİN. ANLAŞILDI MI? ONU ÖLDÜRMEYİN, YOKSA SIÇTIK.",
["Tamam, dikkatli olun! Baştan sona gizlice gitmeye değecek çocuklar. Alarm olmazsa bu kumpas kusursuz olacak!"] = "TAMAM, DİKKATLİ OLUN! BAŞTAN SONA GİZLİCE GİTMEYE DEĞECEK ÇOCUKLAR. ALARM OLMAZSA BU KUMPAS KUSURSUZ OLACAK!",
["Tamam, dinamiti kasaya atıp patlatın. Su işi görecek!"] = "TAMAM, DİNAMİTİ KASAYA ATIP PATLATIN. SU İŞİ GÖRECEK!",
["Tamam, dinleyin. Arka bahçede bir sığınak var, değil mi? Nedenini sormayın. Girin, süslü görünen bir sele bulacaksınız."] = "TAMAM, DİNLEYİN. ARKA BAHÇEDE BİR SIĞINAK VAR, DEĞİL Mİ? NEDENİNİ SORMAYIN. GİRİN, SÜSLÜ GÖRÜNEN BİR SELE BULACAKSINIZ.",
["Tamam, dinleyin. Bu iş biraz çetrefilli. Bir motosikleti söküp özel bir şeyler almam lazım. Yani hünerlerimi gösterebilmem için beni garaja götürmeniz gerekiyor."] = "TAMAM, DİNLEYİN. BU İŞ BİRAZ ÇETREFİLLİ. BİR MOTOSİKLETİ SÖKÜP ÖZEL BİR ŞEYLER ALMAM LAZIM. YANİ HÜNERLERİMİ GÖSTEREBİLMEM İÇİN BENİ GARAJA GÖTÜRMENİZ GEREKİYOR.",
["Tamam, dinleyin. Burada sonsuza kadar kalamam!"] = "TAMAM, DİNLEYİN. BURADA SONSUZA KADAR KALAMAM!",
["Tamam, dinleyin. Kasa dairesine girmek için güvenlik sistemini aşmalısınız. İstihbarata göre anahtar kartı Garnet'ın oğlu Ralph'ta ama doğum günü çocuğu da o, bu sorun olabilir. Bir de biri daha güvenli olacağını söylediği için farklı dizüstü bilgisayarlara bölünmüş üç parçalı güvenlik kodu var. Hiç alarm çaldırmadan hem anahtar kartını hem kodu ele geçirmeniz harika olur. Bay Garnet'a sessizce bir oyun oynayabilirsiniz."] = "TAMAM, DİNLEYİN. KASA DAİRESİNE GİRMEK İÇİN GÜVENLİK SİSTEMİNİ AŞMALISINIZ. İSTİHBARATA GÖRE ANAHTAR KARTI GARNET'IN OĞLU RALPH'TA AMA DOĞUM GÜNÜ ÇOCUĞU DA O, BU SORUN OLABİLİR. BİR DE BİRİ DAHA GÜVENLİ OLACAĞINI SÖYLEDİĞİ İÇİN FARKLI DİZÜSTÜ BİLGİSAYARLARA BÖLÜNMÜŞ ÜÇ PARÇALI GÜVENLİK KODU VAR. HİÇ ALARM ÇALDIRMADAN HEM ANAHTAR KARTINI HEM KODU ELE GEÇİRMENİZ HARİKA OLUR. BAY GARNET'A SESSİZCE BİR OYUN OYNAYABİLİRSİNİZ.",
["Tamam, dinleyin. Müşterimiz biraz ürkek. Normalde, bilirsiniz, kanun çiğnemeyi içeren işlere bulaşmaz. O yüzden hepinizin trende olması gerek."] = "TAMAM, DİNLEYİN. MÜŞTERİMİZ BİRAZ ÜRKEK. NORMALDE, BİLİRSİNİZ, KANUN ÇİĞNEMEYİ İÇEREN İŞLERE BULAŞMAZ. O YÜZDEN HEPİNİZİN TRENDE OLMASI GEREK.",
["Tamam, dinleyin. O kasa dairesine girmek için güvenlik sistemini aşmalısınız. İstihbarata göre Anahtar Kartı Garnet'ın oğlu Ralph'te ama doğum günü kutlanan çocuk da o; bu sorun olabilir. Bir de, biri daha güvenli olacağını söylediği için farklı dizüstü bilgisayarlara bölünmüş üç parçalı güvenlik şifresi var. Hiç alarm çaldırmadan hem Anahtar Kartını hem de şifreyi alabilsek harika olur. Belki Mr. Garnet'ı sessizce oyuna getiririz."] = "TAMAM, DİNLEYİN. O KASA DAİRESİNE GİRMEK İÇİN GÜVENLİK SİSTEMİNİ AŞMALISINIZ. İSTİHBARATA GÖRE ANAHTAR KARTI GARNET'IN OĞLU RALPH'TE AMA DOĞUM GÜNÜ KUTLANAN ÇOCUK DA O; BU SORUN OLABİLİR. BİR DE, BİRİ DAHA GÜVENLİ OLACAĞINI SÖYLEDİĞİ İÇİN FARKLI DİZÜSTÜ BİLGİSAYARLARA BÖLÜNMÜŞ ÜÇ PARÇALI GÜVENLİK ŞİFRESİ VAR. HİÇ ALARM ÇALDIRMADAN HEM ANAHTAR KARTINI HEM DE ŞİFREYİ ALABİLSEK HARİKA OLUR. BELKİ MR. GARNET'I SESSİZCE OYUNA GETİRİRİZ.",
["Tamam, dinleyin. Twitch ileride, köprünün hemen diğer tarafında bekliyor. Kamyonu var. Doğrudan içine sürün, bu iş bitsin."] = "TAMAM, DİNLEYİN. TWITCH İLERİDE, KÖPRÜNÜN HEMEN DİĞER TARAFINDA BEKLİYOR. KAMYONU VAR. DOĞRUDAN İÇİNE SÜRÜN, BU İŞ BİTSİN.",
["Tamam, dizüstü bilgisayar bu. Aferin!"] = "TAMAM, DİZÜSTÜ BİLGİSAYAR BU. AFERİN!",
["Tamam, dokuzuncu dalga geliyor!"] = "TAMAM, DOKUZUNCU DALGA GELİYOR!",
["Tamam, dostlar. Erişim aldım ama aşmam biraz sürecek."] = "TAMAM, DOSTLAR. ERİŞİM ALDIM AMA AŞMAM BİRAZ SÜRECEK.",
["Tamam, dostlar. Kasa Dairesine gidin."] = "TAMAM, DOSTLAR. KASA DAİRESİNE GİDİN.",
["Tamam, dostlar. Çabucak dışarı çıkıp Mr Pink'i kurtarın, olur mu?"] = "TAMAM, DOSTLAR. ÇABUCAK DIŞARI ÇIKIP MR PİNK'İ KURTARIN, OLUR MU?",
["Tamam, dostumuz çıkış yolunu biliyordur, değil mi? Sizin sadece muhafızlara dikkat etmeniz gerekiyor."] = "TAMAM, DOSTUMUZ ÇIKIŞ YOLUNU BİLİYORDUR, DEĞİL Mİ? SİZİN SADECE MUHAFIZLARA DİKKAT ETMENİZ GEREKİYOR.",
["Tamam, dosyalar bunlar. Hoxton'a geri götürün!"] = "TAMAM, DOSYALAR BUNLAR. HOXTON'A GERİ GÖTÜRÜN!",
["Tamam, dumanı olabildiğince az tutun... Devam edin."] = "TAMAM, DUMANI OLABİLDİĞİNCE AZ TUTUN... DEVAM EDİN.",
["Tamam, durum şu:"] = "TAMAM, DURUM ŞU:",
["Tamam, durum şu: Üstünde kırmızı etiket olan tabloları arıyoruz. Güvenlik epey sıkı olacak, kameralar ve muhafızlar var."] = "TAMAM, DURUM ŞU: ÜSTÜNDE KIRMIZI ETİKET OLAN TABLOLARI ARIYORUZ. GÜVENLİK EPEY SIKI OLACAK, KAMERALAR VE MUHAFIZLAR VAR.",
["Tamam, duyduğunuz helikopter. Adamımızı oraya götürün."] = "TAMAM, DUYDUĞUNUZ HELİKOPTER. ADAMIMIZI ORAYA GÖTÜRÜN.",
["Tamam, döndüm ama her yerde bu kadar polis varken bir bok yapamam. Çatıyı temizlemeniz gerekecek."] = "TAMAM, DÖNDÜM AMA HER YERDE BU KADAR POLİS VARKEN BİR BOK YAPAMAM. ÇATIYI TEMİZLEMENİZ GEREKECEK.",
["Tamam, döndüm! Helikoptere binin!"] = "TAMAM, DÖNDÜM! HELİKOPTERE BİNİN!",
["Tamam, dönüp geliyorum. 60 saniyeye oradayım."] = "TAMAM, DÖNÜP GELİYORUM. 60 SANİYEYE ORADAYIM.",
["Tamam, dördüncü dalga geliyor!"] = "TAMAM, DÖRDÜNCÜ DALGA GELİYOR!",
["Tamam, dört oldu. "] = "TAMAM, DÖRT OLDU. ",
["Tamam, dört!"] = "TAMAM, DÖRT!",
["Tamam, dışarıdasınız. Gaz dağılacak. Bekleyin yeter."] = "TAMAM, DIŞARIDASINIZ. GAZ DAĞILACAK. BEKLEYİN YETER.",
["Tamam, elektrik geldi!"] = "TAMAM, ELEKTRİK GELDİ!",
["Tamam, elektrik geldi. Baskı makinesini yeniden çalıştırın!"] = "TAMAM, ELEKTRİK GELDİ. BASKI MAKİNESİNİ YENİDEN ÇALIŞTIRIN!",
["Tamam, elektrik geldi. Şimdi para basma makinesini tekrar başlatın yeter"] = "TAMAM, ELEKTRİK GELDİ. ŞİMDİ PARA BASMA MAKİNESİNİ TEKRAR BAŞLATIN YETER",
["Tamam, elektrik kesildi. Artık çarpma yok. Umarım."] = "TAMAM, ELEKTRİK KESİLDİ. ARTIK ÇARPMA YOK. UMARIM.",
["Tamam, elektrik kesildi. Artık çarpmaz. Umarım."] = "TAMAM, ELEKTRİK KESİLDİ. ARTIK ÇARPMAZ. UMARIM.",
["Tamam, elektrik panoları düzeltildi. Bilgisayarı yeniden başlatabilirsiniz."] = "TAMAM, ELEKTRİK PANOLARI DÜZELTİLDİ. BİLGİSAYARI YENİDEN BAŞLATABİLİRSİNİZ.",
["Tamam, en az yedi tane daha lazım."] = "TAMAM, EN AZ YEDİ TANE DAHA LAZIM.",
["Tamam, epey süründünüz. Ama para güvene alındı. Temizlik için ekip gönderirim. Siz gözden uzak kalın."] = "TAMAM, EPEY SÜRÜNDÜNÜZ. AMA PARA GÜVENE ALINDI. TEMİZLİK İÇİN EKİP GÖNDERİRİM. SİZ GÖZDEN UZAK KALIN.",
["Tamam, erişim sağladım. Bir saniye bekleyin..."] = "TAMAM, ERİŞİM SAĞLADIM. BİR SANİYE BEKLEYİN...",
["Tamam, erişim sağladım..."] = "TAMAM, ERİŞİM SAĞLADIM...",
["Tamam, eriştim. Devre dışı bırakmamız gereken iki GenSec alarm kutusu var. Sizin için işaretleyeceğim."] = "TAMAM, ERİŞTİM. DEVRE DIŞI BIRAKMAMIZ GEREKEN İKİ GENSEC ALARM KUTUSU VAR. SİZİN İÇİN İŞARETLEYECEĞİM.",
["Tamam, eserlerden biri depo arşivinde tutuluyor gibi görünüyor. O alanı yürüyerek aramanız imkânsız ama ana merkezde kullanabileceğiniz vinçli bir getirme sistemi var. Önce doğru rafı bulmalısınız."] = "TAMAM, ESERLERDEN BİRİ DEPO ARŞİVİNDE TUTULUYOR GİBİ GÖRÜNÜYOR. O ALANI YÜRÜYEREK ARAMANIZ İMKÂNSIZ AMA ANA MERKEZDE KULLANABİLECEĞİNİZ VİNÇLİ BİR GETİRME SİSTEMİ VAR. ÖNCE DOĞRU RAFI BULMALISINIZ.",
["Tamam, etrafa bakın; kaçış minibüsünü bulun!"] = "TAMAM, ETRAFA BAKIN; KAÇIŞ MİNİBÜSÜNÜ BULUN!",
["Tamam, etrafa bakıp bir tane bulmaya çalışın."] = "TAMAM, ETRAFA BAKIP BİR TANE BULMAYA ÇALIŞIN.",
["Tamam, etrafa bakıp o kapıyı aşmamızı sağlayacak bir şey bulun."] = "TAMAM, ETRAFA BAKIP O KAPIYI AŞMAMIZI SAĞLAYACAK BİR ŞEY BULUN.",
["Tamam, eve gidip adresi bulun, dikkatli olun."] = "TAMAM, EVE GİDİP ADRESİ BULUN, DİKKATLİ OLUN.",
["Tamam, eve gidip adresi bulun. Dikkatli olun."] = "TAMAM, EVE GİDİP ADRESİ BULUN. DİKKATLİ OLUN.",
["Tamam, evet, kesinlikle bir sorunumuz var."] = "TAMAM, EVET, KESİNLİKLE BİR SORUNUMUZ VAR.",
["Tamam, evet. O adamı indirmeden geçemeyeceksin. Gösteri zamanı."] = "TAMAM, EVET. O ADAMI İNDİRMEDEN GEÇEMEYECEKSİN. GÖSTERİ ZAMANI.",
["Tamam, evrak çantaları. İlki kumarhane müdüründe, ikincisi masa şefinde, üçüncüsü de güvenlik şefinde."] = "TAMAM, EVRAK ÇANTALARI. İLKİ KUMARHANE MÜDÜRÜNDE, İKİNCİSİ MASA ŞEFİNDE, ÜÇÜNCÜSÜ DE GÜVENLİK ŞEFİNDE.",
["Tamam, eşyaları parçalayın. Neye girişelim..."] = "TAMAM, EŞYALARI PARÇALAYIN. NEYE GİRİŞELİM...",
["Tamam, fark edilmeden epey ilerlediniz ama artık bitti. Polislerin kayıp olduğu bildirildi, bir SWAT ekibi gönderiyorlar. Parti yeni başladı."] = "TAMAM, FARK EDİLMEDEN EPEY İLERLEDİNİZ AMA ARTIK BİTTİ. POLİSLERİN KAYIP OLDUĞU BİLDİRİLDİ, BİR SWAT EKİBİ GÖNDERİYORLAR. PARTİ YENİ BAŞLADI.",
["Tamam, federaller yakında gelir. Sert ve hızlı vurma vakti. Muhafız odasındaki C4'ü bulun."] = "TAMAM, FEDERALLER YAKINDA GELİR. SERT VE HIZLI VURMA VAKTİ. MUHAFIZ ODASINDAKİ C4'Ü BULUN.",
["Tamam, galeri ileride. Hareket algılayıcılara, kameralara ve güvenlikçilere dikkat edin. Girip kırmızı satıldı etiketi olan tablolardan dört tane getirin. Zaman daralıyor millet."] = "TAMAM, GALERİ İLERİDE. HAREKET ALGILAYICILARA, KAMERALARA VE GÜVENLİKÇİLERE DİKKAT EDİN. GİRİP KIRMIZI SATILDI ETİKETİ OLAN TABLOLARDAN DÖRT TANE GETİRİN. ZAMAN DARALIYOR MİLLET.",
["Tamam, ganimet o kapının arkasında."] = "TAMAM, GANİMET O KAPININ ARKASINDA.",
["Tamam, gaz dağıldı. Tekrar girin içeri!"] = "TAMAM, GAZ DAĞILDI. TEKRAR GİRİN İÇERİ!",
["Tamam, gece daha erken. Fedai, bir fedaiye göre fazla akıllı görünüyor. Yanından geçebilir misiniz, yoksa ikna mı istiyor, bakın."] = "TAMAM, GECE DAHA ERKEN. FEDAİ, BİR FEDAİYE GÖRE FAZLA AKILLI GÖRÜNÜYOR. YANINDAN GEÇEBİLİR MİSİNİZ, YOKSA İKNA MI İSTİYOR, BAKIN.",
["Tamam, geldi! Ganimeti oraya taşıyın!"] = "TAMAM, GELDİ! GANİMETİ ORAYA TAŞIYIN!",
["Tamam, geldik. Biraz termit alıp çiftliğe girmek için kullanın."] = "TAMAM, GELDİK. BİRAZ TERMİT ALIP ÇİFTLİĞE GİRMEK İÇİN KULLANIN.",
["Tamam, geldik. Gösteri zamanı."] = "TAMAM, GELDİK. GÖSTERİ ZAMANI.",
["Tamam, geldik. Çalışma vakti."] = "TAMAM, GELDİK. ÇALIŞMA VAKTİ.",
["Tamam, geldim!"] = "TAMAM, GELDİM!",
["Tamam, geldim, binin!"] = "TAMAM, GELDİM, BİNİN!",
["Tamam, geldim. Kayışları palete bağlarsanız şu güzelim para dağını tahliye edebilirim."] = "TAMAM, GELDİM. KAYIŞLARI PALETE BAĞLARSANIZ ŞU GÜZELİM PARA DAĞINI TAHLİYE EDEBİLİRİM.",
["Tamam, geldim. Şimdi beni koruyun."] = "TAMAM, GELDİM. ŞİMDİ BENİ KORUYUN.",
["Tamam, geldim. Şimdi keçileri yükleyin!"] = "TAMAM, GELDİM. ŞİMDİ KEÇİLERİ YÜKLEYİN!",
["Tamam, geldiniz. Kapının yanındaki RFID okuyucusunu görüyor musunuz? Açın."] = "TAMAM, GELDİNİZ. KAPININ YANINDAKİ RFID OKUYUCUSUNU GÖRÜYOR MUSUNUZ? AÇIN.",
["Tamam, geliyorum!"] = "TAMAM, GELİYORUM!",
["Tamam, geliyorum, sunucuyu hazırlayın!"] = "TAMAM, GELİYORUM, SUNUCUYU HAZIRLAYIN!",
["Tamam, gemiyle uluslararası sulara ulaşmamız gerekiyor ama daha fazla mazot lazım."] = "TAMAM, GEMİYLE ULUSLARARASI SULARA ULAŞMAMIZ GEREKİYOR AMA DAHA FAZLA MAZOT LAZIM.",
["Tamam, gereken her şey elinizde. Bulmacayı çözmek için el yazmasını kullanın."] = "TAMAM, GEREKEN HER ŞEY ELİNİZDE. BULMACAYI ÇÖZMEK İÇİN EL YAZMASINI KULLANIN.",
["Tamam, gerekeni aldık. Çıkma vakti."] = "TAMAM, GEREKENİ ALDIK. ÇIKMA VAKTİ.",
["Tamam, gerekenin hepsi bu."] = "TAMAM, GEREKENİN HEPSİ BU.",
["Tamam, geri arama geldi, her şey temiz. Son adım. Sayaç bitince parayı alma vakti."] = "TAMAM, GERİ ARAMA GELDİ, HER ŞEY TEMİZ. SON ADIM. SAYAÇ BİTİNCE PARAYI ALMA VAKTİ.",
["Tamam, gerzekler. Canavar'ı getirme vakti!"] = "TAMAM, GERZEKLER. CANAVAR'I GETİRME VAKTİ!",
["Tamam, geçtim. Ama gerçekten zordu. Bunu yaptığımıza seviniyorum. Gerçekten."] = "TAMAM, GEÇTİM. AMA GERÇEKTEN ZORDU. BUNU YAPTIĞIMIZA SEVİNİYORUM. GERÇEKTEN.",
["Tamam, gidelim. Herkes binsin!"] = "TAMAM, GİDELİM. HERKES BİNSİN!",
["Tamam, gidin gidin gidin! Çıkın oradan!"] = "TAMAM, GİDİN GİDİN GİDİN! ÇIKIN ORADAN!",
["Tamam, gidip C4'ü alın, sonra tam panik odasının üstüne yerleştirin."] = "TAMAM, GİDİP C4'Ü ALIN, SONRA TAM PANİK ODASININ ÜSTÜNE YERLEŞTİRİN.",
["Tamam, gidiyor... Şimdi çamaşır odasından onu takip edin!"] = "TAMAM, GİDİYOR... ŞİMDİ ÇAMAŞIR ODASINDAN ONU TAKİP EDİN!",
["Tamam, gidiyorum!"] = "TAMAM, GİDİYORUM!",
["Tamam, gidiyoruz. Taç Vlad'a gidecek, istediği intikamı alacak. Yardımcı olabildiğimize sevindim. Güvenli evde görüşürüz."] = "TAMAM, GİDİYORUZ. TAÇ VLAD'A GİDECEK, İSTEDİĞİ İNTİKAMI ALACAK. YARDIMCI OLABİLDİĞİMİZE SEVİNDİM. GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["Tamam, girdik. Çalışan doğru füzyon motorunu bulun. Notlarını inceleyin. Çözün şu işi!"] = "TAMAM, GİRDİK. ÇALIŞAN DOĞRU FÜZYON MOTORUNU BULUN. NOTLARINI İNCELEYİN. ÇÖZÜN ŞU İŞİ!",
["Tamam, girdim! *etkilenip ıslık çalar* Bu adamlar şaka yapmıyor. Bir sürü ek güvenlik duvarı var."] = "TAMAM, GİRDİM! *ETKİLENİP ISLIK ÇALAR* BU ADAMLAR ŞAKA YAPMIYOR. BİR SÜRÜ EK GÜVENLİK DUVARI VAR.",
["Tamam, girdim! Bekleyin. Çok uzun sürmez."] = "TAMAM, GİRDİM! BEKLEYİN. ÇOK UZUN SÜRMEZ.",
["Tamam, girdim, bekleyin..."] = "TAMAM, GİRDİM, BEKLEYİN...",
["Tamam, girdim. Bekleyin..."] = "TAMAM, GİRDİM. BEKLEYİN...",
["Tamam, girdim. Bir saniye verin."] = "TAMAM, GİRDİM. BİR SANİYE VERİN.",
["Tamam, girdim. Biraz zaman verin."] = "TAMAM, GİRDİM. BİRAZ ZAMAN VERİN.",
["Tamam, girdim. Laboratuvarın kapısını bir çırpıda açarım."] = "TAMAM, GİRDİM. LABORATUVARIN KAPISINI BİR ÇIRPIDA AÇARIM.",
["Tamam, girdim. Şimdi şunu hackleyip laboratuvar kapısının güvenlik bariyerini açalım."] = "TAMAM, GİRDİM. ŞİMDİ ŞUNU HACKLEYİP LABORATUVAR KAPISININ GÜVENLİK BARİYERİNİ AÇALIM.",
["Tamam, girdiniz! Güvenlik yetkisi talebi yolladım. Onaylamanız gerekiyor."] = "TAMAM, GİRDİNİZ! GÜVENLİK YETKİSİ TALEBİ YOLLADIM. ONAYLAMANIZ GEREKİYOR.",
["Tamam, girdiniz. Lanet FBI'ın siktiğimin müdürünün bilgisayarına erişiminiz var! İsteği onaylayın."] = "TAMAM, GİRDİNİZ. LANET FBI'IN SİKTİĞİMİN MÜDÜRÜNÜN BİLGİSAYARINA ERİŞİMİNİZ VAR! İSTEĞİ ONAYLAYIN.",
["Tamam, giriyoruz."] = "TAMAM, GİRİYORUZ.",
["Tamam, giriş kapısı orada. Şu bir RFID okuyucu. Güzel bir güvenlik parçası. Bir bakın."] = "TAMAM, GİRİŞ KAPISI ORADA. ŞU BİR RFID OKUYUCU. GÜZEL BİR GÜVENLİK PARÇASI. BİR BAKIN.",
["Tamam, giriş noktası. İşaretimle eşzamanlayın... Şimdi."] = "TAMAM, GİRİŞ NOKTASI. İŞARETİMLE EŞZAMANLAYIN... ŞİMDİ.",
["Tamam, gitme vakti!"] = "TAMAM, GİTME VAKTİ!",
["Tamam, gitme vakti. O kapının kilidini maymuncukla açmayın, kolunu vurup koparın."] = "TAMAM, GİTME VAKTİ. O KAPININ KİLİDİNİ MAYMUNCUKLA AÇMAYIN, KOLUNU VURUP KOPARIN.",
["Tamam, gitme vakti. Yeniden asfalta çıkın."] = "TAMAM, GİTME VAKTİ. YENİDEN ASFALTA ÇIKIN.",
["Tamam, gitme vaktimiz geldi. Hadi!"] = "TAMAM, GİTME VAKTİMİZ GELDİ. HADİ!",
["Tamam, gitmeye hazırız. Güvenli eve geçişinizi ayarlarım. Cephanelikleri gitti. Askerlerinin dişleri söküldü."] = "TAMAM, GİTMEYE HAZIRIZ. GÜVENLİ EVE GEÇİŞİNİZİ AYARLARIM. CEPHANELİKLERİ GİTTİ. ASKERLERİNİN DİŞLERİ SÖKÜLDÜ.",
["Tamam, gitmeye hazırız. Sizi güvenli eve kadar sağ salim götüreceğim. Vlad'ı memnun edecek silahlar bizde. Eminim çok hoşuna gidecek. FBI ise... başka mesele."] = "TAMAM, GİTMEYE HAZIRIZ. SİZİ GÜVENLİ EVE KADAR SAĞ SALİM GÖTÜRECEĞİM. VLAD'I MEMNUN EDECEK SİLAHLAR BİZDE. EMİNİM ÇOK HOŞUNA GİDECEK. FBI İSE... BAŞKA MESELE.",
["Tamam, gitti."] = "TAMAM, GİTTİ.",
["Tamam, gittiler. "] = "TAMAM, GİTTİLER. ",
["Tamam, gönderdiğim termiti o kasa dairesinin menteşelerinde kullanmalısınız, tamam mı?"] = "TAMAM, GÖNDERDİĞİM TERMİTİ O KASA DAİRESİNİN MENTEŞELERİNDE KULLANMALISINIZ, TAMAM MI?",
["Tamam, görünüşe göre panik odasının kapısı bir şifre ve iki Anahtar Kartı'yla açılıyor. Bunları bulun."] = "TAMAM, GÖRÜNÜŞE GÖRE PANİK ODASININ KAPISI BİR ŞİFRE VE İKİ ANAHTAR KARTI'YLA AÇILIYOR. BUNLARI BULUN.",
["Tamam, görünüşe göre... 11... 12 prototip var. Evde hangisinin çalıştığını gösterecek bir şey bulabilir misiniz, bakın. Sonra alıp bana getirin."] = "TAMAM, GÖRÜNÜŞE GÖRE... 11... 12 PROTOTİP VAR. EVDE HANGİSİNİN ÇALIŞTIĞINI GÖSTERECEK BİR ŞEY BULABİLİR MİSİNİZ, BAKIN. SONRA ALIP BANA GETİRİN.",
["Tamam, görünüşe göre... 11... 12 prototip var. Hangisinin çalıştığını gösterecek bir ipucu bulabilir misiniz, bakın. Sonra alıp bana getirin."] = "TAMAM, GÖRÜNÜŞE GÖRE... 11... 12 PROTOTİP VAR. HANGİSİNİN ÇALIŞTIĞINI GÖSTERECEK BİR İPUCU BULABİLİR MİSİNİZ, BAKIN. SONRA ALIP BANA GETİRİN.",
["Tamam, görüyorum! Yakında oradayız."] = "TAMAM, GÖRÜYORUM! YAKINDA ORADAYIZ.",
["Tamam, gösterinin programını aldım. Bunu yapabiliriz."] = "TAMAM, GÖSTERİNİN PROGRAMINI ALDIM. BUNU YAPABİLİRİZ.",
["Tamam, gürültülü gidiyoruz! Panik odası sağlam. Açmak için termal mızrak gerekecek. Yolda."] = "TAMAM, GÜRÜLTÜLÜ GİDİYORUZ! PANİK ODASI SAĞLAM. AÇMAK İÇİN TERMAL MIZRAK GEREKECEK. YOLDA.",
["Tamam, gürültülü yapıyoruz! Panik odası kilitlendi, size termal mızrak gönderiyorum. Bekleyin."] = "TAMAM, GÜRÜLTÜLÜ YAPIYORUZ! PANİK ODASI KİLİTLENDİ, SİZE TERMAL MIZRAK GÖNDERİYORUM. BEKLEYİN.",
["Tamam, güvenlik kapısının açılması gerek."] = "TAMAM, GÜVENLİK KAPISININ AÇILMASI GEREK.",
["Tamam, güvenlik odasının dışındayım ama Anahtar Kartı lazım."] = "TAMAM, GÜVENLİK ODASININ DIŞINDAYIM AMA ANAHTAR KARTI LAZIM.",
["Tamam, güvenlikçiyi hallettim."] = "TAMAM, GÜVENLİKÇİYİ HALLETTİM.",
["Tamam, güvenliği kapatmayı deneyelim. Sisteme güç veren devre kutularını bulmalısınız. Onlara bağlanın. Alarmı tetiklemeden sistemlerini kırıp gücü kesebilirim."] = "TAMAM, GÜVENLİĞİ KAPATMAYI DENEYELİM. SİSTEME GÜÇ VEREN DEVRE KUTULARINI BULMALISINIZ. ONLARA BAĞLANIN. ALARMI TETİKLEMEDEN SİSTEMLERİNİ KIRIP GÜCÜ KESEBİLİRİM.",
["Tamam, güzel bir kokteyle benziyor. Şimdi o şeyi kapıya sürün, işini yapsın."] = "TAMAM, GÜZEL BİR KOKTEYLE BENZİYOR. ŞİMDİ O ŞEYİ KAPIYA SÜRÜN, İŞİNİ YAPSIN.",
["Tamam, güzel!"] = "TAMAM, GÜZEL!",
["Tamam, güzel! Şimdi lütfen patlayıcıları orada gördüğünüz dört kilide yerleştirin."] = "TAMAM, GÜZEL! ŞİMDİ LÜTFEN PATLAYICILARI ORADA GÖRDÜĞÜNÜZ DÖRT KİLİDE YERLEŞTİRİN.",
["Tamam, güzel! Şimdi sizi alacak tekneye işaret vermelisiniz. Depodaki projektörler için bir şalter arayın."] = "TAMAM, GÜZEL! ŞİMDİ SİZİ ALACAK TEKNEYE İŞARET VERMELİSİNİZ. DEPODAKİ PROJEKTÖRLER İÇİN BİR ŞALTER ARAYIN.",
["Tamam, güzel, güzel. Getirmeye devam edin."] = "TAMAM, GÜZEL, GÜZEL. GETİRMEYE DEVAM EDİN.",
["Tamam, güzel, işe yarayabilir."] = "TAMAM, GÜZEL, İŞE YARAYABİLİR.",
["Tamam, güzel. Arka ofisteki kasa dairesini kontrol etme vakti millet."] = "TAMAM, GÜZEL. ARKA OFİSTEKİ KASA DAİRESİNİ KONTROL ETME VAKTİ MİLLET.",
["Tamam, güzel. Bir süre yeterli olur. Yeniden çalıştırmayı deneyin."] = "TAMAM, GÜZEL. BİR SÜRE YETERLİ OLUR. YENİDEN ÇALIŞTIRMAYI DENEYİN.",
["Tamam, güzel. Bu sefer çalışır tutun."] = "TAMAM, GÜZEL. BU SEFER ÇALIŞIR TUTUN.",
["Tamam, güzel. Elektriği açtınız. Tarama işlemine dönün."] = "TAMAM, GÜZEL. ELEKTRİĞİ AÇTINIZ. TARAMA İŞLEMİNE DÖNÜN.",
["Tamam, güzel. Garaja gidip asansörü çağırın. Yukarı çıkabilmeniz için boşluğun açık olması gerek."] = "TAMAM, GÜZEL. GARAJA GİDİP ASANSÖRÜ ÇAĞIRIN. YUKARI ÇIKABİLMENİZ İÇİN BOŞLUĞUN AÇIK OLMASI GEREK.",
["Tamam, güzel. O binanın öbür tarafında sizi bekleyen bir minibüs var. İçinden geçin, aracı yükleyin, bugünlük işimiz bitsin."] = "TAMAM, GÜZEL. O BİNANIN ÖBÜR TARAFINDA SİZİ BEKLEYEN BİR MİNİBÜS VAR. İÇİNDEN GEÇİN, ARACI YÜKLEYİN, BUGÜNLÜK İŞİMİZ BİTSİN.",
["Tamam, güzel. O sunucu odasını bulalım."] = "TAMAM, GÜZEL. O SUNUCU ODASINI BULALIM.",
["Tamam, güzel. Şarj yeniden başladı."] = "TAMAM, GÜZEL. ŞARJ YENİDEN BAŞLADI.",
["Tamam, güzel. Şimdi biri aramaya gelmeden cesedi torbalayıp gözden kaldır."] = "TAMAM, GÜZEL. ŞİMDİ BİRİ ARAMAYA GELMEDEN CESEDİ TORBALAYIP GÖZDEN KALDIR.",
["Tamam, güzel. Şimdi devam edin."] = "TAMAM, GÜZEL. ŞİMDİ DEVAM EDİN.",
["Tamam, güzel. Şimdi diğer yönlendiriciyi halledin."] = "TAMAM, GÜZEL. ŞİMDİ DİĞER YÖNLENDİRİCİYİ HALLEDİN.",
["Tamam, güzel. Şimdi gidip keçiyi alın!"] = "TAMAM, GÜZEL. ŞİMDİ GİDİP KEÇİYİ ALIN!",
["Tamam, güzel. Şimdi rehineyi arkadaki odaya götürün."] = "TAMAM, GÜZEL. ŞİMDİ REHİNEYİ ARKADAKİ ODAYA GÖTÜRÜN.",
["Tamam, güzel. Şimdi... bir saniye... millet... Hava desteği göndermekten bahsediyorlar! Acele etmelisiniz...!"] = "TAMAM, GÜZEL. ŞİMDİ... BİR SANİYE... MİLLET... HAVA DESTEĞİ GÖNDERMEKTEN BAHSEDİYORLAR! ACELE ETMELİSİNİZ...!",
["Tamam, güzel. Şu sunucu odasını bulalım."] = "TAMAM, GÜZEL. ŞU SUNUCU ODASINI BULALIM.",
["Tamam, hadi çalıştırın, sonra kapıya bindirin!"] = "TAMAM, HADİ ÇALIŞTIRIN, SONRA KAPIYA BİNDİRİN!",
["Tamam, hainin kimliği gizli tutuluyor. Ama tamamen boşa gitmedi, DNA örneğini aldık! İyi iş. Şimdi Hoxton'a dönün."] = "TAMAM, HAİNİN KİMLİĞİ GİZLİ TUTULUYOR. AMA TAMAMEN BOŞA GİTMEDİ, DNA ÖRNEĞİNİ ALDIK! İYİ İŞ. ŞİMDİ HOXTON'A DÖNÜN.",
["Tamam, hallettim! Deponun kilidi artık açık. Gidip araba anahtarlarını alın."] = "TAMAM, HALLETTİM! DEPONUN KİLİDİ ARTIK AÇIK. GİDİP ARABA ANAHTARLARINI ALIN.",
["Tamam, hallettim. Dostumuzu takasla geri almak için rehineyi şimdi bırakın."] = "TAMAM, HALLETTİM. DOSTUMUZU TAKASLA GERİ ALMAK İÇİN REHİNEYİ ŞİMDİ BIRAKIN.",
["Tamam, hamlemizin vakti geldi. Maskeleri takın, başlayalım!"] = "TAMAM, HAMLEMİZİN VAKTİ GELDİ. MASKELERİ TAKIN, BAŞLAYALIM!",
["Tamam, hangarı tamamen boşalttınız. Çıkma vakti."] = "TAMAM, HANGARI TAMAMEN BOŞALTTINIZ. ÇIKMA VAKTİ.",
["Tamam, hangi maskenin hangi muhafıza ait olduğunu biliyoruz ama bu hâlâ kartın şu anda kimde olduğunu söylemiyor. "] = "TAMAM, HANGİ MASKENİN HANGİ MUHAFIZA AİT OLDUĞUNU BİLİYORUZ AMA BU HÂLÂ KARTIN ŞU ANDA KİMDE OLDUĞUNU SÖYLEMİYOR. ",
["Tamam, hangi nakil aracında? Hepsini testereyle açıp öğrenin!"] = "TAMAM, HANGİ NAKİL ARACINDA? HEPSİNİ TESTEREYLE AÇIP ÖĞRENİN!",
["Tamam, hangi şarabı aradığımızı biliyorsunuz! Bulun!"] = "TAMAM, HANGİ ŞARABI ARADIĞIMIZI BİLİYORSUNUZ! BULUN!",
["Tamam, hareket ediyoruz. Kurtulana kadar kamyonu tehlikeden uzak tutun."] = "TAMAM, HAREKET EDİYORUZ. KURTULANA KADAR KAMYONU TEHLİKEDEN UZAK TUTUN.",
["Tamam, harekete hazırız. Unutmayın, bunlar Murky Water paralı askerleri; siper kullanın ve kısa, kontrollü seriler hâlinde ateş edin."] = "TAMAM, HAREKETE HAZIRIZ. UNUTMAYIN, BUNLAR MURKY WATER PARALI ASKERLERİ; SİPER KULLANIN VE KISA, KONTROLLÜ SERİLER HÂLİNDE ATEŞ EDİN.",
["Tamam, harika! O para çuvalını minibüse götürün."] = "TAMAM, HARİKA! O PARA ÇUVALINI MİNİBÜSE GÖTÜRÜN.",
["Tamam, harika! Şimdi ganimeti asansörlerin yanındaki havalandırmaya koyun!"] = "TAMAM, HARİKA! ŞİMDİ GANİMETİ ASANSÖRLERİN YANINDAKİ HAVALANDIRMAYA KOYUN!",
["Tamam, harika, sıradaki işe geçelim."] = "TAMAM, HARİKA, SIRADAKİ İŞE GEÇELİM.",
["Tamam, harika. Geliyorum."] = "TAMAM, HARİKA. GELİYORUM.",
["Tamam, harika. Hem rakamı hem rengi unutmayın."] = "TAMAM, HARİKA. HEM RAKAMI HEM RENGİ UNUTMAYIN.",
["Tamam, harika. O testere işe yarayacak."] = "TAMAM, HARİKA. O TESTERE İŞE YARAYACAK.",
["Tamam, harika. Sıcaklık artıyor. Bekleyin ama daha fazla fan sıkıştırmak işi hızlandırır."] = "TAMAM, HARİKA. SICAKLIK ARTIYOR. BEKLEYİN AMA DAHA FAZLA FAN SIKIŞTIRMAK İŞİ HIZLANDIRIR.",
["Tamam, harika. Şimdi o şeyi Kasa Dairesi'nin kapısına götürün."] = "TAMAM, HARİKA. ŞİMDİ O ŞEYİ KASA DAİRESİ'NİN KAPISINA GÖTÜRÜN.",
["Tamam, harika. Şimdi şu sunucu... O dizüstü bilgisayara dönüp beni bağlarsanız sunucunun bulunduğu odayı açabilirim herhâlde."] = "TAMAM, HARİKA. ŞİMDİ ŞU SUNUCU... O DİZÜSTÜ BİLGİSAYARA DÖNÜP BENİ BAĞLARSANIZ SUNUCUNUN BULUNDUĞU ODAYI AÇABİLİRİM HERHÂLDE.",
["Tamam, havaalanı hemen yokuş aşağıda. Çiti kesip geçin. Kasaların yüklü olduğu kamyonun bulunduğu hangarı bulun. FBI tabii ki olay yerinde. Vlad'ın silahlarını alıp buraya getirin."] = "TAMAM, HAVAALANI HEMEN YOKUŞ AŞAĞIDA. ÇİTİ KESİP GEÇİN. KASALARIN YÜKLÜ OLDUĞU KAMYONUN BULUNDUĞU HANGARI BULUN. FBI TABİİ Kİ OLAY YERİNDE. VLAD'IN SİLAHLARINI ALIP BURAYA GETİRİN.",
["Tamam, havaalanı hemen yokuş aşağıda. Çiti kesip geçin. Kasaların yüklü olduğu kamyonun bulunduğu hangarı bulun. Mendoza'lar muhtemelen oradadır. Gidip o silahları alın ya da onların alamamasını sağlayın. "] = "TAMAM, HAVAALANI HEMEN YOKUŞ AŞAĞIDA. ÇİTİ KESİP GEÇİN. KASALARIN YÜKLÜ OLDUĞU KAMYONUN BULUNDUĞU HANGARI BULUN. MENDOZA'LAR MUHTEMELEN ORADADIR. GİDİP O SİLAHLARI ALIN YA DA ONLARIN ALAMAMASINI SAĞLAYIN. ",
["Tamam, havaalanı tepenin hemen aşağısında. Çiti kesip kutuların bulunduğu kamyonun olduğu hangarı bulun. Mendozas muhtemelen oradadır. Silahları minibüse getirin; yapamıyorsanız ellerinde kalmasın. Çatışmadan pes etmeyecekler. Ortalık karışırsa silahları yok edin."] = "TAMAM, HAVAALANI TEPENİN HEMEN AŞAĞISINDA. ÇİTİ KESİP KUTULARIN BULUNDUĞU KAMYONUN OLDUĞU HANGARI BULUN. MENDOZAS MUHTEMELEN ORADADIR. SİLAHLARI MİNİBÜSE GETİRİN; YAPAMIYORSANIZ ELLERİNDE KALMASIN. ÇATIŞMADAN PES ETMEYECEKLER. ORTALIK KARIŞIRSA SİLAHLARI YOK EDİN.",
["Tamam, havai fişekleri gördüm. Size dönüyorum."] = "TAMAM, HAVAİ FİŞEKLERİ GÖRDÜM. SİZE DÖNÜYORUM.",
["Tamam, hazır olun! Gereken sayıda çantayı getirin, güvenli evde buluşalım."] = "TAMAM, HAZIR OLUN! GEREKEN SAYIDA ÇANTAYI GETİRİN, GÜVENLİ EVDE BULUŞALIM.",
["Tamam, hazır olun, geliyorum!"] = "TAMAM, HAZIR OLUN, GELİYORUM!",
["Tamam, hazırsınız. Sistem kırma işlemini başlatın."] = "TAMAM, HAZIRSINIZ. SİSTEM KIRMA İŞLEMİNİ BAŞLATIN.",
["Tamam, hazırım, herkesi helikoptere alın!"] = "TAMAM, HAZIRIM, HERKESİ HELİKOPTERE ALIN!",
["Tamam, hedefin yerini buldum. Gidip alın onu!"] = "TAMAM, HEDEFİN YERİNİ BULDUM. GİDİP ALIN ONU!",
["Tamam, helikopter burada. Pilotu getirin!"] = "TAMAM, HELİKOPTER BURADA. PİLOTU GETİRİN!",
["Tamam, helikopter döndü. Pompayı tekrar çalıştırın!"] = "TAMAM, HELİKOPTER DÖNDÜ. POMPAYI TEKRAR ÇALIŞTIRIN!",
["Tamam, helikopter geldi!"] = "TAMAM, HELİKOPTER GELDİ!",
["Tamam, helikopter geldi. Bulduğunuz ganimetleri güvene alın. İstediğiniz zaman kaçabilirsiniz ama dışarıda her zaman daha fazla ganimet olduğuna eminim. Karar sizin."] = "TAMAM, HELİKOPTER GELDİ. BULDUĞUNUZ GANİMETLERİ GÜVENE ALIN. İSTEDİĞİNİZ ZAMAN KAÇABİLİRSİNİZ AMA DIŞARIDA HER ZAMAN DAHA FAZLA GANİMET OLDUĞUNA EMİNİM. KARAR SİZİN.",
["Tamam, helikopter geldi. Motoru yükleyin."] = "TAMAM, HELİKOPTER GELDİ. MOTORU YÜKLEYİN.",
["Tamam, helikopter geliyor, prototipi hazırlayın."] = "TAMAM, HELİKOPTER GELİYOR, PROTOTİPİ HAZIRLAYIN.",
["Tamam, helikopter için bir fikrim var. O lastiklere biraz benzin döküp yakın. Duman perdesi oluşturur."] = "TAMAM, HELİKOPTER İÇİN BİR FİKRİM VAR. O LASTİKLERE BİRAZ BENZİN DÖKÜP YAKIN. DUMAN PERDESİ OLUŞTURUR.",
["Tamam, helikopter kalkıyor. Umarım biraz ganimet yüklediniz. Yine gelecek. Vlad'ın kokaininden daha fazla bulmaya çalışın."] = "TAMAM, HELİKOPTER KALKIYOR. UMARIM BİRAZ GANİMET YÜKLEDİNİZ. YİNE GELECEK. VLAD'IN KOKAİNİNDEN DAHA FAZLA BULMAYA ÇALIŞIN.",
["Tamam, helikopter neredeyse geldi. Bekleyin."] = "TAMAM, HELİKOPTER NEREDEYSE GELDİ. BEKLEYİN.",
["Tamam, helikopter o füzyon motorunu almaya geliyor."] = "TAMAM, HELİKOPTER O FÜZYON MOTORUNU ALMAYA GELİYOR.",
["Tamam, helikopter pistine gidip aracınıza işaret verin."] = "TAMAM, HELİKOPTER PİSTİNE GİDİP ARACINIZA İŞARET VERİN.",
["Tamam, helikopter yolda."] = "TAMAM, HELİKOPTER YOLDA.",
["Tamam, helikopter yolda. Bir dakikaya orada."] = "TAMAM, HELİKOPTER YOLDA. BİR DAKİKAYA ORADA.",
["Tamam, helikopter şimdi konvoyun üstüne geliyor, köprüdeyiz. İyi iş Alex... Sonunda... Vurun ve bitirin. Ne olursa olsun para bizim. Halledin."] = "TAMAM, HELİKOPTER ŞİMDİ KONVOYUN ÜSTÜNE GELİYOR, KÖPRÜDEYİZ. İYİ İŞ ALEX... SONUNDA... VURUN VE BİTİRİN. NE OLURSA OLSUN PARA BİZİM. HALLEDİN.",
["Tamam, henüz nereye bakmadınız?"] = "TAMAM, HENÜZ NEREYE BAKMADINIZ?",
["Tamam, hepsi bu. Hazır olur olmaz çıkın oradan."] = "TAMAM, HEPSİ BU. HAZIR OLUR OLMAZ ÇIKIN ORADAN.",
["Tamam, her neyse... Kazanmanın başka bir yolu hâlâ var: Commissar'ı bulup öldürün! Artık motive olduğunuzu sanıyorum!"] = "TAMAM, HER NEYSE... KAZANMANIN BAŞKA BİR YOLU HÂLÂ VAR: COMMİSSAR'I BULUP ÖLDÜRÜN! ARTIK MOTİVE OLDUĞUNUZU SANIYORUM!",
["Tamam, her şeyi silip süpürdünüz! Buradan gitme vakti."] = "TAMAM, HER ŞEYİ SİLİP SÜPÜRDÜNÜZ! BURADAN GİTME VAKTİ.",
["Tamam, herkes eğilsin. Patlatıyorum: dört, üç, iki, siper alın, ateş!"] = "TAMAM, HERKES EĞİLSİN. PATLATIYORUM: DÖRT, ÜÇ, İKİ, SİPER ALIN, ATEŞ!",
["Tamam, herkes çöksün. Patlatıyorum: dört, üç, iki, siper..."] = "TAMAM, HERKES ÇÖKSÜN. PATLATIYORUM: DÖRT, ÜÇ, İKİ, SİPER...",
["Tamam, heykelle birlikte minibüse gidin!"] = "TAMAM, HEYKELLE BİRLİKTE MİNİBÜSE GİDİN!",
["Tamam, hortum iyi görünüyor. Şimdi pompayı çalıştırın."] = "TAMAM, HORTUM İYİ GÖRÜNÜYOR. ŞİMDİ POMPAYI ÇALIŞTIRIN.",
["Tamam, hortum sağlam görünüyor. Şimdi pompayı yeniden çalıştıralım!"] = "TAMAM, HORTUM SAĞLAM GÖRÜNÜYOR. ŞİMDİ POMPAYI YENİDEN ÇALIŞTIRALIM!",
["Tamam, hortum serildi."] = "TAMAM, HORTUM SERİLDİ.",
["Tamam, ihtiyacımız olanın hepsi bu."] = "TAMAM, İHTİYACIMIZ OLANIN HEPSİ BU.",
["Tamam, iki anahtar kartı da bizde. Şu kasa dairesini açalım."] = "TAMAM, İKİ ANAHTAR KARTI DA BİZDE. ŞU KASA DAİRESİNİ AÇALIM.",
["Tamam, iki delik de açıldı."] = "TAMAM, İKİ DELİK DE AÇILDI.",
["Tamam, iki tane daha."] = "TAMAM, İKİ TANE DAHA.",
["Tamam, iki şey lazım: Yakıt deposu ve egzoz boruları. Atölyeye girip tavan liftini bulun. Orada tutuyorlar. İndirip ikisini de getirin."] = "TAMAM, İKİ ŞEY LAZIM: YAKIT DEPOSU VE EGZOZ BORULARI. ATÖLYEYE GİRİP TAVAN LİFTİNİ BULUN. ORADA TUTUYORLAR. İNDİRİP İKİSİNİ DE GETİRİN.",
["Tamam, iki!"] = "TAMAM, İKİ!",
["Tamam, ikinci dalga geliyor!"] = "TAMAM, İKİNCİ DALGA GELİYOR!",
["Tamam, ileride bir muhafız görüyorum. Açıkçası yanından gizlice geçecek pek alan yok."] = "TAMAM, İLERİDE BİR MUHAFIZ GÖRÜYORUM. AÇIKÇASI YANINDAN GİZLİCE GEÇECEK PEK ALAN YOK.",
["Tamam, ilerleyelim."] = "TAMAM, İLERLEYELİM.",
["Tamam, ilk adım güvenlik şefini bulmak. Evin erişim kodlarının olduğu USB bellek onda. Hep yeşil ceket giyer."] = "TAMAM, İLK ADIM GÜVENLİK ŞEFİNİ BULMAK. EVİN ERİŞİM KODLARININ OLDUĞU USB BELLEK ONDA. HEP YEŞİL CEKET GİYER.",
["Tamam, ilk dalga geliyor!"] = "TAMAM, İLK DALGA GELİYOR!",
["Tamam, ilk kısım bu, değil mi? Sıradaki bileşiği ekleme vakti."] = "TAMAM, İLK KISIM BU, DEĞİL Mİ? SIRADAKİ BİLEŞİĞİ EKLEME VAKTİ.",
["Tamam, ilk makine hacklendi. Devam edin."] = "TAMAM, İLK MAKİNE HACKLENDİ. DEVAM EDİN.",
["Tamam, ilk matkap deldi geçti."] = "TAMAM, İLK MATKAP DELDİ GEÇTİ.",
["Tamam, ilk nakil aracı açıldı. Kontrol edin!"] = "TAMAM, İLK NAKİL ARACI AÇILDI. KONTROL EDİN!",
["Tamam, ilk veri tabanı indirildi. Harika görünüyor ama eksik. Şimdi sıvışabilirsiniz ya da kalıp bütün veri tabanını indirebilirsiniz. Size kalmış."] = "TAMAM, İLK VERİ TABANI İNDİRİLDİ. HARİKA GÖRÜNÜYOR AMA EKSİK. ŞİMDİ SIVIŞABİLİRSİNİZ YA DA KALIP BÜTÜN VERİ TABANINI İNDİREBİLİRSİNİZ. SİZE KALMIŞ.",
["Tamam, inceliyoruz... Şimdilik her şey yolunda... Şimdi testleri yapıyor..."] = "TAMAM, İNCELİYORUZ... ŞİMDİLİK HER ŞEY YOLUNDA... ŞİMDİ TESTLERİ YAPIYOR...",
["Tamam, inceliyoruz... Şimdilik iyi... Şimdi çıkışları test ediyor..."] = "TAMAM, İNCELİYORUZ... ŞİMDİLİK İYİ... ŞİMDİ ÇIKIŞLARI TEST EDİYOR...",
["Tamam, indirin onu. Alex, vinci oraya getir."] = "TAMAM, İNDİRİN ONU. ALEX, VİNCİ ORAYA GETİR.",
["Tamam, isterseniz gitmeye yetecek kadar aldık. Ama daha fazlasını istiyorsak gözetim odasına erişim sağlayın da ağlarında ne var göreyim."] = "TAMAM, İSTERSENİZ GİTMEYE YETECEK KADAR ALDIK. AMA DAHA FAZLASINI İSTİYORSAK GÖZETİM ODASINA ERİŞİM SAĞLAYIN DA AĞLARINDA NE VAR GÖREYİM.",
["Tamam, istihbarat sağlam. Bilim insanının saklandığı anlaşılan büyük villaya saldırıyı planlamamıza yardım edecek. Hazırlanıp oraya gidelim."] = "TAMAM, İSTİHBARAT SAĞLAM. BİLİM İNSANININ SAKLANDIĞI ANLAŞILAN BÜYÜK VİLLAYA SALDIRIYI PLANLAMAMIZA YARDIM EDECEK. HAZIRLANIP ORAYA GİDELİM.",
["Tamam, istihbaratı alıp yürüyün."] = "TAMAM, İSTİHBARATI ALIP YÜRÜYÜN.",
["Tamam, istihbaratım girişin tam yerini söylemiyor. Biraz kurcalamanız gerekecek."] = "TAMAM, İSTİHBARATIM GİRİŞİN TAM YERİNİ SÖYLEMİYOR. BİRAZ KURCALAMANIZ GEREKECEK.",
["Tamam, iyi buldunuz. Şimdi benzini lastiklerin her tarafına dökün."] = "TAMAM, İYİ BULDUNUZ. ŞİMDİ BENZİNİ LASTİKLERİN HER TARAFINA DÖKÜN.",
["Tamam, iyi değil, hiç iyi değil!"] = "TAMAM, İYİ DEĞİL, HİÇ İYİ DEĞİL!",
["Tamam, iyi dinleyin. Bir bağlantım sizi yakındaki metro istasyonundan çıkaracak."] = "TAMAM, İYİ DİNLEYİN. BİR BAĞLANTIM SİZİ YAKINDAKİ METRO İSTASYONUNDAN ÇIKARACAK.",
["Tamam, iyi dinleyin. Hector için pişireceksiniz. Minnettar kalacak, bana güvenin."] = "TAMAM, İYİ DİNLEYİN. HECTOR İÇİN PİŞİRECEKSİNİZ. MİNNETTAR KALACAK, BANA GÜVENİN.",
["Tamam, iyi dinleyin. Kaçış şöyle. İlerideki köprüyü geçince tünelde bir kamyon göreceksiniz. O Twitch. Arabayı doğrudan kamyonun içine park edin, bu dosyayı kapatalım."] = "TAMAM, İYİ DİNLEYİN. KAÇIŞ ŞÖYLE. İLERİDEKİ KÖPRÜYÜ GEÇİNCE TÜNELDE BİR KAMYON GÖRECEKSİNİZ. O TWITCH. ARABAYI DOĞRUDAN KAMYONUN İÇİNE PARK EDİN, BU DOSYAYI KAPATALIM.",
["Tamam, iyi iş! Şimdi konteynere gidin. Benzin bidonunu oraya bırakın."] = "TAMAM, İYİ İŞ! ŞİMDİ KONTEYNERE GİDİN. BENZİN BİDONUNU ORAYA BIRAKIN.",
["Tamam, iyi iş. Yeniden bağlandık."] = "TAMAM, İYİ İŞ. YENİDEN BAĞLANDIK.",
["Tamam, iyi olacak... Dayanın."] = "TAMAM, İYİ OLACAK... DAYANIN.",
["Tamam, içeri gelin."] = "TAMAM, İÇERİ GELİN.",
["Tamam, içeri girdi!"] = "TAMAM, İÇERİ GİRDİ!",
["Tamam, içeri girdim ama asansör çalışmıyor galiba. Dinleyin, benden aldıkları önemli bir şeyi geri almam gerek. Metal bir evrak çantasının içinde. Onu bana getirir misiniz?"] = "TAMAM, İÇERİ GİRDİM AMA ASANSÖR ÇALIŞMIYOR GALİBA. DİNLEYİN, BENDEN ALDIKLARI ÖNEMLİ BİR ŞEYİ GERİ ALMAM GEREK. METAL BİR EVRAK ÇANTASININ İÇİNDE. ONU BANA GETİRİR MİSİNİZ?",
["Tamam, içeri girdiğinize göre makinelerin peşine düşelim. Muhtemelen kapalı sandıklardalar, sandıklar için gözünüzü açık tutun."] = "TAMAM, İÇERİ GİRDİĞİNİZE GÖRE MAKİNELERİN PEŞİNE DÜŞELİM. MUHTEMELEN KAPALI SANDIKLARDALAR, SANDIKLAR İÇİN GÖZÜNÜZÜ AÇIK TUTUN.",
["Tamam, içeri girin. Sessiz olun. "] = "TAMAM, İÇERİ GİRİN. SESSİZ OLUN. ",
["Tamam, içeri girip adamımızı çıkarın."] = "TAMAM, İÇERİ GİRİP ADAMIMIZI ÇIKARIN.",
["Tamam, içeri girip hedefi bulun."] = "TAMAM, İÇERİ GİRİP HEDEFİ BULUN.",
["Tamam, içeri girmenin yolunu bulun, başınızı eğin, muhafızlara ve kameralara dikkat edin."] = "TAMAM, İÇERİ GİRMENİN YOLUNU BULUN, BAŞINIZI EĞİN, MUHAFIZLARA VE KAMERALARA DİKKAT EDİN.",
["Tamam, içerideki adamımız barmenlik yapıyor. Gidip konuşun."] = "TAMAM, İÇERİDEKİ ADAMIMIZ BARMENLİK YAPIYOR. GİDİP KONUŞUN.",
["Tamam, içeridesiniz! İstihbaratıma göre delilleri ikinci katta tutuyorlar. Gidip bulun!"] = "TAMAM, İÇERİDESİNİZ! İSTİHBARATIMA GÖRE DELİLLERİ İKİNCİ KATTA TUTUYORLAR. GİDİP BULUN!",
["Tamam, içeridesiniz, güzel. Şimdi en az dört tablo lazım. İyi olanların üzerinde kırmızı etiket var; sanatseverimiz onları satın almak istiyor."] = "TAMAM, İÇERİDESİNİZ, GÜZEL. ŞİMDİ EN AZ DÖRT TABLO LAZIM. İYİ OLANLARIN ÜZERİNDE KIRMIZI ETİKET VAR; SANATSEVERİMİZ ONLARI SATIN ALMAK İSTİYOR.",
["Tamam, içeridesiniz. Esteban'ın ofisini bulun, sıkı güvenliğe de hazır olun."] = "TAMAM, İÇERİDESİNİZ. ESTEBAN'IN OFİSİNİ BULUN, SIKI GÜVENLİĞE DE HAZIR OLUN.",
["Tamam, içeridesiniz. Kırmızı etiketli tabloları bulun, en az dört istiyoruz."] = "TAMAM, İÇERİDESİNİZ. KIRMIZI ETİKETLİ TABLOLARI BULUN, EN AZ DÖRT İSTİYORUZ.",
["Tamam, içerideyim. Bu sunucular üzerinde çalışacağım. Beni koruyun!"] = "TAMAM, İÇERİDEYİM. BU SUNUCULAR ÜZERİNDE ÇALIŞACAĞIM. BENİ KORUYUN!",
["Tamam, içerideyiz. Kasa dairesine girin, ganimeti taşımaya başlayın!"] = "TAMAM, İÇERİDEYİZ. KASA DAİRESİNE GİRİN, GANİMETİ TAŞIMAYA BAŞLAYIN!",
["Tamam, içimiz rahat olabilir. Bugün oy verilmeyecek. Üstüne para da aldık. Güzel zafer, güzel günler."] = "TAMAM, İÇİMİZ RAHAT OLABİLİR. BUGÜN OY VERİLMEYECEK. ÜSTÜNE PARA DA ALDIK. GÜZEL ZAFER, GÜZEL GÜNLER.",
["Tamam, işaret fişeği orada. Alçalmaya başlıyorum."] = "TAMAM, İŞARET FİŞEĞİ ORADA. ALÇALMAYA BAŞLIYORUM.",
["Tamam, işaret fişeği yandı. Güzel iş millet, şimdi Bile'ı bekleyin."] = "TAMAM, İŞARET FİŞEĞİ YANDI. GÜZEL İŞ MİLLET, ŞİMDİ BILE'I BEKLEYİN.",
["Tamam, işaretlediğim terminali görüyor musunuz? Oraya gidip sistemi hackleyin de şu manyetik kilidi devreden çıkaralım."] = "TAMAM, İŞARETLEDİĞİM TERMİNALİ GÖRÜYOR MUSUNUZ? ORAYA GİDİP SİSTEMİ HACKLEYİN DE ŞU MANYETİK KİLİDİ DEVREDEN ÇIKARALIM.",
["Tamam, işaretli dolap orada. Kilidi açmaya başlayın."] = "TAMAM, İŞARETLİ DOLAP ORADA. KİLİDİ AÇMAYA BAŞLAYIN.",
["Tamam, işe odaklanın. Evin her yanına dağılmış deliller var. Onları halletmeliyiz. FBI'ın izimizi kaybettiğinden emin olmalıyız!"] = "TAMAM, İŞE ODAKLANIN. EVİN HER YANINA DAĞILMIŞ DELİLLER VAR. ONLARI HALLETMELİYİZ. FBI'IN İZİMİZİ KAYBETTİĞİNDEN EMİN OLMALIYIZ!",
["Tamam, işe yaramadı. Belki şu avize... Kabloyu termitle eritin!"] = "TAMAM, İŞE YARAMADI. BELKİ ŞU AVİZE... KABLOYU TERMİTLE ERİTİN!",
["Tamam, işlem başladı, pişiyor. Hector aracılığıyla bir uzmanla bağlantım var. Size adım adım yol göstereceğim."] = "TAMAM, İŞLEM BAŞLADI, PİŞİYOR. HECTOR ARACILIĞIYLA BİR UZMANLA BAĞLANTIM VAR. SİZE ADIM ADIM YOL GÖSTERECEĞİM.",
["Tamam, işler ciddileşti. Sunucuya koşun millet. Söküp alın."] = "TAMAM, İŞLER CİDDİLEŞTİ. SUNUCUYA KOŞUN MİLLET. SÖKÜP ALIN.",
["Tamam, işleri biraz daha ilginç kılmak için biz yüklerken bu görüntüyü bütün büyük medya kuruluşlarına canlı veriyorum. Bol bol haber olacağız."] = "TAMAM, İŞLERİ BİRAZ DAHA İLGİNÇ KILMAK İÇİN BİZ YÜKLERKEN BU GÖRÜNTÜYÜ BÜTÜN BÜYÜK MEDYA KURULUŞLARINA CANLI VERİYORUM. BOL BOL HABER OLACAĞIZ.",
["Tamam, işte bu kadar. Gitme vakti."] = "TAMAM, İŞTE BU KADAR. GİTME VAKTİ.",
["Tamam, işte bu! BFD'nin üstüne atın."] = "TAMAM, İŞTE BU! BFD'NİN ÜSTÜNE ATIN.",
["Tamam, işte bu! Sonunda yaptınız amına koyayım!"] = "TAMAM, İŞTE BU! SONUNDA YAPTINIZ AMINA KOYAYIM!",
["Tamam, işte bu! Şimdi geri çekilin, burası patlamak üzere!"] = "TAMAM, İŞTE BU! ŞİMDİ GERİ ÇEKİLİN, BURASI PATLAMAK ÜZERE!",
["Tamam, işte bu! Şimdi o şeyi açın."] = "TAMAM, İŞTE BU! ŞİMDİ O ŞEYİ AÇIN.",
["Tamam, işte bu! Şimdi şunu açın."] = "TAMAM, İŞTE BU! ŞİMDİ ŞUNU AÇIN.",
["Tamam, işte bu. Ganimeti içeri yükleyince yakıtını da doldurmalısınız."] = "TAMAM, İŞTE BU. GANİMETİ İÇERİ YÜKLEYİNCE YAKITINI DA DOLDURMALISINIZ.",
["Tamam, işte bu. Ganimeti yükledikten sonra yakıtını da doldurmalısınız."] = "TAMAM, İŞTE BU. GANİMETİ YÜKLEDİKTEN SONRA YAKITINI DA DOLDURMALISINIZ.",
["Tamam, işte bu. Kasa dairesine gidip anahtar kartı ve kodla açın."] = "TAMAM, İŞTE BU. KASA DAİRESİNE GİDİP ANAHTAR KARTI VE KODLA AÇIN.",
["Tamam, işte bu. Kaçış minibüsüne götürün... Vlad memnun olacak."] = "TAMAM, İŞTE BU. KAÇIŞ MİNİBÜSÜNE GÖTÜRÜN... VLAD MEMNUN OLACAK.",
["Tamam, işte bu. Çabucak girip Vlad'ın tacını alın. Daha fazlasını isterseniz karar sizin."] = "TAMAM, İŞTE BU. ÇABUCAK GİRİP VLAD'IN TACINI ALIN. DAHA FAZLASINI İSTERSENİZ KARAR SİZİN.",
["Tamam, işte burası palyaçolar. O parayı buraya getirin."] = "TAMAM, İŞTE BURASI PALYAÇOLAR. O PARAYI BURAYA GETİRİN.",
["Tamam, işte burası! Ben gidiyorum, içeri girdiğinde Bain sana ulaşacak."] = "TAMAM, İŞTE BURASI! BEN GİDİYORUM, İÇERİ GİRDİĞİNDE BAIN SANA ULAŞACAK.",
["Tamam, işte burası."] = "TAMAM, İŞTE BURASI.",
["Tamam, işte o, orada! Çıkarın onu, olur mu?"] = "TAMAM, İŞTE O, ORADA! ÇIKARIN ONU, OLUR MU?",
["Tamam, işte orada, ilerleyin!"] = "TAMAM, İŞTE ORADA, İLERLEYİN!",
["Tamam, işte orada. Kapıyı tekmeleyip açın!"] = "TAMAM, İŞTE ORADA. KAPIYI TEKMELEYİP AÇIN!",
["Tamam, kabin ekibi. İşaret verdiğimde basıyorsunuz, anlaşıldı mı?"] = "TAMAM, KABİN EKİBİ. İŞARET VERDİĞİMDE BASIYORSUNUZ, ANLAŞILDI MI?",
["Tamam, kafesi görüyorum. Geliyorum!"] = "TAMAM, KAFESİ GÖRÜYORUM. GELİYORUM!",
["Tamam, kalabalığa karışmak bizim tarzımız değil galiba. Helikopteri şimdi gönderiyorum!"] = "TAMAM, KALABALIĞA KARIŞMAK BİZİM TARZIMIZ DEĞİL GALİBA. HELİKOPTERİ ŞİMDİ GÖNDERİYORUM!",
["Tamam, kalıpları ben alırım; sen güvenlik kayıtlarını sil."] = "TAMAM, KALIPLARI BEN ALIRIM; SEN GÜVENLİK KAYITLARINI SİL.",
["Tamam, kameralar halledildi."] = "TAMAM, KAMERALAR HALLEDİLDİ.",
["Tamam, kameralar tablolara yerleştirildi. Hazırız. Senatörün adamları gergin ama bizimle anlaşmaya hazır. Hadi takas yapalım. Sanata karşılık para."] = "TAMAM, KAMERALAR TABLOLARA YERLEŞTİRİLDİ. HAZIRIZ. SENATÖRÜN ADAMLARI GERGİN AMA BİZİMLE ANLAŞMAYA HAZIR. HADİ TAKAS YAPALIM. SANATA KARŞILIK PARA.",
["Tamam, kameralar tablolara yerleştirildi. Hazırız. Senatörün adamları gergin ama bizimle anlaşmaya hazır. O hâlde alışverişi yapalım. Sanat karşılığında para. Buluşma yerini ayarladım. Terk edilmiş bir tren sahasında buluşacaksınız. İyi şanslar."] = "TAMAM, KAMERALAR TABLOLARA YERLEŞTİRİLDİ. HAZIRIZ. SENATÖRÜN ADAMLARI GERGİN AMA BİZİMLE ANLAŞMAYA HAZIR. O HÂLDE ALIŞVERİŞİ YAPALIM. SANAT KARŞILIĞINDA PARA. BULUŞMA YERİNİ AYARLADIM. TERK EDİLMİŞ BİR TREN SAHASINDA BULUŞACAKSINIZ. İYİ ŞANSLAR.",
["Tamam, kamerayı kurup kaydedin."] = "TAMAM, KAMERAYI KURUP KAYDEDİN.",
["Tamam, kamyon açıldı, mallarımızı çıkarın."] = "TAMAM, KAMYON AÇILDI, MALLARIMIZI ÇIKARIN.",
["Tamam, kamyon orada, çantalarımız da orada. Ganimeti kamyona yükleyin, çabuk!"] = "TAMAM, KAMYON ORADA, ÇANTALARIMIZ DA ORADA. GANİMETİ KAMYONA YÜKLEYİN, ÇABUK!",
["Tamam, kamyon orada. Kutudaki C4'ü alıp o kapıyı patlatın."] = "TAMAM, KAMYON ORADA. KUTUDAKİ C4'Ü ALIP O KAPIYI PATLATIN.",
["Tamam, kamyon yola çıkıyor ve GPS çalışıyor. Güzel iş. Tarihi kendi yolumuzla değiştirme vakti."] = "TAMAM, KAMYON YOLA ÇIKIYOR VE GPS ÇALIŞIYOR. GÜZEL İŞ. TARİHİ KENDİ YOLUMUZLA DEĞİŞTİRME VAKTİ.",
["Tamam, kamyonlar bu otoyolda bir yerde."] = "TAMAM, KAMYONLAR BU OTOYOLDA BİR YERDE.",
["Tamam, kaptanı duydunuz. Bilgisayarı bulun. GPS koordinatlarını girin. Şu gemiyi hareket ettirelim."] = "TAMAM, KAPTANI DUYDUNUZ. BİLGİSAYARI BULUN. GPS KOORDİNATLARINI GİRİN. ŞU GEMİYİ HAREKET ETTİRELİM.",
["Tamam, kapı açıldı, o metro girişine gidin."] = "TAMAM, KAPI AÇILDI, O METRO GİRİŞİNE GİDİN.",
["Tamam, kapı kilitli. Anahtar lazım olacak. Bence Chavez'i bulmak anahtarı bulmak demek. Binada Chavez'i arayın."] = "TAMAM, KAPI KİLİTLİ. ANAHTAR LAZIM OLACAK. BENCE CHAVEZ'İ BULMAK ANAHTARI BULMAK DEMEK. BİNADA CHAVEZ'İ ARAYIN.",
["Tamam, kapı orada, ilk kilit de orada. Şifre kırıcıları çalıştırın."] = "TAMAM, KAPI ORADA, İLK KİLİT DE ORADA. ŞİFRE KIRICILARI ÇALIŞTIRIN.",
