["Tamam, neredeyse bitti!"] = "TAMAM, NEREDEYSE BİTTİ!",
["Tamam, neyse... Commissar'ı çatı katında bulup öldürelim. O piç bedelini ödeyecek."] = "TAMAM, NEYSE... COMMİSSAR'I ÇATI KATINDA BULUP ÖLDÜRELİM. O PİÇ BEDELİNİ ÖDEYECEK.",
["Tamam, noktadayım!"] = "TAMAM, NOKTADAYIM!",
["Tamam, o Anahtar Kartını bulmaya çalışın."] = "TAMAM, O ANAHTAR KARTINI BULMAYA ÇALIŞIN.",
