["Tamam, o kasa dairesine girme vakti. Çabuk çabuk."] = "TAMAM, O KASA DAİRESİNE GİRME VAKTİ. ÇABUK ÇABUK.",
["Tamam, o kodun cevabını aramaya başlayın."] = "TAMAM, O KODUN CEVABINI ARAMAYA BAŞLAYIN.",
["Tamam, o mezbahaya girmeniz gerekiyor. Yakınlara C4 saklandı. Onunla yol açabilirsiniz."] = "TAMAM, O MEZBAHAYA GİRMENİZ GEREKİYOR. YAKINLARA C4 SAKLANDI. ONUNLA YOL AÇABİLİRSİNİZ.",
["Tamam, o rampanın indirilmesi gerek."] = "TAMAM, O RAMPANIN İNDİRİLMESİ GEREK.",
["Tamam, o tünele girin. Meksika'yı ziyaret etme vakti."] = "TAMAM, O TÜNELE GİRİN. MEKSİKA'YI ZİYARET ETME VAKTİ.",
["Tamam, o vinç parçalarını kapın."] = "TAMAM, O VİNÇ PARÇALARINI KAPIN.",
["Tamam, o zaman gürültülü yoldan yapalım. Çatışmaya hazır olun."] = "TAMAM, O ZAMAN GÜRÜLTÜLÜ YOLDAN YAPALIM. ÇATIŞMAYA HAZIR OLUN.",
["Tamam, o zaman gürültülü yolu seçiyoruz!"] = "TAMAM, O ZAMAN GÜRÜLTÜLÜ YOLU SEÇİYORUZ!",
["Tamam, o zaman yapalım!"] = "TAMAM, O ZAMAN YAPALIM!",
["Tamam, odayı zeminden ayırmak için testereleri kullanmamız gerekecek."] = "TAMAM, ODAYI ZEMİNDEN AYIRMAK İÇİN TESTERELERİ KULLANMAMIZ GEREKECEK.",
["Tamam, ofisi bu. Şimdi sonraki aşamaya geçiyoruz."] = "TAMAM, OFİSİ BU. ŞİMDİ SONRAKİ AŞAMAYA GEÇİYORUZ.",
["Tamam, olanları gözleyin. Sunucuyu gerçekten görmek istiyoruz."] = "TAMAM, OLANLARI GÖZLEYİN. SUNUCUYU GERÇEKTEN GÖRMEK İSTİYORUZ.",
["Tamam, on beş bin oldu! Şoförü sizi almaya göndereceğim."] = "TAMAM, ON BEŞ BİN OLDU! ŞOFÖRÜ SİZİ ALMAYA GÖNDERECEĞİM.",
["Tamam, on iki tane daha, işimiz biter."] = "TAMAM, ON İKİ TANE DAHA, İŞİMİZ BİTER.",
["Tamam, on kaldı. Yarıladık!"] = "TAMAM, ON KALDI. YARILADIK!",
["Tamam, onaylamanız gereken bir istek daha!"] = "TAMAM, ONAYLAMANIZ GEREKEN BİR İSTEK DAHA!",
["Tamam, onu deneyelim."] = "TAMAM, ONU DENEYELİM.",
["Tamam, onu oradan çıkarın."] = "TAMAM, ONU ORADAN ÇIKARIN.",
["Tamam, onu sandalyeye oturtun."] = "TAMAM, ONU SANDALYEYE OTURTUN.",
["Tamam, onuncu dalga geliyor!"] = "TAMAM, ONUNCU DALGA GELİYOR!",
["Tamam, orta ve sağ konsola basın. Hadi!"] = "TAMAM, ORTA VE SAĞ KONSOLA BASIN. HADİ!",
["Tamam, ortalık temiz. Geliyorum."] = "TAMAM, ORTALIK TEMİZ. GELİYORUM.",
["Tamam, oyuncakçıda Tin Boy oyuncaklarını arayın."] = "TAMAM, OYUNCAKÇIDA TİN BOY OYUNCAKLARINI ARAYIN.",
["Tamam, oyuncakçıdaymış. Tin Boy!"] = "TAMAM, OYUNCAKÇIDAYMIŞ. TİN BOY!",
["Tamam, paket yerde."] = "TAMAM, PAKET YERDE.",
["Tamam, paketi aldım. Eve dönüyorum."] = "TAMAM, PAKETİ ALDIM. EVE DÖNÜYORUM.",
["Tamam, paketiniz iniyor. Sky Express işiniz bitene kadar burada kalacak. İyi şanslar!"] = "TAMAM, PAKETİNİZ İNİYOR. SKY EXPRESS İŞİNİZ BİTENE KADAR BURADA KALACAK. İYİ ŞANSLAR!",
["Tamam, panik odasının kapısı iki anahtar kartı ve özel bir anahtarla kontrol ediliyor. Bulun onları."] = "TAMAM, PANİK ODASININ KAPISI İKİ ANAHTAR KARTI VE ÖZEL BİR ANAHTARLA KONTROL EDİLİYOR. BULUN ONLARI.",
["Tamam, paniğe kapılmayın, siz profesyonelsiniz!"] = "TAMAM, PANİĞE KAPILMAYIN, SİZ PROFESYONELSİNİZ!",
["Tamam, para güvende. Vlad votkaları alır kesin, polislere de biraz gerekecek..."] = "TAMAM, PARA GÜVENDE. VLAD VOTKALARI ALIR KESİN, POLİSLERE DE BİRAZ GEREKECEK...",
["Tamam, para vakti, millet. Ernesto'nun zemin Kasasını yağmalayacağız. O vinçleri zemine bağlayın."] = "TAMAM, PARA VAKTİ, MİLLET. ERNESTO'NUN ZEMİN KASASINI YAĞMALAYACAĞIZ. O VİNÇLERİ ZEMİNE BAĞLAYIN.",
["Tamam, paranın yanmasını beklerken şu kiralık Kasalardan bazılarını açabilirsiniz. İçlerinde ne bulursak bizim."] = "TAMAM, PARANIN YANMASINI BEKLERKEN ŞU KİRALIK KASALARDAN BAZILARINI AÇABİLİRSİNİZ. İÇLERİNDE NE BULURSAK BİZİM.",
["Tamam, paranın yanmasını beklerken şu kiralık kasalardan bazılarını açabilirsiniz. İçlerinde ne bulursak bizim."] = "TAMAM, PARANIN YANMASINI BEKLERKEN ŞU KİRALIK KASALARDAN BAZILARINI AÇABİLİRSİNİZ. İÇLERİNDE NE BULURSAK BİZİM.",
["Tamam, pilot başka bir termal mızrakla yolda. Açgözlüsünüz. Saygı duyarım."] = "TAMAM, PİLOT BAŞKA BİR TERMAL MIZRAKLA YOLDA. AÇGÖZLÜSÜNÜZ. SAYGI DUYARIM.",
["Tamam, pilot kafesi bankanın arkasındaki otoparktan almayı bekliyor. Hazır olsun."] = "TAMAM, PİLOT KAFESİ BANKANIN ARKASINDAKİ OTOPARKTAN ALMAYI BEKLİYOR. HAZIR OLSUN.",
["Tamam, pilot yolcusunu güvenle indirdiğini az önce doğruladı! Eve gidebilirsiniz, millet!"] = "TAMAM, PİLOT YOLCUSUNU GÜVENLE İNDİRDİĞİNİ AZ ÖNCE DOĞRULADI! EVE GİDEBİLİRSİNİZ, MİLLET!",
["Tamam, plan şu. Locke sizi kaçak olarak uçağa sokacak. İşaretini bekleyin, sonra fırlayın dışarı. Direniş hafif olmalı, sadece mürettebat. Para büyük paletlere paketlenmiş. Kargo kapılarından dışarı atın, yere inince toplarız. Basit."] = "TAMAM, PLAN ŞU. LOCKE SİZİ KAÇAK OLARAK UÇAĞA SOKACAK. İŞARETİNİ BEKLEYİN, SONRA FIRLAYIN DIŞARI. DİRENİŞ HAFİF OLMALI, SADECE MÜRETTEBAT. PARA BÜYÜK PALETLERE PAKETLENMİŞ. KARGO KAPILARINDAN DIŞARI ATIN, YERE İNİNCE TOPLARIZ. BASİT.",
["Tamam, planladığımız gibi limana gidin. Kokaini kamyonetten boşaltın. Hector'ın teknesinin gelmesi için depodan işaret vermelisiniz."] = "TAMAM, PLANLADIĞIMIZ GİBİ LİMANA GİDİN. KOKAİNİ KAMYONETTEN BOŞALTIN. HECTOR'IN TEKNESİNİN GELMESİ İÇİN DEPODAN İŞARET VERMELİSİNİZ.",
["Tamam, planladığımız gibi limana gidin. Kokaini kamyonetten indirin. Hector'ın teknesinin gelmesi için depodaki ışıklarla işaret vermeniz gerekecek. Gelince kokaini yükleyin, gerisini kaptan halleder."] = "TAMAM, PLANLADIĞIMIZ GİBİ LİMANA GİDİN. KOKAİNİ KAMYONETTEN İNDİRİN. HECTOR'IN TEKNESİNİN GELMESİ İÇİN DEPODAKİ IŞIKLARLA İŞARET VERMENİZ GEREKECEK. GELİNCE KOKAİNİ YÜKLEYİN, GERİSİNİ KAPTAN HALLEDER.",
["Tamam, planladığımız gibi limana gidin. Kokaini pikaptan indirin. Hector'ın teknesinin yanaşması için depodan işaret vermeniz gerekecek. Tekne geldiğinde kokaini güverteye taşıyın. Gerisini kaptan halleder."] = "TAMAM, PLANLADIĞIMIZ GİBİ LİMANA GİDİN. KOKAİNİ PİKAPTAN İNDİRİN. HECTOR'IN TEKNESİNİN YANAŞMASI İÇİN DEPODAN İŞARET VERMENİZ GEREKECEK. TEKNE GELDİĞİNDE KOKAİNİ GÜVERTEYE TAŞIYIN. GERİSİNİ KAPTAN HALLEDER.",
["Tamam, planı unutmayın. Altını çıkarın, altını taşıyın, sis perdesini kurun, tuzağı hazırlayın, kaçın. Hadi!"] = "TAMAM, PLANI UNUTMAYIN. ALTINI ÇIKARIN, ALTINI TAŞIYIN, SİS PERDESİNİ KURUN, TUZAĞI HAZIRLAYIN, KAÇIN. HADİ!",
["Tamam, planımızın sonraki adımı: Bile'ın getireceği C4. Bekleyin, onu bağlayayım. 'Bile, orada mısın? C4 lazım. Ne kadar sürer?'"] = "TAMAM, PLANIMIZIN SONRAKİ ADIMI: BILE'IN GETİRECEĞİ C4. BEKLEYİN, ONU BAĞLAYAYIM. 'BILE, ORADA MISIN? C4 LAZIM. NE KADAR SÜRER?'",
["Tamam, planın sonraki kısmına geçelim."] = "TAMAM, PLANIN SONRAKİ KISMINA GEÇELİM.",
["Tamam, polis araştırmaya geliyor. Sadece kontrol ediyorlar, sessizce halledebilirseniz... "] = "TAMAM, POLİS ARAŞTIRMAYA GELİYOR. SADECE KONTROL EDİYORLAR, SESSİZCE HALLEDEBİLİRSENİZ... ",
["Tamam, polis geliyor. İlk adım, muhafız odasında C4 aramak."] = "TAMAM, POLİS GELİYOR. İLK ADIM, MUHAFIZ ODASINDA C4 ARAMAK.",
["Tamam, polis santrali hareketlendi. Sanırım biri sizi gördü. Hazır olun!"] = "TAMAM, POLİS SANTRALİ HAREKETLENDİ. SANIRIM BİRİ SİZİ GÖRDÜ. HAZIR OLUN!",
["Tamam, polis yolda. Bu vurgun Pink Panther'dan çok Reservoir Dogs'a döndü. Güvenlik odasına gidin."] = "TAMAM, POLİS YOLDA. BU VURGUN PİNK PANTHER'DAN ÇOK RESERVOIR DOGS'A DÖNDÜ. GÜVENLİK ODASINA GİDİN.",
["Tamam, polisler incelemeye geldi. Eve girmelerine izin verip sessizce indirirseniz dikkat çekmeyiz."] = "TAMAM, POLİSLER İNCELEMEYE GELDİ. EVE GİRMELERİNE İZİN VERİP SESSİZCE İNDİRİRSENİZ DİKKAT ÇEKMEYİZ.",
["Tamam, polisler içeride. Sessizce indirin!"] = "TAMAM, POLİSLER İÇERİDE. SESSİZCE İNDİRİN!",
["Tamam, polisler işi bir üst seviyeye taşıdı. Daha zorlu birlikler geliyor!"] = "TAMAM, POLİSLER İŞİ BİR ÜST SEVİYEYE TAŞIDI. DAHA ZORLU BİRLİKLER GELİYOR!",
["Tamam, pompa çalışıyor! Kasa Dairesi dolsun."] = "TAMAM, POMPA ÇALIŞIYOR! KASA DAİRESİ DOLSUN.",
["Tamam, rehinelerin aptallık yapmayacağından emin olmanın yolunu bulmalıyız. Sahte Otomatik Taretleri kurun."] = "TAMAM, REHİNELERİN APTALLIK YAPMAYACAĞINDAN EMİN OLMANIN YOLUNU BULMALIYIZ. SAHTE OTOMATİK TARETLERİ KURUN.",
["Tamam, retina tarayıcı için FBI şefi lazım. Bulup rehin alın!"] = "TAMAM, RETİNA TARAYICI İÇİN FBI ŞEFİ LAZIM. BULUP REHİN ALIN!",
["Tamam, retina tarayıcısı için göz gerekiyor. Ne yazık ki canlısı. Oradaki FBI şefini bulup rehin alın."] = "TAMAM, RETİNA TARAYICISI İÇİN GÖZ GEREKİYOR. NE YAZIK Kİ CANLISI. ORADAKİ FBI ŞEFİNİ BULUP REHİN ALIN.",
["Tamam, rıhtım açıldı. Şimdi Moretta'yı çağırıp hareket ettirmeliyiz. Haberleşme frekansları ofislerdeki bilgisayarlardan birinde olmalı. Bulun. Ben bağlanıp konuşurum."] = "TAMAM, RIHTIM AÇILDI. ŞİMDİ MORETTA'YI ÇAĞIRIP HAREKET ETTİRMELİYİZ. HABERLEŞME FREKANSLARI OFİSLERDEKİ BİLGİSAYARLARDAN BİRİNDE OLMALI. BULUN. BEN BAĞLANIP KONUŞURUM.",
["Tamam, rıhtımda buluşuruz."] = "TAMAM, RIHTIMDA BULUŞURUZ.",
["Tamam, sabit diski alıp yanınızda götürün. "] = "TAMAM, SABİT DİSKİ ALIP YANINIZDA GÖTÜRÜN. ",
["Tamam, sabırlı olun dostlarım. Her kasa dairesinde kısa bir zaman kilidi var. Bilirsiniz, güvenlik için."] = "TAMAM, SABIRLI OLUN DOSTLARIM. HER KASA DAİRESİNDE KISA BİR ZAMAN KİLİDİ VAR. BİLİRSİNİZ, GÜVENLİK İÇİN.",
["Tamam, sadece bir tane kaldı."] = "TAMAM, SADECE BİR TANE KALDI.",
["Tamam, sakin sakin!"] = "TAMAM, SAKİN SAKİN!",
["Tamam, sakin sakin. Maskeleri çıkarıp kalabalığa karışın, hiçbir sorun yaşamayız. Minibüs sizi bekliyor olacak."] = "TAMAM, SAKİN SAKİN. MASKELERİ ÇIKARIP KALABALIĞA KARIŞIN, HİÇBİR SORUN YAŞAMAYIZ. MİNİBÜS SİZİ BEKLİYOR OLACAK.",
["Tamam, sanırım en kötüsü geride kaldı. Vlad'ın sürücüsü keçileri şehrin dışındaki bir çiftliğe götürdü; paketleri çıkarmaya hazırlar. Etrafta kalın. Çevreyi gözetleyin. Kolay iş, değil mi?"] = "TAMAM, SANIRIM EN KÖTÜSÜ GERİDE KALDI. VLAD'IN SÜRÜCÜSÜ KEÇİLERİ ŞEHRİN DIŞINDAKİ BİR ÇİFTLİĞE GÖTÜRDÜ; PAKETLERİ ÇIKARMAYA HAZIRLAR. ETRAFTA KALIN. ÇEVREYİ GÖZETLEYİN. KOLAY İŞ, DEĞİL Mİ?",
["Tamam, sanırım en kötüsü geride kaldı. Vlad'ın şoförü keçileri şehir dışındaki bir çiftliğe götürdü. Paketleri çıkarmaya hazırlar. Oralarda bekleyin. Çevreyi gözleyin. Kolay iş, değil mi?"] = "TAMAM, SANIRIM EN KÖTÜSÜ GERİDE KALDI. VLAD'IN ŞOFÖRÜ KEÇİLERİ ŞEHİR DIŞINDAKİ BİR ÇİFTLİĞE GÖTÜRDÜ. PAKETLERİ ÇIKARMAYA HAZIRLAR. ORALARDA BEKLEYİN. ÇEVREYİ GÖZLEYİN. KOLAY İŞ, DEĞİL Mİ?",
["Tamam, sanırım köprü iyi bir bırakma noktası olur."] = "TAMAM, SANIRIM KÖPRÜ İYİ BİR BIRAKMA NOKTASI OLUR.",
["Tamam, satıcımız geliyor. Bir saniye bekleyin."] = "TAMAM, SATICIMIZ GELİYOR. BİR SANİYE BEKLEYİN.",
["Tamam, sağ salim dışarı çıktım."] = "TAMAM, SAĞ SALİM DIŞARI ÇIKTIM.",
["Tamam, sağlam."] = "TAMAM, SAĞLAM.",
["Tamam, sağınızdaki kule! Onu yukarı çıkarın!"] = "TAMAM, SAĞINIZDAKİ KULE! ONU YUKARI ÇIKARIN!",
["Tamam, sekiz tane aldık!"] = "TAMAM, SEKİZ TANE ALDIK!",
["Tamam, sekizinci dalga geliyor!"] = "TAMAM, SEKİZİNCİ DALGA GELİYOR!",
["Tamam, sessiz kalıp gizlenmeyi unutun. Bir şey düşüneyim, bir dakika verin."] = "TAMAM, SESSİZ KALIP GİZLENMEYİ UNUTUN. BİR ŞEY DÜŞÜNEYİM, BİR DAKİKA VERİN.",
["Tamam, seçim şu: Şimdi kaçın ya da daha fazla ganimet toplayın. Karar sizin!"] = "TAMAM, SEÇİM ŞU: ŞİMDİ KAÇIN YA DA DAHA FAZLA GANİMET TOPLAYIN. KARAR SİZİN!",
["Tamam, sikerler, benim kaçma vaktim geldi!"] = "TAMAM, SİKERLER, BENİM KAÇMA VAKTİM GELDİ!",
["Tamam, sikerler..."] = "TAMAM, SİKERLER...",
["Tamam, siktir et, bu kadar! Daha fazla kalamam!"] = "TAMAM, SİKTİR ET, BU KADAR! DAHA FAZLA KALAMAM!",
["Tamam, siktir et..."] = "TAMAM, SİKTİR ET...",
["Tamam, silah zulalarını arıyorsunuz."] = "TAMAM, SİLAH ZULALARINI ARIYORSUNUZ.",
["Tamam, sinsice dolaşmak buraya kadarmış. Hareket vakti!"] = "TAMAM, SİNSİCE DOLAŞMAK BURAYA KADARMIŞ. HAREKET VAKTİ!",
["Tamam, sistem kırıldı."] = "TAMAM, SİSTEM KIRILDI.",
["Tamam, sisteme girdim. Birazdan kilidi açacağım. Şimdi tekrar ön tarafa çıkın, C4'ü alıp sokağa yerleştirin."] = "TAMAM, SİSTEME GİRDİM. BİRAZDAN KİLİDİ AÇACAĞIM. ŞİMDİ TEKRAR ÖN TARAFA ÇIKIN, C4'Ü ALIP SOKAĞA YERLEŞTİRİN.",
["Tamam, sistemi kırmak için bana biraz zaman verin."] = "TAMAM, SİSTEMİ KIRMAK İÇİN BANA BİRAZ ZAMAN VERİN.",
["Tamam, sistemine girdim. Laboratuvar birazdan açılacak."] = "TAMAM, SİSTEMİNE GİRDİM. LABORATUVAR BİRAZDAN AÇILACAK.",
["Tamam, siz hazır olunca hazırım."] = "TAMAM, SİZ HAZIR OLUNCA HAZIRIM.",
["Tamam, size şoför buldum, bağlıyorum."] = "TAMAM, SİZE ŞOFÖR BULDUM, BAĞLIYORUM.",
["Tamam, sizi alacak araç hazır. İkramiye isterseniz taşıyabildiğiniz kadar mühimmat götürebilirsiniz. Size kalmış."] = "TAMAM, SİZİ ALACAK ARAÇ HAZIR. İKRAMİYE İSTERSENİZ TAŞIYABİLDİĞİNİZ KADAR MÜHİMMAT GÖTÜREBİLİRSİNİZ. SİZE KALMIŞ.",
["Tamam, sizi alacak helikopter bu! Kokaini çabucak yükleyin!"] = "TAMAM, SİZİ ALACAK HELİKOPTER BU! KOKAİNİ ÇABUCAK YÜKLEYİN!",
["Tamam, sizi alacak şoför arkanızdaki sokakta!"] = "TAMAM, SİZİ ALACAK ŞOFÖR ARKANIZDAKİ SOKAKTA!",
["Tamam, sizi alacak şoför geldi! Arkanızdaki sokakta!"] = "TAMAM, SİZİ ALACAK ŞOFÖR GELDİ! ARKANIZDAKİ SOKAKTA!",
["Tamam, sizi alacak şoför hatta. Şimdi bağlıyorum."] = "TAMAM, SİZİ ALACAK ŞOFÖR HATTA. ŞİMDİ BAĞLIYORUM.",
["Tamam, sizi alacak şoför yolda."] = "TAMAM, SİZİ ALACAK ŞOFÖR YOLDA.",
["Tamam, sizi bekliyorum!"] = "TAMAM, SİZİ BEKLİYORUM!",
["Tamam, sizi eve götürelim."] = "TAMAM, SİZİ EVE GÖTÜRELİM.",
["Tamam, sizi fark ettiler. Silahları konuşturun, olur mu?"] = "TAMAM, SİZİ FARK ETTİLER. SİLAHLARI KONUŞTURUN, OLUR MU?",
["Tamam, sizi görüyorum. Kafesi silonun yanına bırakıyorum."] = "TAMAM, SİZİ GÖRÜYORUM. KAFESİ SİLONUN YANINA BIRAKIYORUM.",
["Tamam, solunda Crime.net istasyonun var. Sözleşmelerini buradan alırsın. Sağında güvenlik kameraların var. Etrafa bak, daha fazlasını anlatırım."] = "TAMAM, SOLUNDA CRIME.NET İSTASYONUN VAR. SÖZLEŞMELERİNİ BURADAN ALIRSIN. SAĞINDA GÜVENLİK KAMERALARIN VAR. ETRAFA BAK, DAHA FAZLASINI ANLATIRIM.",
["Tamam, son adım. Şunu açalım."] = "TAMAM, SON ADIM. ŞUNU AÇALIM.",
["Tamam, son elf de raftan düştü, evet. Siktir edin onu. Gitme ve Noel ikramiyenizin tadını çıkarma vakti, dostlar!"] = "TAMAM, SON ELF DE RAFTAN DÜŞTÜ, EVET. SİKTİR EDİN ONU. GİTME VE NOEL İKRAMİYENİZİN TADINI ÇIKARMA VAKTİ, DOSTLAR!",
["Tamam, sonuncuları da bunlardı. Şimdi burada olanları kimsenin bilmediğinden emin olmamız gerek. Bir telefon açacağım, bekleyin millet..."] = "TAMAM, SONUNCULARI DA BUNLARDI. ŞİMDİ BURADA OLANLARI KİMSENİN BİLMEDİĞİNDEN EMİN OLMAMIZ GEREK. BİR TELEFON AÇACAĞIM, BEKLEYİN MİLLET...",
["Tamam, sonunda!"] = "TAMAM, SONUNDA!",
["Tamam, sonunda! Tanrım!"] = "TAMAM, SONUNDA! TANRIM!",
["Tamam, standart banka soygunu ama altın sevkiyatı gününde gidiyoruz. Likit kalmak gerek, değil mi?"] = "TAMAM, STANDART BANKA SOYGUNU AMA ALTIN SEVKİYATI GÜNÜNDE GİDİYORUZ. LİKİT KALMAK GEREK, DEĞİL Mİ?",
["Tamam, standart bir iş ama bu sefer altın kaplama, ne demek istediğimi anladıysanız. "] = "TAMAM, STANDART BİR İŞ AMA BU SEFER ALTIN KAPLAMA, NE DEMEK İSTEDİĞİMİ ANLADIYSANIZ. ",
["Tamam, sunağın arkasında bariz bir giriş var ama patlatarak açmamız gerekecek. "] = "TAMAM, SUNAĞIN ARKASINDA BARİZ BİR GİRİŞ VAR AMA PATLATARAK AÇMAMIZ GEREKECEK. ",
["Tamam, sunağın arkasındaki duvar bir girişi gizliyor ama güzel patlayıcılarla açmanız gerekecek! "] = "TAMAM, SUNAĞIN ARKASINDAKİ DUVAR BİR GİRİŞİ GİZLİYOR AMA GÜZEL PATLAYICILARLA AÇMANIZ GEREKECEK! ",
["Tamam, sunucu Bilişim Bölümündeki ofislerden birinde. Yerini bulup alın!"] = "TAMAM, SUNUCU BİLİŞİM BÖLÜMÜNDEKİ OFİSLERDEN BİRİNDE. YERİNİ BULUP ALIN!",
["Tamam, sunucu bu. Karıştırıcıyı takın. "] = "TAMAM, SUNUCU BU. KARIŞTIRICIYI TAKIN. ",
["Tamam, sunucu odası burası. İçeri girin de bilgisayara erişelim."] = "TAMAM, SUNUCU ODASI BURASI. İÇERİ GİRİN DE BİLGİSAYARA ERİŞELİM.",
["Tamam, sunucu odası orada. Şimdi içeri girmek gerek. Tuş takımının şifresi buralarda bir yerde. Matkap da seçenek ama güvenlikçileri çekebilir."] = "TAMAM, SUNUCU ODASI ORADA. ŞİMDİ İÇERİ GİRMEK GEREK. TUŞ TAKIMININ ŞİFRESİ BURALARDA BİR YERDE. MATKAP DA SEÇENEK AMA GÜVENLİKÇİLERİ ÇEKEBİLİR.",
["Tamam, sunucu odasına ulaştığından emin olun."] = "TAMAM, SUNUCU ODASINA ULAŞTIĞINDAN EMİN OLUN.",
["Tamam, sunucu odasını bulup içeri girin. Artık alarmları devre dışı bırakmanın anlamı yok."] = "TAMAM, SUNUCU ODASINI BULUP İÇERİ GİRİN. ARTIK ALARMLARI DEVRE DIŞI BIRAKMANIN ANLAMI YOK.",
["Tamam, sunucu odasının kapısı açıldı."] = "TAMAM, SUNUCU ODASININ KAPISI AÇILDI.",
["Tamam, sunucu odasının kapısı bu."] = "TAMAM, SUNUCU ODASININ KAPISI BU.",
["Tamam, sunucu onda. 25 milyon dolar bizim olabilir. 25 milyon! Az önce aldığı sunucu da bunun anahtarı!"] = "TAMAM, SUNUCU ONDA. 25 MİLYON DOLAR BİZİM OLABİLİR. 25 MİLYON! AZ ÖNCE ALDIĞI SUNUCU DA BUNUN ANAHTARI!",
["Tamam, sunucuyu bağlayın da başlayalım."] = "TAMAM, SUNUCUYU BAĞLAYIN DA BAŞLAYALIM.",
["Tamam, sunucuyu kilitlediler. O engeli açın."] = "TAMAM, SUNUCUYU KİLİTLEDİLER. O ENGELİ AÇIN.",
["Tamam, söyle bakalım şef. HEY, dikkat et!!"] = "TAMAM, SÖYLE BAKALIM ŞEF. HEY, DİKKAT ET!!",
["Tamam, sözünüzü tuttunuz! Şimdi sizi oradan çıkarayım."] = "TAMAM, SÖZÜNÜZÜ TUTTUNUZ! ŞİMDİ SİZİ ORADAN ÇIKARAYIM.",
["Tamam, sırada ne var..."] = "TAMAM, SIRADA NE VAR...",
["Tamam, sırada ne var?"] = "TAMAM, SIRADA NE VAR?",
["Tamam, sıradaki adım."] = "TAMAM, SIRADAKİ ADIM.",
["Tamam, sıradaki adıma geçin."] = "TAMAM, SIRADAKİ ADIMA GEÇİN.",
["Tamam, sıradaki adıma hazırsınız."] = "TAMAM, SIRADAKİ ADIMA HAZIRSINIZ.",
["Tamam, sıradaki işe geçelim."] = "TAMAM, SIRADAKİ İŞE GEÇELİM.",
["Tamam, sıradaki malzeme..."] = "TAMAM, SIRADAKİ MALZEME...",
["Tamam, sıradaki sistem kırma işlemini başlatın."] = "TAMAM, SIRADAKİ SİSTEM KIRMA İŞLEMİNİ BAŞLATIN.",
["Tamam, sıradakini almak için yine dönüyorum. Doğrudan evin üzerine bırakabiliriz."] = "TAMAM, SIRADAKİNİ ALMAK İÇİN YİNE DÖNÜYORUM. DOĞRUDAN EVİN ÜZERİNE BIRAKABİLİRİZ.",
["Tamam, sıradakini tam lobiye bırakalım. Geri dönüyorum."] = "TAMAM, SIRADAKİNİ TAM LOBİYE BIRAKALIM. GERİ DÖNÜYORUM.",
["Tamam, sızma bitti. Garaja inip asansörü çağırın. Çatı katına çıkabilmeniz için kuyunun boş olması gerek."] = "TAMAM, SIZMA BİTTİ. GARAJA İNİP ASANSÖRÜ ÇAĞIRIN. ÇATI KATINA ÇIKABİLMENİZ İÇİN KUYUNUN BOŞ OLMASI GEREK.",
["Tamam, tabloları bana atın, paranızı alın!"] = "TAMAM, TABLOLARI BANA ATIN, PARANIZI ALIN!",
["Tamam, takas yapalım!"] = "TAMAM, TAKAS YAPALIM!",
["Tamam, tam düşündüğüm gibi... lanet amatörler. Şu USB belleği bulmaya çalışın."] = "TAMAM, TAM DÜŞÜNDÜĞÜM GİBİ... LANET AMATÖRLER. ŞU USB BELLEĞİ BULMAYA ÇALIŞIN.",
["Tamam, tamam güzel."] = "TAMAM, TAMAM GÜZEL.",
["Tamam, tamam!"] = "TAMAM, TAMAM!",
["Tamam, tamam! B planı, sunucu odasını bulun. Siktir!"] = "TAMAM, TAMAM! B PLANI, SUNUCU ODASINI BULUN. SİKTİR!",
["Tamam, tamam! Hallediyorum!"] = "TAMAM, TAMAM! HALLEDİYORUM!",
["Tamam, tamam, bir tane daha buldum."] = "TAMAM, TAMAM, BİR TANE DAHA BULDUM.",
["Tamam, tamam, bunu değiştirmeliyiz!"] = "TAMAM, TAMAM, BUNU DEĞİŞTİRMELİYİZ!",
["Tamam, tamam, güvenlik sistemini hackledim. Bütün kilitler açıldı."] = "TAMAM, TAMAM, GÜVENLİK SİSTEMİNİ HACKLEDİM. BÜTÜN KİLİTLER AÇILDI.",
["Tamam, tamam, nerede... Geri vites?"] = "TAMAM, TAMAM, NEREDE... GERİ VİTES?",
["Tamam, tamam. Bir saniye bekleyin."] = "TAMAM, TAMAM. BİR SANİYE BEKLEYİN.",
["Tamam, tamam. Gerekenleri aldım. Beni kamyona götürün de bitireyim."] = "TAMAM, TAMAM. GEREKENLERİ ALDIM. BENİ KAMYONA GÖTÜRÜN DE BİTİREYİM.",
["Tamam, tamam. Şifre muhtemelen bir e-postadadır. Bir FBI bilgisayarı bulup sisteme girin."] = "TAMAM, TAMAM. ŞİFRE MUHTEMELEN BİR E-POSTADADIR. BİR FBI BİLGİSAYARI BULUP SİSTEME GİRİN.",
["Tamam, tarama sürüyor. Şimdi kesilmeden tamamlandığından emin olun."] = "TAMAM, TARAMA SÜRÜYOR. ŞİMDİ KESİLMEDEN TAMAMLANDIĞINDAN EMİN OLUN.",
["Tamam, taramaya başlamak için her şey hazır."] = "TAMAM, TARAMAYA BAŞLAMAK İÇİN HER ŞEY HAZIR.",
["Tamam, taç bu!"] = "TAMAM, TAÇ BU!",
["Tamam, tekneyi görüyorum, neredeyse geldi. Çantalarla hazır olun."] = "TAMAM, TEKNEYİ GÖRÜYORUM, NEREDEYSE GELDİ. ÇANTALARLA HAZIR OLUN.",
["Tamam, tekrar dönüyorum! Bana 30 saniye verin."] = "TAMAM, TEKRAR DÖNÜYORUM! BANA 30 SANİYE VERİN.",
["Tamam, tekrar edeyim: Taxman IRS'ten, büyük bir şirketle şüpheli anlaşma yapıyor. Onlara hayati veriler içeren bir sunucu satıyor."] = "TAMAM, TEKRAR EDEYİM: TAXMAN IRS'TEN, BÜYÜK BİR ŞİRKETLE ŞÜPHELİ ANLAŞMA YAPIYOR. ONLARA HAYATİ VERİLER İÇEREN BİR SUNUCU SATIYOR.",
["Tamam, tekrar çalışıyor gibi. Harika."] = "TAMAM, TEKRAR ÇALIŞIYOR GİBİ. HARİKA.",
["Tamam, tepedesiniz değil mi? Kemerlerini bağlamasına yardım edip balonu bırakın. Uçak her an gelebilir."] = "TAMAM, TEPEDESİNİZ DEĞİL Mİ? KEMERLERİNİ BAĞLAMASINA YARDIM EDİP BALONU BIRAKIN. UÇAK HER AN GELEBİLİR.",
["Tamam, tepkimeyi sürdürmek için tuz ruhu ekleyin."] = "TAMAM, TEPKİMEYİ SÜRDÜRMEK İÇİN TUZ RUHU EKLEYİN.",
["Tamam, termit deldi geçti. Helikopter su getiriyor. Gelince bağlayın."] = "TAMAM, TERMİT DELDİ GEÇTİ. HELİKOPTER SU GETİRİYOR. GELİNCE BAĞLAYIN.",
["Tamam, termit deldi geçti. Pis ama güzel. Şimdi çekme vincini kurun, tamam mı?"] = "TAMAM, TERMİT DELDİ GEÇTİ. PİS AMA GÜZEL. ŞİMDİ ÇEKME VİNCİNİ KURUN, TAMAM MI?",
["Tamam, teslim olma fırsatınız vardı. Artık en ağır baskıyı uygulamak zorundayız."] = "TAMAM, TESLİM OLMA FIRSATINIZ VARDI. ARTIK EN AĞIR BASKIYI UYGULAMAK ZORUNDAYIZ.",
["Tamam, tuş takımı etkin. Yanına gidip şifreyi girin."] = "TAMAM, TUŞ TAKIMI ETKİN. YANINA GİDİP ŞİFREYİ GİRİN.",
["Tamam, tüymemin vakti geldi!"] = "TAMAM, TÜYMEMİN VAKTİ GELDİ!",
["Tamam, unutmayın, barışçıl kalmalı. Metamfetamini bilgiyle, fazlasını parayla takas edin. Kolay ve temiz, kan dökmeden ayrılın. "] = "TAMAM, UNUTMAYIN, BARIŞÇIL KALMALI. METAMFETAMİNİ BİLGİYLE, FAZLASINI PARAYLA TAKAS EDİN. KOLAY VE TEMİZ, KAN DÖKMEDEN AYRILIN. ",
["Tamam, unutmayın: Her tablo için bir çanta para."] = "TAMAM, UNUTMAYIN: HER TABLO İÇİN BİR ÇANTA PARA.",
["Tamam, uzaklaşın! O pencereler kırıldığında orada olmak istemezsiniz!"] = "TAMAM, UZAKLAŞIN! O PENCERELER KIRILDIĞINDA ORADA OLMAK İSTEMEZSİNİZ!",
["Tamam, uçak yakında geliyor."] = "TAMAM, UÇAK YAKINDA GELİYOR.",
["Tamam, uçaksavarı kontrol eden radar bu. Yerle bir edin. "] = "TAMAM, UÇAKSAVARI KONTROL EDEN RADAR BU. YERLE BİR EDİN. ",
["Tamam, vagona girdik. İçini görmek için kamerayı kullanın."] = "TAMAM, VAGONA GİRDİK. İÇİNİ GÖRMEK İÇİN KAMERAYI KULLANIN.",
["Tamam, veri tabanı ikiye ayrılmış. Şimdi ilkini alıyorum."] = "TAMAM, VERİ TABANI İKİYE AYRILMIŞ. ŞİMDİ İLKİNİ ALIYORUM.",
["Tamam, veri tabanının ikinci yarısını alıyorum. Tamamını indirirsek makineleri taşıyan kamyonu bulma şansımız güçlü."] = "TAMAM, VERİ TABANININ İKİNCİ YARISINI ALIYORUM. TAMAMINI İNDİRİRSEK MAKİNELERİ TAŞIYAN KAMYONU BULMA ŞANSIMIZ GÜÇLÜ.",
["Tamam, veriler diğer odadaki sunucuya aktarılıyor. Gidip alabilir ya da kalıp daha fazla ceset tarayabilirsiniz. Eminim Jimmy bir işe yarar bulur; bu da bize daha fazla para demek."] = "TAMAM, VERİLER DİĞER ODADAKİ SUNUCUYA AKTARILIYOR. GİDİP ALABİLİR YA DA KALIP DAHA FAZLA CESET TARAYABİLİRSİNİZ. EMİNİM JIMMY BİR İŞE YARAR BULUR; BU DA BİZE DAHA FAZLA PARA DEMEK.",
["Tamam, veriler karıştı! Sıradan bir sabit disk arızası gibi görünecek."] = "TAMAM, VERİLER KARIŞTI! SIRADAN BİR SABİT DİSK ARIZASI GİBİ GÖRÜNECEK.",
["Tamam, veriler karıştı! Sıradan bir veri hatası gibi görünecek."] = "TAMAM, VERİLER KARIŞTI! SIRADAN BİR VERİ HATASI GİBİ GÖRÜNECEK.",
["Tamam, veriler karıştırıldı. Basit bir sabit disk arızası gibi görünecek. "] = "TAMAM, VERİLER KARIŞTIRILDI. BASİT BİR SABİT DİSK ARIZASI GİBİ GÖRÜNECEK. ",
["Tamam, verileri bozduk. Sıradan bir sabit disk arızası gibi görünecek. "] = "TAMAM, VERİLERİ BOZDUK. SIRADAN BİR SABİT DİSK ARIZASI GİBİ GÖRÜNECEK. ",
["Tamam, verin!"] = "TAMAM, VERİN!",
["Tamam, vurkaç vakti."] = "TAMAM, VURKAÇ VAKTİ.",
["Tamam, yaklaştım ama bırakma bölgesine keskin nişancılar yayılmış. C4'ü bırakmadan önce onları halletmelisiniz."] = "TAMAM, YAKLAŞTIM AMA BIRAKMA BÖLGESİNE KESKİN NİŞANCILAR YAYILMIŞ. C4'Ü BIRAKMADAN ÖNCE ONLARI HALLETMELİSİNİZ.",
["Tamam, yaklaşık 5000 dolar oldu."] = "TAMAM, YAKLAŞIK 5000 DOLAR OLDU.",
["Tamam, yaklaşıyorum. Motoru hazırlayın."] = "TAMAM, YAKLAŞIYORUM. MOTORU HAZIRLAYIN.",
["Tamam, yakında dönüyorum!"] = "TAMAM, YAKINDA DÖNÜYORUM!",
["Tamam, yakında dönüyorum."] = "TAMAM, YAKINDA DÖNÜYORUM.",
["Tamam, yakında geri geliyorum!"] = "TAMAM, YAKINDA GERİ GELİYORUM!",
["Tamam, yakında geri geliyorum."] = "TAMAM, YAKINDA GERİ GELİYORUM.",
["Tamam, yakında oradayım!"] = "TAMAM, YAKINDA ORADAYIM!",
["Tamam, yakınız. Onu sağınızdaki kulenin tepesine çıkarın!"] = "TAMAM, YAKINIZ. ONU SAĞINIZDAKİ KULENİN TEPESİNE ÇIKARIN!",
["Tamam, yakıt deposu dolu, pervaneler dönüyor, yük güvende. Buradan çıkma vakti. Beyler, lütfen bana katılın!"] = "TAMAM, YAKIT DEPOSU DOLU, PERVANELER DÖNÜYOR, YÜK GÜVENDE. BURADAN ÇIKMA VAKTİ. BEYLER, LÜTFEN BANA KATILIN!",
["Tamam, yan, yan, yan."] = "TAMAM, YAN, YAN, YAN.",
["Tamam, yanaştı! Güverteye çıkıp konteynerleri aramaya başlayın."] = "TAMAM, YANAŞTI! GÜVERTEYE ÇIKIP KONTEYNERLERİ ARAMAYA BAŞLAYIN.",
["Tamam, yanıyor. Yerinizde olsam elimiz boş çıkmayalım diye diğer kamyonları boşaltırdım."] = "TAMAM, YANIYOR. YERİNİZDE OLSAM ELİMİZ BOŞ ÇIKMAYALIM DİYE DİĞER KAMYONLARI BOŞALTIRDIM.",
["Tamam, yapacağınız şu. Kasaya bir matkap takın. Bir delik açın. Sonra içini suyla doldurmalıyız. Bahçe hortumunu aşağı sürükleyin."] = "TAMAM, YAPACAĞINIZ ŞU. KASAYA BİR MATKAP TAKIN. BİR DELİK AÇIN. SONRA İÇİNİ SUYLA DOLDURMALIYIZ. BAHÇE HORTUMUNU AŞAĞI SÜRÜKLEYİN.",
["Tamam, yedinci dalga geliyor!"] = "TAMAM, YEDİNCİ DALGA GELİYOR!",
["Tamam, yeni bir planım var ama hızlı olmalısınız. Mr Blonde, dondurucu sıvıyı getirdin mi?"] = "TAMAM, YENİ BİR PLANIM VAR AMA HIZLI OLMALISINIZ. MR BLONDE, DONDURUCU SIVIYI GETİRDİN Mİ?",
["Tamam, yeni plan vakti!"] = "TAMAM, YENİ PLAN VAKTİ!",
["Tamam, yeni plan: Şunun yanından gizlice geçip güvenlik odasını bulun. Böylece bütün kameraları tek seferde devre dışı bırakabiliriz. "] = "TAMAM, YENİ PLAN: ŞUNUN YANINDAN GİZLİCE GEÇİP GÜVENLİK ODASINI BULUN. BÖYLECE BÜTÜN KAMERALARI TEK SEFERDE DEVRE DIŞI BIRAKABİLİRİZ. ",
["Tamam, yeniden çalışıyorum ama şu lanet elektriği açık tutun."] = "TAMAM, YENİDEN ÇALIŞIYORUM AMA ŞU LANET ELEKTRİĞİ AÇIK TUTUN.",
["Tamam, yer burası. Trene gidip bağlantınızı bulun. Sizinle orada buluşacaklarını söylediler. Şimdilik her şey iyi görünüyor. Tabloları takas edip çabucak çıkın. İşi aksatmayın."] = "TAMAM, YER BURASI. TRENE GİDİP BAĞLANTINIZI BULUN. SİZİNLE ORADA BULUŞACAKLARINI SÖYLEDİLER. ŞİMDİLİK HER ŞEY İYİ GÖRÜNÜYOR. TABLOLARI TAKAS EDİP ÇABUCAK ÇIKIN. İŞİ AKSATMAYIN.",
["Tamam, yerimdeyim!"] = "TAMAM, YERİMDEYİM!",
["Tamam, yerimi aldım!"] = "TAMAM, YERİMİ ALDIM!",
["Tamam, yeterince aldınız... Ya da daha fazlası için kalabilirsiniz."] = "TAMAM, YETERİNCE ALDINIZ... YA DA DAHA FAZLASI İÇİN KALABİLİRSİNİZ.",
["Tamam, yeterince film çektik. Kaydı alın, daha fazla ganimet için kalmayacaksanız kaçın."] = "TAMAM, YETERİNCE FİLM ÇEKTİK. KAYDI ALIN, DAHA FAZLA GANİMET İÇİN KALMAYACAKSANIZ KAÇIN.",
["Tamam, yeterince para kazandık. Daha fazla ganimet için oyalanmak istemiyorsanız kaydı alıp kaçın."] = "TAMAM, YETERİNCE PARA KAZANDIK. DAHA FAZLA GANİMET İÇİN OYALANMAK İSTEMİYORSANIZ KAYDI ALIP KAÇIN.",
["Tamam, yetkilendirme işe yaradı. Şimdi tarayıcıyı çalıştırın."] = "TAMAM, YETKİLENDİRME İŞE YARADI. ŞİMDİ TARAYICIYI ÇALIŞTIRIN.",
["Tamam, yine aynı: Alabildiğiniz kadar çantayı güvene alın ya da buradan ayrılın. Karar verin!"] = "TAMAM, YİNE AYNI: ALABİLDİĞİNİZ KADAR ÇANTAYI GÜVENE ALIN YA DA BURADAN AYRILIN. KARAR VERİN!",
["Tamam, yine gitti. Ofisine dönün, olur mu?"] = "TAMAM, YİNE GİTTİ. OFİSİNE DÖNÜN, OLUR MU?",
["Tamam, yine ilerliyoruz. Heriflerin bir şeyi bozmasına izin vermeyin."] = "TAMAM, YİNE İLERLİYORUZ. HERİFLERİN BİR ŞEYİ BOZMASINA İZİN VERMEYİN.",
["Tamam, yine savaşa hazır olmalısın. Kokaini al."] = "TAMAM, YİNE SAVAŞA HAZIR OLMALISIN. KOKAİNİ AL.",
["Tamam, yine çalışıyoruz. Dayanın yeter."] = "TAMAM, YİNE ÇALIŞIYORUZ. DAYANIN YETER.",
