["Tamam, şimdi oradan yürüyüp çıkın. Dikkatlice..."] = "TAMAM, ŞİMDİ ORADAN YÜRÜYÜP ÇIKIN. DİKKATLİCE...",
["Tamam, şimdi parayı yakın."] = "TAMAM, ŞİMDİ PARAYI YAKIN.",
["Tamam, şimdi pilotu bekleyin."] = "TAMAM, ŞİMDİ PİLOTU BEKLEYİN.",
["Tamam, şimdi rampadan inip çıkın."] = "TAMAM, ŞİMDİ RAMPADAN İNİP ÇIKIN.",
["Tamam, şimdi rıhtımlara gidiyorsunuz. Bu iş bitmedi!"] = "TAMAM, ŞİMDİ RIHTIMLARA GİDİYORSUNUZ. BU İŞ BİTMEDİ!",
["Tamam, şimdi sadece Bile'ın gelmesini bekleyeceksiniz. Umarım fazla sürmez."] = "TAMAM, ŞİMDİ SADECE BILE'IN GELMESİNİ BEKLEYECEKSİNİZ. UMARIM FAZLA SÜRMEZ.",
["Tamam, şimdi say."] = "TAMAM, ŞİMDİ SAY.",
["Tamam, şimdi sessiz kalıp Vlad'ın bütün ‘kıymetli’ ganimetini toplayın."] = "TAMAM, ŞİMDİ SESSİZ KALIP VLAD'IN BÜTÜN ‘KIYMETLİ’ GANİMETİNİ TOPLAYIN.",
["Tamam, şimdi silahı ikinci kilide doğrultmalısınız."] = "TAMAM, ŞİMDİ SİLAHI İKİNCİ KİLİDE DOĞRULTMALISINIZ.",
["Tamam, şimdi silahı şarj etmek için kontrol panelini bulun."] = "TAMAM, ŞİMDİ SİLAHI ŞARJ ETMEK İÇİN KONTROL PANELİNİ BULUN.",
["Tamam, şimdi sisteme giriyorum..."] = "TAMAM, ŞİMDİ SİSTEME GİRİYORUM...",
["Tamam, şimdi sunucu odası... Daha önce bulduğunuz dizüstü bilgisayarla size erişim sağlayabilirim. Geri dönüp beni bağlayın."] = "TAMAM, ŞİMDİ SUNUCU ODASI... DAHA ÖNCE BULDUĞUNUZ DİZÜSTÜ BİLGİSAYARLA SİZE ERİŞİM SAĞLAYABİLİRİM. GERİ DÖNÜP BENİ BAĞLAYIN.",
["Tamam, şimdi sürün. Gidin gidin gidin!"] = "TAMAM, ŞİMDİ SÜRÜN. GİDİN GİDİN GİDİN!",
["Tamam, şimdi sıra..."] = "TAMAM, ŞİMDİ SIRA...",
["Tamam, şimdi trenin üstüne çıkıp kancaları sabitleyin. Ne kadar sıkı o kadar iyi."] = "TAMAM, ŞİMDİ TRENİN ÜSTÜNE ÇIKIP KANCALARI SABİTLEYİN. NE KADAR SIKI O KADAR İYİ.",
["Tamam, şimdi tüpleri kasa dairesine takın."] = "TAMAM, ŞİMDİ TÜPLERİ KASA DAİRESİNE TAKIN.",
["Tamam, şimdi umalım da sizi çabucak arasınlar."] = "TAMAM, ŞİMDİ UMALIM DA SİZİ ÇABUCAK ARASINLAR.",
["Tamam, şimdi uygun Anahtar Kartını bulmalısınız."] = "TAMAM, ŞİMDİ UYGUN ANAHTAR KARTINI BULMALISINIZ.",
["Tamam, şimdi vurun onu! Vurun o aşağılık piçi!"] = "TAMAM, ŞİMDİ VURUN ONU! VURUN O AŞAĞILIK PİÇİ!",
["Tamam, şimdi ya depoyu açın ya da geçmek için o kamyonu aradan çıkarın."] = "TAMAM, ŞİMDİ YA DEPOYU AÇIN YA DA GEÇMEK İÇİN O KAMYONU ARADAN ÇIKARIN.",
["Tamam, şimdi yakıt dolduruyor. Acele etmesini söyledim ama..."] = "TAMAM, ŞİMDİ YAKIT DOLDURUYOR. ACELE ETMESİNİ SÖYLEDİM AMA...",
["Tamam, şimdi çantaları kamyona atın. En az dört çanta lazım."] = "TAMAM, ŞİMDİ ÇANTALARI KAMYONA ATIN. EN AZ DÖRT ÇANTA LAZIM.",
["Tamam, şimdi çantaları kamyona koyun da bu işi bitirelim."] = "TAMAM, ŞİMDİ ÇANTALARI KAMYONA KOYUN DA BU İŞİ BİTİRELİM.",
["Tamam, şimdi çatıya!"] = "TAMAM, ŞİMDİ ÇATIYA!",
["Tamam, şimdi şalteri indirin. Bakalım BFD neler yapabiliyormuş!"] = "TAMAM, ŞİMDİ ŞALTERİ İNDİRİN. BAKALIM BFD NELER YAPABİLİYORMUŞ!",
["Tamam, şimdi şifre. Jiu Feng, önemli bilgileri yakındaki ofiste tuttuklarını söyledi."] = "TAMAM, ŞİMDİ ŞİFRE. JIU FENG, ÖNEMLİ BİLGİLERİ YAKINDAKİ OFİSTE TUTTUKLARINI SÖYLEDİ.",
["Tamam, şimdi şu dizüstüler ne durumda?"] = "TAMAM, ŞİMDİ ŞU DİZÜSTÜLER NE DURUMDA?",
["Tamam, şimdilik dengeli görünüyor. Daha malzeme ekleyin..."] = "TAMAM, ŞİMDİLİK DENGELİ GÖRÜNÜYOR. DAHA MALZEME EKLEYİN...",
["Tamam, şimdilik yeter."] = "TAMAM, ŞİMDİLİK YETER.",
["Tamam, şirketin kiralık fedaileri geliyor."] = "TAMAM, ŞİRKETİN KİRALIK FEDAİLERİ GELİYOR.",
["Tamam, şu adamı bulalım. Buralarda bir yerde olmalı."] = "TAMAM, ŞU ADAMI BULALIM. BURALARDA BİR YERDE OLMALI.",
["Tamam, şu işi yapalım."] = "TAMAM, ŞU İŞİ YAPALIM.",
["Tamam, şu kapıyı halledelim! Biraz ısı verin, çabuk çabuk."] = "TAMAM, ŞU KAPIYI HALLEDELİM! BİRAZ ISI VERİN, ÇABUK ÇABUK.",
["Tamam, şu mereti buradan çekip çıkarıyorum. Siz polisleri uzak tutun!"] = "TAMAM, ŞU MERETİ BURADAN ÇEKİP ÇIKARIYORUM. SİZ POLİSLERİ UZAK TUTUN!",
["Tamam, şunu deneyelim. Limanın ağına bağlı bir şey bulun. Sevkiyat manifestolarını açabilirim herhâlde. Nereye gittiklerine dair ipucu olabilir."] = "TAMAM, ŞUNU DENEYELİM. LİMANIN AĞINA BAĞLI BİR ŞEY BULUN. SEVKİYAT MANİFESTOLARINI AÇABİLİRİM HERHÂLDE. NEREYE GİTTİKLERİNE DAİR İPUCU OLABİLİR.",
["Tamam."] = "TAMAM.",
["Tamam. (telefondan başkasına seslenir) Dwayne, yukarıya birkaç adam gönder, biraz kıç tekmelesinler."] = "TAMAM. (TELEFONDAN BAŞKASINA SESLENİR) DWAYNE, YUKARIYA BİRKAÇ ADAM GÖNDER, BİRAZ KIÇ TEKMELESİNLER.",
["Tamam. Adamı duydunuz. Mal keçilerin İÇİNDE, keçiler de şehir merkezinin her yerine dağılmış. Toplayın."] = "TAMAM. ADAMI DUYDUNUZ. MAL KEÇİLERİN İÇİNDE, KEÇİLER DE ŞEHİR MERKEZİNİN HER YERİNE DAĞILMIŞ. TOPLAYIN.",
["Tamam. Altını 61 numaralı konteynere saklamalısınız. Avluda."] = "TAMAM. ALTINI 61 NUMARALI KONTEYNERE SAKLAMALISINIZ. AVLUDA.",
["Tamam. Ama işte uyuşturucu yok demiştik. Dikkatli olsan iyi olur, yoksa patron kıçını tekmeler."] = "TAMAM. AMA İŞTE UYUŞTURUCU YOK DEMİŞTİK. DİKKATLİ OLSAN İYİ OLUR, YOKSA PATRON KIÇINI TEKMELER.",
["Tamam. Artık ana panelin kontrolünü devralabilirim."] = "TAMAM. ARTIK ANA PANELİN KONTROLÜNÜ DEVRALABİLİRİM.",
["Tamam. Bakması için oraya bir ekip yollayacağız."] = "TAMAM. BAKMASI İÇİN ORAYA BİR EKİP YOLLAYACAĞIZ.",
["Tamam. Bana bir dakika kadar verin."] = "TAMAM. BANA BİR DAKİKA KADAR VERİN.",
["Tamam. Banka müdürünü bulun."] = "TAMAM. BANKA MÜDÜRÜNÜ BULUN.",
["Tamam. Beklenmedik bir şey ama hâlâ yapacak işimiz var."] = "TAMAM. BEKLENMEDİK BİR ŞEY AMA HÂLÂ YAPACAK İŞİMİZ VAR.",
["Tamam. Bir anahtar ve bir şifre gerekiyor. En azından ne aramanız gerektiğini biliyoruz."] = "TAMAM. BİR ANAHTAR VE BİR ŞİFRE GEREKİYOR. EN AZINDAN NE ARAMANIZ GEREKTİĞİNİ BİLİYORUZ.",
["Tamam. Bir soluklandık. Tanrım. İyi iş."] = "TAMAM. BİR SOLUKLANDIK. TANRIM. İYİ İŞ.",
["Tamam. Bir yük daha bırakmak için dönüşe geçiyorum. 30 saniye!"] = "TAMAM. BİR YÜK DAHA BIRAKMAK İÇİN DÖNÜŞE GEÇİYORUM. 30 SANİYE!",
["Tamam. Biraz bekleyin, gaz dağılsın."] = "TAMAM. BİRAZ BEKLEYİN, GAZ DAĞILSIN.",
["Tamam. Biraz daha C4. Gerekenlerin neredeyse hepsi elimizde. Aramaya devam edin."] = "TAMAM. BİRAZ DAHA C4. GEREKENLERİN NEREDEYSE HEPSİ ELİMİZDE. ARAMAYA DEVAM EDİN.",
["Tamam. Biraz para yakma vakti."] = "TAMAM. BİRAZ PARA YAKMA VAKTİ.",
["Tamam. Bu lobide muhafızlar, kameralar ve metal dedektörleri var. Hepsini geçip asansörleri bulmalısınız. Hadi!"] = "TAMAM. BU LOBİDE MUHAFIZLAR, KAMERALAR VE METAL DEDEKTÖRLERİ VAR. HEPSİNİ GEÇİP ASANSÖRLERİ BULMALISINIZ. HADİ!",
["Tamam. Buldum onu. Adı, sosyal güvenlik numarası, köpeğinin adı... Adamı bulun. Bilişimdeki ekrana bakın. Ha, bir de slot makinesi bağımlısıymış, aramaya oradan başlamak iyi olabilir."] = "TAMAM. BULDUM ONU. ADI, SOSYAL GÜVENLİK NUMARASI, KÖPEĞİNİN ADI... ADAMI BULUN. BİLİŞİMDEKİ EKRANA BAKIN. HA, BİR DE SLOT MAKİNESİ BAĞIMLISIYMIŞ, ARAMAYA ORADAN BAŞLAMAK İYİ OLABİLİR.",
["Tamam. Buradayım, teslimatınızı bırakmaya hazırım."] = "TAMAM. BURADAYIM, TESLİMATINIZI BIRAKMAYA HAZIRIM.",
["Tamam. Burayı yakmayın millet."] = "TAMAM. BURAYI YAKMAYIN MİLLET.",
["Tamam. Bütün araçlar durdu."] = "TAMAM. BÜTÜN ARAÇLAR DURDU.",
["Tamam. Bütün veri tabanı kurtarıldı. Oyalanmanın anlamı yok, tekneye dönün."] = "TAMAM. BÜTÜN VERİ TABANI KURTARILDI. OYALANMANIN ANLAMI YOK, TEKNEYE DÖNÜN.",
["Tamam. Büyük bir müşteriyle toplantıya çağırdılar. Harika iş çıkarıyor."] = "TAMAM. BÜYÜK BİR MÜŞTERİYLE TOPLANTIYA ÇAĞIRDILAR. HARİKA İŞ ÇIKARIYOR.",
["Tamam. Cephanelik üç haneli şifre kullanıyor. Kumarhanede arayın. Rakamlar ve renkler. Ya da tahmin kumarı oynayın."] = "TAMAM. CEPHANELİK ÜÇ HANELİ ŞİFRE KULLANIYOR. KUMARHANEDE ARAYIN. RAKAMLAR VE RENKLER. YA DA TAHMİN KUMARI OYNAYIN.",
["Tamam. Daha fazla C4. Gerekeni neredeyse topladık. Aramaya devam edin."] = "TAMAM. DAHA FAZLA C4. GEREKENİ NEREDEYSE TOPLADIK. ARAMAYA DEVAM EDİN.",
["Tamam. Doğru mu anladım? Arabamı denizaltıya çevirmem için bana kredi vermeyeceksiniz?"] = "TAMAM. DOĞRU MU ANLADIM? ARABAMI DENİZALTIYA ÇEVİRMEM İÇİN BANA KREDİ VERMEYECEKSİNİZ?",
["Tamam. Dışarıdayım. Gitmeye hazırız, değil mi?"] = "TAMAM. DIŞARIDAYIM. GİTMEYE HAZIRIZ, DEĞİL Mİ?",
["Tamam. Emniyetleri açın. Aşağı inin!"] = "TAMAM. EMNİYETLERİ AÇIN. AŞAĞI İNİN!",
["Tamam. Erişim şifreleri işe yaramış galiba."] = "TAMAM. ERİŞİM ŞİFRELERİ İŞE YARAMIŞ GALİBA.",
["Tamam. Evet, bu iyi. Ama daha fazlası gerekecek."] = "TAMAM. EVET, BU İYİ. AMA DAHA FAZLASI GEREKECEK.",
["Tamam. Evet. Simyayı efedrin başlatacak. Karıştırıcıya biraz tablet atın."] = "TAMAM. EVET. SİMYAYI EFEDRİN BAŞLATACAK. KARIŞTIRICIYA BİRAZ TABLET ATIN.",
["Tamam. Geliyorum. Kocaman, siyah bir helikopter görürseniz benim. Kocaman siyah alet deyince annenizin don çekmecesindekinden bahsetmiyorsak tabii."] = "TAMAM. GELİYORUM. KOCAMAN, SİYAH BİR HELİKOPTER GÖRÜRSENİZ BENİM. KOCAMAN SİYAH ALET DEYİNCE ANNENİZİN DON ÇEKMECESİNDEKİNDEN BAHSETMİYORSAK TABİİ.",
["Tamam. Girdiniz. Şimdi etrafı araştırın. Oy makinelerini Washington'a taşıyan kamyona dair ipucu olmalı. Konteynerleri arayın, bilgisayarlara bakın. Doğru kamyonu belirlemek için ne gerekiyorsa."] = "TAMAM. GİRDİNİZ. ŞİMDİ ETRAFI ARAŞTIRIN. OY MAKİNELERİNİ WASHINGTON'A TAŞIYAN KAMYONA DAİR İPUCU OLMALI. KONTEYNERLERİ ARAYIN, BİLGİSAYARLARA BAKIN. DOĞRU KAMYONU BELİRLEMEK İÇİN NE GEREKİYORSA.",
["Tamam. Girin, doğru kamyonu ve oy makinelerini bulun. Bulunca oyları değiştirecek şekilde yeniden programlayın, sonra GenSec ganimetiyle dönün. Tek işte iki soygun. Tadını çıkarın."] = "TAMAM. GİRİN, DOĞRU KAMYONU VE OY MAKİNELERİNİ BULUN. BULUNCA OYLARI DEĞİŞTİRECEK ŞEKİLDE YENİDEN PROGRAMLAYIN, SONRA GENSEC GANİMETİYLE DÖNÜN. TEK İŞTE İKİ SOYGUN. TADINI ÇIKARIN.",
["Tamam. Gözden uzak durmaya çalışın. Her şey kontrol meselesi."] = "TAMAM. GÖZDEN UZAK DURMAYA ÇALIŞIN. HER ŞEY KONTROL MESELESİ.",
["Tamam. Güzel iş palyaçolar. Görüntüleri getirin, işi bitirelim."] = "TAMAM. GÜZEL İŞ PALYAÇOLAR. GÖRÜNTÜLERİ GETİRİN, İŞİ BİTİRELİM.",
["Tamam. Güzel teknoloji! Panik odasının kapısı bir kod ve retina tarayıcısıyla kontrol ediliyor gibi."] = "TAMAM. GÜZEL TEKNOLOJİ! PANİK ODASININ KAPISI BİR KOD VE RETİNA TARAYICISIYLA KONTROL EDİLİYOR GİBİ.",
["Tamam. Güzel. Ama kapıda iki kilit var; biri Mitchell'ın, biri Wilson'ın. İkinci kilit için bir şifre kırıcı gerekecek."] = "TAMAM. GÜZEL. AMA KAPIDA İKİ KİLİT VAR; BİRİ MITCHELL'IN, BİRİ WİLSON'IN. İKİNCİ KİLİT İÇİN BİR ŞİFRE KIRICI GEREKECEK.",
["Tamam. Güzel. İşler kolaylaşır. Başka ne kolaylaştırır söyleyeyim: Bana yol gösterecek bir işaret fişeği yakmanız."] = "TAMAM. GÜZEL. İŞLER KOLAYLAŞIR. BAŞKA NE KOLAYLAŞTIRIR SÖYLEYEYİM: BANA YOL GÖSTERECEK BİR İŞARET FİŞEĞİ YAKMANIZ.",
["Tamam. Güzel. Şimdi içine daha fazla koyun."] = "TAMAM. GÜZEL. ŞİMDİ İÇİNE DAHA FAZLA KOYUN.",
["Tamam. Harika. Bakalım yemi yutacak mı..."] = "TAMAM. HARİKA. BAKALIM YEMİ YUTACAK MI...",
["Tamam. Hazır olduğunuzda balonu kaldırın, pilot kafesi alacak."] = "TAMAM. HAZIR OLDUĞUNUZDA BALONU KALDIRIN, PİLOT KAFESİ ALACAK.",
["Tamam. Hazır olduğunuzda maskeleri takın."] = "TAMAM. HAZIR OLDUĞUNUZDA MASKELERİ TAKIN.",
["Tamam. Her şeyim var mı? Levye, plastik kelepçe, kayganlaştırıcı. Hazır! Çok pis işler için eldivenler takılsın."] = "TAMAM. HER ŞEYİM VAR MI? LEVYE, PLASTİK KELEPÇE, KAYGANLAŞTIRICI. HAZIR! ÇOK PİS İŞLER İÇİN ELDİVENLER TAKILSIN.",
["Tamam. Her... an..."] = "TAMAM. HER... AN...",
["Tamam. Hizalanıyorum. Flaplar iyi görünüyor. Yapabilirsin!"] = "TAMAM. HİZALANIYORUM. FLAPLAR İYİ GÖRÜNÜYOR. YAPABİLİRSİN!",
["Tamam. Kafes kuruldu. Ama boş. Doldurun!"] = "TAMAM. KAFES KURULDU. AMA BOŞ. DOLDURUN!",
["Tamam. Kapılar artık açık dostlar."] = "TAMAM. KAPILAR ARTIK AÇIK DOSTLAR.",
["Tamam. Kapılar artık açık olmalı dostlar."] = "TAMAM. KAPILAR ARTIK AÇIK OLMALI DOSTLAR.",
["Tamam. Kapılardayım. Benimle orada buluşun."] = "TAMAM. KAPILARDAYIM. BENİMLE ORADA BULUŞUN.",
["Tamam. Kasalar yüklendi. Alandan çıkıyoruz. Kamyonun orada olduğundan emin olun!"] = "TAMAM. KASALAR YÜKLENDİ. ALANDAN ÇIKIYORUZ. KAMYONUN ORADA OLDUĞUNDAN EMİN OLUN!",
["Tamam. Kontrol odasına gidip sondajın püskürme önleyicisini devre dışı bırakın. Heh, matkabı devre dışı bırakmak... Şimdi roller değişti, ha?"] = "TAMAM. KONTROL ODASINA GİDİP SONDAJIN PÜSKÜRME ÖNLEYİCİSİNİ DEVRE DIŞI BIRAKIN. HEH, MATKABI DEVRE DIŞI BIRAKMAK... ŞİMDİ ROLLER DEĞİŞTİ, HA?",
["Tamam. Kumandalar. Sistemlerini kırın, polisleri de uzak tutun."] = "TAMAM. KUMANDALAR. SİSTEMLERİNİ KIRIN, POLİSLERİ DE UZAK TUTUN.",
["Tamam. Küçük oyunumuzun ikinci perdesi: Kasa Dairesini açın."] = "TAMAM. KÜÇÜK OYUNUMUZUN İKİNCİ PERDESİ: KASA DAİRESİNİ AÇIN.",
["Tamam. Lanet. Bakın, telefona cevap verin. Doğaçlama yapalım."] = "TAMAM. LANET. BAKIN, TELEFONA CEVAP VERİN. DOĞAÇLAMA YAPALIM.",
["Tamam. Mangal yapan adam o."] = "TAMAM. MANGAL YAPAN ADAM O.",
["Tamam. Ne olduğunu fark etmeden şu ganimeti taşıyalım."] = "TAMAM. NE OLDUĞUNU FARK ETMEDEN ŞU GANİMETİ TAŞIYALIM.",
["Tamam. Nerede olduğunu siz biliyorsunuz ama ben bilmiyorum lan. Bir işaret fişeği yakın, olur mu?"] = "TAMAM. NEREDE OLDUĞUNU SİZ BİLİYORSUNUZ AMA BEN BİLMİYORUM LAN. BİR İŞARET FİŞEĞİ YAKIN, OLUR MU?",
["Tamam. O kapının alarmı kapalı. Şimdi içeri girin."] = "TAMAM. O KAPININ ALARMI KAPALI. ŞİMDİ İÇERİ GİRİN.",
["Tamam. O matkabı kapıya kurun."] = "TAMAM. O MATKABI KAPIYA KURUN.",
["Tamam. Onu gereken yere götürelim. Vinç kumandalarını bulun."] = "TAMAM. ONU GEREKEN YERE GÖTÜRELİM. VİNÇ KUMANDALARINI BULUN.",
["Tamam. Onun işi BFD'yi taşımak, sizin işiniz onu korumak."] = "TAMAM. ONUN İŞİ BFD'Yİ TAŞIMAK, SİZİN İŞİNİZ ONU KORUMAK.",
["Tamam. Panik odasının kapısı iki Anahtar Kartı ve retina tarayıcısıyla kontrol ediliyor. Sorun yok."] = "TAMAM. PANİK ODASININ KAPISI İKİ ANAHTAR KARTI VE RETİNA TARAYICISIYLA KONTROL EDİLİYOR. SORUN YOK.",
["Tamam. Pekâlâ. Vinci kullanıp lokomotifimizi doğru raya kaldırın. Ah lanet olsun, bakamıyorum...          "] = "TAMAM. PEKÂLÂ. VİNCİ KULLANIP LOKOMOTİFİMİZİ DOĞRU RAYA KALDIRIN. AH LANET OLSUN, BAKAMIYORUM...          ",
["Tamam. Resepsiyona gidin, bir terminal bulup konuk listesini indirin."] = "TAMAM. RESEPSİYONA GİDİN, BİR TERMİNAL BULUP KONUK LİSTESİNİ İNDİRİN.",
["Tamam. SERA karbon yakalama prototipini etkinlik salonuna taşıdı. Kolaçan edelim."] = "TAMAM. SERA KARBON YAKALAMA PROTOTİPİNİ ETKİNLİK SALONUNA TAŞIDI. KOLAÇAN EDELİM.",
["Tamam. Sessizce yapacaksak alarm sistemlerinin bazılarını kapatmalıyız. Etrafa bakın. Müzeyi arayın. Güvenliğe elektrik veren sigorta kutularını bulun. Sistemlerini kırabilirsek alarmları tetiklemeden burayı kapatabiliriz."] = "TAMAM. SESSİZCE YAPACAKSAK ALARM SİSTEMLERİNİN BAZILARINI KAPATMALIYIZ. ETRAFA BAKIN. MÜZEYİ ARAYIN. GÜVENLİĞE ELEKTRİK VEREN SİGORTA KUTULARINI BULUN. SİSTEMLERİNİ KIRABİLİRSEK ALARMLARI TETİKLEMEDEN BURAYI KAPATABİLİRİZ.",
["Tamam. Sözde oyuncakçı. Tam ileride."] = "TAMAM. SÖZDE OYUNCAKÇI. TAM İLERİDE.",
["Tamam. Sıvışmadan önce bir iş daha yapmanızı istiyorum. Güvenlik odasına gidip kamera görüntülerini alın. Aleyhimize bir şey kaydetmişlerse diye."] = "TAMAM. SIVIŞMADAN ÖNCE BİR İŞ DAHA YAPMANIZI İSTİYORUM. GÜVENLİK ODASINA GİDİP KAMERA GÖRÜNTÜLERİNİ ALIN. ALEYHİMİZE BİR ŞEY KAYDETMİŞLERSE DİYE.",
["Tamam. Tarama ekipmanları çatıda hazır. Gizlice girin; cep telefonunu, dizüstü bilgisayarını, sabit disklerini ve tabletini alın. Teknolojik ne varsa. Sonra çatıya getirin."] = "TAMAM. TARAMA EKİPMANLARI ÇATIDA HAZIR. GİZLİCE GİRİN; CEP TELEFONUNU, DİZÜSTÜ BİLGİSAYARINI, SABİT DİSKLERİNİ VE TABLETİNİ ALIN. TEKNOLOJİK NE VARSA. SONRA ÇATIYA GETİRİN.",
["Tamam. Tekrar deneyelim."] = "TAMAM. TEKRAR DENEYELİM.",
["Tamam. Trenlere dönüp o EMP'yi çantaya koyma vakti."] = "TAMAM. TRENLERE DÖNÜP O EMP'Yİ ÇANTAYA KOYMA VAKTİ.",
["Tamam. Vinci işte bu yüzden getirdik. BFD'ye bağlayın, doğru konuma getirsin."] = "TAMAM. VİNCİ İŞTE BU YÜZDEN GETİRDİK. BFD'YE BAĞLAYIN, DOĞRU KONUMA GETİRSİN.",
["Tamam. Yani. Doğru mu anlıyorum, televizyon programı fikrimi finanse etmek istemiyorsunuz. Pig Brother'ı?"] = "TAMAM. YANİ. DOĞRU MU ANLIYORUM, TELEVİZYON PROGRAMI FİKRİMİ FİNANSE ETMEK İSTEMİYORSUNUZ. PİG BROTHER'I?",
["Tamam. Yine başlıyoruz. Bu para için bebeğim!"] = "TAMAM. YİNE BAŞLIYORUZ. BU PARA İÇİN BEBEĞİM!",
["Tamam. Ön tarafa gidip normal davranma vakti."] = "TAMAM. ÖN TARAFA GİDİP NORMAL DAVRANMA VAKTİ.",
["Tamam. Ön tarafı ve üst katı göremiyorlar. İyi iş. Kasa dairesi bölümünde sadece birkaç tane kaldı."] = "TAMAM. ÖN TARAFI VE ÜST KATI GÖREMİYORLAR. İYİ İŞ. KASA DAİRESİ BÖLÜMÜNDE SADECE BİRKAÇ TANE KALDI.",
["Tamam. İletişim aktarıcılarına erişin. Aramayı evden yapıyormuşuz gibi göstereceğiz."] = "TAMAM. İLETİŞİM AKTARICILARINA ERİŞİN. ARAMAYI EVDEN YAPIYORMUŞUZ GİBİ GÖSTERECEĞİZ.",
["Tamam. İletişim sistemine erişin. Bir arama yapacağız."] = "TAMAM. İLETİŞİM SİSTEMİNE ERİŞİN. BİR ARAMA YAPACAĞIZ.",
["Tamam. İlk görev: O çitin öbür tarafına geçin."] = "TAMAM. İLK GÖREV: O ÇİTİN ÖBÜR TARAFINA GEÇİN.",
["Tamam. İlki tamam. Isı artıyor. Daha fazla fanı durdurmak işi hızlandırır."] = "TAMAM. İLKİ TAMAM. ISI ARTIYOR. DAHA FAZLA FANI DURDURMAK İŞİ HIZLANDIRIR.",
["Tamam. İlkini ben alırım ama şan şöhret sende kalabilir."] = "TAMAM. İLKİNİ BEN ALIRIM AMA ŞAN ŞÖHRET SENDE KALABİLİR.",
["Tamam. İyi görünüyor. Sağ olun."] = "TAMAM. İYİ GÖRÜNÜYOR. SAĞ OLUN.",
["Tamam. İşaret fişeğini görüyorum. Alçalmaya başlıyorum."] = "TAMAM. İŞARET FİŞEĞİNİ GÖRÜYORUM. ALÇALMAYA BAŞLIYORUM.",
["Tamam. İşaretli dolaplardan biri orada."] = "TAMAM. İŞARETLİ DOLAPLARDAN BİRİ ORADA.",
["Tamam. Şimdi beni o terminale yeniden bağlayın."] = "TAMAM. ŞİMDİ BENİ O TERMİNALE YENİDEN BAĞLAYIN.",
["Tamam. Şimdi denekleri bulup tarayıcıya götürün. Kel adamlar arıyorsunuz."] = "TAMAM. ŞİMDİ DENEKLERİ BULUP TARAYICIYA GÖTÜRÜN. KEL ADAMLAR ARIYORSUNUZ.",
["Tamam. Şimdi dostunuz Locke'a yardım edin. Bir işaret fişeği yakın. Paranın yerini bana gösterin."] = "TAMAM. ŞİMDİ DOSTUNUZ LOCKE'A YARDIM EDİN. BİR İŞARET FİŞEĞİ YAKIN. PARANIN YERİNİ BANA GÖSTERİN.",
["Tamam. Şimdi iletişim rölesini bulup erişin. Aramayı evden yapılıyormuş gibi gösterebiliriz."] = "TAMAM. ŞİMDİ İLETİŞİM RÖLESİNİ BULUP ERİŞİN. ARAMAYI EVDEN YAPILIYORMUŞ GİBİ GÖSTEREBİLİRİZ.",
["Tamam. Şimdi malikâneye. Boşuna güvenli ev demiyorlar. Bütün kapı ve pencerelerde alarm bekleyin."] = "TAMAM. ŞİMDİ MALİKÂNEYE. BOŞUNA GÜVENLİ EV DEMİYORLAR. BÜTÜN KAPI VE PENCERELERDE ALARM BEKLEYİN.",
["Tamam. Şimdi termit bitene kadar onları oyalayın."] = "TAMAM. ŞİMDİ TERMİT BİTENE KADAR ONLARI OYALAYIN.",
["Tamam. Şimdi zaman kilidini yeniden başlatıp işe yaradı mı bakalım."] = "TAMAM. ŞİMDİ ZAMAN KİLİDİNİ YENİDEN BAŞLATIP İŞE YARADI MI BAKALIM.",
["Tamam. Şimdi çıkışımızın yanına götürün. Kontrol panelini kullanın."] = "TAMAM. ŞİMDİ ÇIKIŞIMIZIN YANINA GÖTÜRÜN. KONTROL PANELİNİ KULLANIN.",
["Tamam. Şoföre gitmeye hazır olduğunuzu bildirin."] = "TAMAM. ŞOFÖRE GİTMEYE HAZIR OLDUĞUNUZU BİLDİRİN.",
["Tamam..."] = "TAMAM...",
["Tamam... Alarmı kapatmayı unutun... Çünkü az önceki lanet alarmdı. Sunucu odasını bulun."] = "TAMAM... ALARMI KAPATMAYI UNUTUN... ÇÜNKÜ AZ ÖNCEKİ LANET ALARMDI. SUNUCU ODASINI BULUN.",
["Tamam... Binada devriye gezen başka muhafızları var. Bariz zaten."] = "TAMAM... BİNADA DEVRİYE GEZEN BAŞKA MUHAFIZLARI VAR. BARİZ ZATEN.",
["Tamam... Bu iş için termal matkap lazım... Adamım bankanın arkasına sakladı. Alıp işe koyulun."] = "TAMAM... BU İŞ İÇİN TERMAL MATKAP LAZIM... ADAMIM BANKANIN ARKASINA SAKLADI. ALIP İŞE KOYULUN.",
["Tamam... Charon'ı çıkaralım. Bu benim için kişisel, o yüzden uyanık olalım."] = "TAMAM... CHARON'I ÇIKARALIM. BU BENİM İÇİN KİŞİSEL, O YÜZDEN UYANIK OLALIM.",
["Tamam... Daha fazla güvenlikçi görüyorum."] = "TAMAM... DAHA FAZLA GÜVENLİKÇİ GÖRÜYORUM.",
["Tamam... En yakın yer... Kontrol ediyorum..."] = "TAMAM... EN YAKIN YER... KONTROL EDİYORUM...",
["Tamam... Kontrol ediyorum. İyi gibi... Hımm... Buradaki elektrik şebekesi sürekli dalgalanıyor gibi... Belki icadı..."] = "TAMAM... KONTROL EDİYORUM. İYİ GİBİ... HIMM... BURADAKİ ELEKTRİK ŞEBEKESİ SÜREKLİ DALGALANIYOR GİBİ... BELKİ İCADI...",
["Tamam... Mıknatısı bağlayın lütfen."] = "TAMAM... MIKNATISI BAĞLAYIN LÜTFEN.",
["Tamam... Odayı kontrol altında tutun..."] = "TAMAM... ODAYI KONTROL ALTINDA TUTUN...",
["Tamam... Olabildiğince uzun süre sessiz kalın..."] = "TAMAM... OLABİLDİĞİNCE UZUN SÜRE SESSİZ KALIN...",
["Tamam... Soldaki düğme!"] = "TAMAM... SOLDAKİ DÜĞME!",
["Tamam... Tamam... Sunucuyu yuvasından çıkarıp minibüse taşımak kaldı."] = "TAMAM... TAMAM... SUNUCUYU YUVASINDAN ÇIKARIP MİNİBÜSE TAŞIMAK KALDI.",
["Tamam... Tamam... Sunucuyu yuvasından çıkarıp minibüse taşımanız yeterli."] = "TAMAM... TAMAM... SUNUCUYU YUVASINDAN ÇIKARIP MİNİBÜSE TAŞIMANIZ YETERLİ.",
["Tamam... hallettim. Sabit diski alabilirsiniz."] = "TAMAM... HALLETTİM. SABİT DİSKİ ALABİLİRSİNİZ.",
["Tamam... lobide daha fazla muhafız var."] = "TAMAM... LOBİDE DAHA FAZLA MUHAFIZ VAR.",
