["Tamamdır! Bu numune tam ihtiyacımız olan şey."] = "TAMAMDIR! BU NUMUNE TAM İHTİYACIMIZ OLAN ŞEY.",
["Tamamdır! Bütün veri tabanı elimizde. Bu verileri tarayıp belki doğru kamyonun nereye gittiğini bulabilirim. Sizin işiniz bitti millet."] = "TAMAMDIR! BÜTÜN VERİ TABANI ELİMİZDE. BU VERİLERİ TARAYIP BELKİ DOĞRU KAMYONUN NEREYE GİTTİĞİNİ BULABİLİRİM. SİZİN İŞİNİZ BİTTİ MİLLET.",
["Tamamdır! Gidiyorum!"] = "TAMAMDIR! GİDİYORUM!",
["Tamamdır! Laboratuvar kapısını açın!"] = "TAMAMDIR! LABORATUVAR KAPISINI AÇIN!",
["Tamamdır! Silahları doldurun!"] = "TAMAMDIR! SİLAHLARI DOLDURUN!",
["Tamamdır! Sisteme girdim. Ben bitirirken minibüse çıkıp C4'ü alın. Sokağa yerleştirin."] = "TAMAMDIR! SİSTEME GİRDİM. BEN BİTİRİRKEN MİNİBÜSE ÇIKIP C4'Ü ALIN. SOKAĞA YERLEŞTİRİN.",
["Tamamdır! Son çantayı da tuvalete attılar. Bana bir dakika verin, az önce olanları zihnimde sindirmem gerek..."] = "TAMAMDIR! SON ÇANTAYI DA TUVALETE ATTILAR. BANA BİR DAKİKA VERİN, AZ ÖNCE OLANLARI ZİHNİMDE SİNDİRMEM GEREK...",
["Tamamdır! Tekneye dönün sizi aptallar!"] = "TAMAMDIR! TEKNEYE DÖNÜN SİZİ APTALLAR!",
["Tamamdır! Termit işini bitirdi. Şimdi aşağı inin."] = "TAMAMDIR! TERMİT İŞİNİ BİTİRDİ. ŞİMDİ AŞAĞI İNİN.",
["Tamamdır! Yaramazlıklarımızı izleyecek tek bir kamera bile kalmadı. Harika iş."] = "TAMAMDIR! YARAMAZLIKLARIMIZI İZLEYECEK TEK BİR KAMERA BİLE KALMADI. HARİKA İŞ.",
["Tamamdır, Bain. Bütün kayıtlar silindi."] = "TAMAMDIR, BAIN. BÜTÜN KAYITLAR SİLİNDİ.",
["Tamamdır, bitti! C4 çatıya bırakıldı."] = "TAMAMDIR, BİTTİ! C4 ÇATIYA BIRAKILDI.",
["Tamamdır, bu kadar! Ben gidiyorum!"] = "TAMAMDIR, BU KADAR! BEN GİDİYORUM!",
["Tamamdır, ekip. Sadece dördüncü kat kaldı."] = "TAMAMDIR, EKİP. SADECE DÖRDÜNCÜ KAT KALDI.",
["Tamamdır, işim bitti!"] = "TAMAMDIR, İŞİM BİTTİ!",
["Tamamdır, sadece beşinci kat kaldı."] = "TAMAMDIR, SADECE BEŞİNCİ KAT KALDI.",
["Tamamdır, yönlendirici kutuları halledildi."] = "TAMAMDIR, YÖNLENDİRİCİ KUTULARI HALLEDİLDİ.",
["Tamamdır. Kapılar açılmış olmalı."] = "TAMAMDIR. KAPILAR AÇILMIŞ OLMALI.",
["Tamamdır. Kapıyı açabilirsiniz."] = "TAMAMDIR. KAPIYI AÇABİLİRSİNİZ.",
["Tamamdır. Moretta hareket ediyor! Biraz sürebilir, siper alın. Ölmemeye çalışın."] = "TAMAMDIR. MORETTA HAREKET EDİYOR! BİRAZ SÜREBİLİR, SİPER ALIN. ÖLMEMEYE ÇALIŞIN.",
["Tamamdır. Şimdi düğmeye basıp bariyerleri indirin."] = "TAMAMDIR. ŞİMDİ DÜĞMEYE BASIP BARİYERLERİ İNDİRİN.",
["Tamamen anlaşılır. Belki fırsat çıkarsa çocuklar halleder."] = "TAMAMEN ANLAŞILIR. BELKİ FIRSAT ÇIKARSA ÇOCUKLAR HALLEDER.",
["Tamamen açık alan. Görüş hattı çok. Kullanın ama dikkatli olun. Keskin nişancılar burayı iyi görüyor."] = "TAMAMEN AÇIK ALAN. GÖRÜŞ HATTI ÇOK. KULLANIN AMA DİKKATLİ OLUN. KESKİN NİŞANCILAR BURAYI İYİ GÖRÜYOR.",
["Tamamen çalışan bir metamfetamin laboratuvarı! Formül görürseniz pişirmeye başlayın ya da mekânı yakın. Hayatınızda birkaç metamfetamin laboratuvarı yakmışsınızdır eminim."] = "TAMAMEN ÇALIŞAN BİR METAMFETAMİN LABORATUVARI! FORMÜL GÖRÜRSENİZ PİŞİRMEYE BAŞLAYIN YA DA MEKÂNI YAKIN. HAYATINIZDA BİRKAÇ METAMFETAMİN LABORATUVARI YAKMIŞSINIZDIR EMİNİM.",
["Tamamladığın tüm meydan okumaları görüntüle."] = "TAMAMLADIĞIN TÜM MEYDAN OKUMALARI GÖRÜNTÜLE.",
["Tamamladığınız bütün maskeleri tam buraya asacağız. "] = "TAMAMLADIĞINIZ BÜTÜN MASKELERİ TAM BURAYA ASACAĞIZ. ",
