["Tamamlanan Soygunlar"] = "TAMAMLANAN SOYGUNLAR",
["Tamamlanan soygun sayısı"] = "TAMAMLANAN SOYGUN SAYISI",
["Tamamlandı, değişiklikleri onaylayın."] = "TAMAMLANDI, DEĞİŞİKLİKLERİ ONAYLAYIN.",
["Tamamlandı."] = "TAMAMLANDI.",
["Tamamlandı. Aşağıdaki ödüllerden birini seç!"] = "TAMAMLANDI. AŞAĞIDAKİ ÖDÜLLERDEN BİRİNİ SEÇ!",
["Tamamlandı. Ödüllerini al!"] = "TAMAMLANDI. ÖDÜLLERİNİ AL!",
["Tamamı Ödendi"] = "TAMAMI ÖDENDİ",
["Tamburalı Şarjör"] = "TAMBURALI ŞARJÖR",
["Tamirci Dükkânı"] = "TAMİRCİ DÜKKÂNI",
["Tamirci Dükkânı Girişi"] = "TAMİRCİ DÜKKÂNI GİRİŞİ",
["Tamirci Dükkânındaki Lastik Yığını"] = "TAMİRCİ DÜKKÂNINDAKİ LASTİK YIĞINI",
["Tamirci Rust'ın motoru üzerinde çalışmaya başlasın. Dediğini yapıp ihtiyacı olanları ona getirin."] = "TAMİRCİ RUST'IN MOTORU ÜZERİNDE ÇALIŞMAYA BAŞLASIN. DEDİĞİNİ YAPIP İHTİYACI OLANLARI ONA GETİRİN.",
["Tamirci Rust'ın motorunu birleştirmenize yardım etsin. Bu işte onun dediğini yapmalısınız."] = "TAMİRCİ RUST'IN MOTORUNU BİRLEŞTİRMENİZE YARDIM ETSİN. BU İŞTE ONUN DEDİĞİNİ YAPMALISINIZ.",
["Tamirci atölyedeki aletlerinin gerektiğini söyledi. Oraya gidin."] = "TAMİRCİ ATÖLYEDEKİ ALETLERİNİN GEREKTİĞİNİ SÖYLEDİ. ORAYA GİDİN.",
