["Tamirci dükkânı"] = "TAMİRCİ DÜKKÂNI",
["Tamirci ekipmanını almanı bekliyor!"] = "TAMİRCİ EKİPMANINI ALMANI BEKLİYOR!",
["Tamirci sığınağa gidip onun için seleyi almanızı söyledi."] = "TAMİRCİ SIĞINAĞA GİDİP ONUN İÇİN SELEYİ ALMANIZI SÖYLEDİ.",
