["Tamirci, kulüp binasındaki bir depodan krom kafatası almanı istiyor. Tamirciden pürmüz alman gerekecek. Depoya gir, kafatasını alıp ona götür!"] = "TAMİRCİ, KULÜP BİNASINDAKİ BİR DEPODAN KROM KAFATASI ALMANI İSTİYOR. TAMİRCİDEN PÜRMÜZ ALMAN GEREKECEK. DEPOYA GİR, KAFATASINI ALIP ONA GÖTÜR!",
["Tamirci, kulüp binasının içine motor koyduklarını gördüğünü söyledi. Gidip bakın."] = "TAMİRCİ, KULÜP BİNASININ İÇİNE MOTOR KOYDUKLARINI GÖRDÜĞÜNÜ SÖYLEDİ. GİDİP BAKIN.",
["Tamircinin bağlarını çöz"] = "TAMİRCİNİN BAĞLARINI ÇÖZ",
["Tamircinin ekipmanını al"] = "TAMİRCİNİN EKİPMANINI AL",
["Tamircinin garajdaki bir motosikletten özel bir parçaya ihtiyacı var. Dostumuz tamirciye yol açmak için garajı aç. Hedefe kadar ona eşlik edip onu koru. Parçalarını aldıktan sonra onunla kamyona dön."] = "TAMİRCİNİN GARAJDAKİ BİR MOTOSİKLETTEN ÖZEL BİR PARÇAYA İHTİYACI VAR. DOSTUMUZ TAMİRCİYE YOL AÇMAK İÇİN GARAJI AÇ. HEDEFE KADAR ONA EŞLİK EDİP ONU KORU. PARÇALARINI ALDIKTAN SONRA ONUNLA KAMYONA DÖN.",
["Tamircinin istediği krom kafatasını alın. Kulüp binasına girip size verdiği şalomayı kullanın."] = "TAMİRCİNİN İSTEDİĞİ KROM KAFATASINI ALIN. KULÜP BİNASINA GİRİP SİZE VERDİĞİ ŞALOMAYI KULLANIN.",
["Tamircinin işi bitti. Daha fazla ganimet istiyorsanız şimdi alın, yoksa motorlara atlayıp çıkın oradan. "] = "TAMİRCİNİN İŞİ BİTTİ. DAHA FAZLA GANİMET İSTİYORSANIZ ŞİMDİ ALIN, YOKSA MOTORLARA ATLAYIP ÇIKIN ORADAN. ",
["Tamircinin özel parçaları toplamasına yardım et"] = "TAMİRCİNİN ÖZEL PARÇALARI TOPLAMASINA YARDIM ET",
["Tamircinin, onun için topladığın motosiklet parçasının montajını bitirmesini bekle. Sonra ne yapacağını söyleyecek."] = "TAMİRCİNİN, ONUN İÇİN TOPLADIĞIN MOTOSİKLET PARÇASININ MONTAJINI BİTİRMESİNİ BEKLE. SONRA NE YAPACAĞINI SÖYLEYECEK.",
["Tamirciye göre fazla şıksınız. İşe başlamadan üst değiştirirsiniz herhâlde, ha? "] = "TAMİRCİYE GÖRE FAZLA ŞIKSINIZ. İŞE BAŞLAMADAN ÜST DEĞİŞTİRİRSİNİZ HERHÂLDE, HA? ",
["Tamirciye yardım et ve onu bantlarından kurtar!"] = "TAMİRCİYE YARDIM ET VE ONU BANTLARINDAN KURTAR!",
["Tamirciyi kamyona kadar takip et"] = "TAMİRCİYİ KAMYONA KADAR TAKİP ET",
["Tamirciyi savun"] = "TAMİRCİYİ SAVUN",
["Tamirciyi tam zamanında kurtardınız. Şimdi sandalyeden kaldırın da motoru toplasın."] = "TAMİRCİYİ TAM ZAMANINDA KURTARDINIZ. ŞİMDİ SANDALYEDEN KALDIRIN DA MOTORU TOPLASIN.",
["Tampon çıkartması gibi yapıştılar bize!"] = "TAMPON ÇIKARTMASI GİBİ YAPIŞTILAR BİZE!",
["Tane, muazzam gücüyle anne babası olan yeri ve göğü birbirinden ayıran orman tanrısıydı. Efsaneler ilk insan Tiki’yi de onun yarattığını söyler. Böylece bildiğimiz dünyayı ve içindeki insanları yarattı."] = "TANE, MUAZZAM GÜCÜYLE ANNE BABASI OLAN YERİ VE GÖĞÜ BİRBİRİNDEN AYIRAN ORMAN TANRISIYDI. EFSANELER İLK İNSAN TİKİ’Yİ DE ONUN YARATTIĞINI SÖYLER. BÖYLECE BİLDİĞİMİZ DÜNYAYI VE İÇİNDEKİ İNSANLARI YARATTI.",
["Tane’nin kardeşi Tawhiri, havanın, özellikle de şiddetli fırtınaların ve şimşeklerin tanrısıdır. Bodhi ikisinden de bolca nasibini aldı. Tuvalu’da resif dalışı sırasında yaşanan özellikle şiddetli bir patlama, Bodhi’nin bu güçlü tanrının kıymetini gerçekten anlamasını sağladı."] = "TANE’NİN KARDEŞİ TAWHİRİ, HAVANIN, ÖZELLİKLE DE ŞİDDETLİ FIRTINALARIN VE ŞİMŞEKLERİN TANRISIDIR. BODHI İKİSİNDEN DE BOLCA NASİBİNİ ALDI. TUVALU’DA RESİF DALIŞI SIRASINDA YAŞANAN ÖZELLİKLE ŞİDDETLİ BİR PATLAMA, BODHI’NİN BU GÜÇLÜ TANRININ KIYMETİNİ GERÇEKTEN ANLAMASINI SAĞLADI.",
