["Tanrı gibisiniz. Devam edin."] = "TANRI GİBİSİNİZ. DEVAM EDİN.",
["Tanrı seninle olsun, sik kafalı."] = "TANRI SENİNLE OLSUN, SİK KAFALI.",
["Tanrı'ya sığınmanın tam zamanı!"] = "TANRI'YA SIĞINMANIN TAM ZAMANI!",
