["The Diamond soygununda Direnişe 1. dalgadan başlayarak 7. dalgayı tamamla."] = "THE DIAMOND SOYGUNUNDA DİRENİŞE 1. DALGADAN BAŞLAYARAK 7. DALGAYI TAMAMLA.",
["The Diamond soygununda Direnişe 1. dalgadan başlayarak 9. dalgayı tamamla."] = "THE DIAMOND SOYGUNUNDA DİRENİŞE 1. DALGADAN BAŞLAYARAK 9. DALGAYI TAMAMLA.",
