["Undercover soygununu OVERKILL veya üzeri zorlukta; tüm ekip üyeleri yalnızca keskin nişancı tüfekleri kullanırken, hiçbir beceri kullanmadan ve İki Parçalı Takım Elbise giyerek tamamla."] = "UNDERCOVER SOYGUNUNU OVERKILL VEYA ÜZERİ ZORLUKTA; TÜM EKİP ÜYELERİ YALNIZCA KESKİN NİŞANCI TÜFEKLERİ KULLANIRKEN, HİÇBİR BECERİ KULLANMADAN VE İKİ PARÇALI TAKIM ELBİSE GİYEREK TAMAMLA.",
["Undercover soygununu Zor veya daha yüksek zorlukta tamamla."] = "UNDERCOVER SOYGUNUNU ZOR VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Undercover soygununu hiç Keskin Nişancı öldürmeden tamamla."] = "UNDERCOVER SOYGUNUNU HİÇ KESKİN NİŞANCI ÖLDÜRMEDEN TAMAMLA.",
["Undercover soygununu Çok Zor veya daha yüksek zorlukta tamamla."] = "UNDERCOVER SOYGUNUNU ÇOK ZOR VEYA DAHA YÜKSEK ZORLUKTA TAMAMLA.",
["Union 5.56 Tüfeği"] = "UNION 5.56 TÜFEĞİ",
["Unutma, Rusça Yok"] = "UNUTMA, RUSÇA YOK",
["Unutma, maskeni takma. Önce etrafı kolaçan et."] = "UNUTMA, MASKENİ TAKMA. ÖNCE ETRAFI KOLAÇAN ET.",
["Unutma, yalnız bir oyuncu Cloaker için kolay hedeftir."] = "UNUTMA, YALNIZ BİR OYUNCU CLOAKER İÇİN KOLAY HEDEFTİR.",
["Unutma. Bu adamı öldürme. Çağrı cihazına cevap verirsen kontroldeki adam bir daha kanmaz."] = "UNUTMA. BU ADAMI ÖLDÜRME. ÇAĞRI CİHAZINA CEVAP VERİRSEN KONTROLDEKİ ADAM BİR DAHA KANMAZ.",
["Unutma: Sevdiklerine hep zaman ayır ama işin hakkında soru sormalarına izin verme."] = "UNUTMA: SEVDİKLERİNE HEP ZAMAN AYIR AMA İŞİN HAKKINDA SORU SORMALARINA İZİN VERME.",
["Unutmayın dostlar, bunu Bain için yapıyoruz. Garrett'ı çıldırtmak eğlenceli olsa da planlarını bozmalıyız."] = "UNUTMAYIN DOSTLAR, BUNU BAIN İÇİN YAPIYORUZ. GARRETT'I ÇILDIRTMAK EĞLENCELİ OLSA DA PLANLARINI BOZMALIYIZ.",
["Unutmayın dostlar, ofise gidin."] = "UNUTMAYIN DOSTLAR, OFİSE GİDİN.",
["Unutmayın dostlar: Yanlış kabloyu keserseniz alarmı tetiklersiniz, hayatımız çok daha zorlaşır."] = "UNUTMAYIN DOSTLAR: YANLIŞ KABLOYU KESERSENİZ ALARMI TETİKLERSİNİZ, HAYATIMIZ ÇOK DAHA ZORLAŞIR.",
["Unutmayın ekip, Garrett'ın nefes alması gerekiyor... şimdilik."] = "UNUTMAYIN EKİP, GARRETT'IN NEFES ALMASI GEREKİYOR... ŞİMDİLİK.",
["Unutmayın millet, bu her şey için. Teneke kutu da dâhil."] = "UNUTMAYIN MİLLET, BU HER ŞEY İÇİN. TENEKE KUTU DA DÂHİL.",
["Unutmayın millet, bu işin getirisi önemli."] = "UNUTMAYIN MİLLET, BU İŞİN GETİRİSİ ÖNEMLİ.",
["Unutmayın millet, güvenlik şefini arıyorsunuz. USB belleği lazım."] = "UNUTMAYIN MİLLET, GÜVENLİK ŞEFİNİ ARIYORSUNUZ. USB BELLEĞİ LAZIM.",
["Unutmayın millet, hem Taxman hem sunucu gerekiyor. Sunucunun onda olduğunu doğrulayınca korkutup limuzine sokun."] = "UNUTMAYIN MİLLET, HEM TAXMAN HEM SUNUCU GEREKİYOR. SUNUCUNUN ONDA OLDUĞUNU DOĞRULAYINCA KORKUTUP LİMUZİNE SOKUN.",
["Unutmayın millet, kaçmak için altı çanta lazım."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN ALTI ÇANTA LAZIM.",
["Unutmayın millet, kaçmak için beş çanta lazım."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN BEŞ ÇANTA LAZIM.",
["Unutmayın millet, kaçmak için dokuz çanta lazım."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN DOKUZ ÇANTA LAZIM.",
["Unutmayın millet, kaçmak için dört çanta lazım."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN DÖRT ÇANTA LAZIM.",
["Unutmayın millet, kaçmak için en az bir çanta gerekiyor."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN EN AZ BİR ÇANTA GEREKİYOR.",
["Unutmayın millet, kaçmak için en az iki çanta gerekiyor."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN EN AZ İKİ ÇANTA GEREKİYOR.",
["Unutmayın millet, kaçmak için on çanta gerekiyor."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN ON ÇANTA GEREKİYOR.",
["Unutmayın millet, kaçmak için sekiz çanta gerekiyor."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN SEKİZ ÇANTA GEREKİYOR.",
["Unutmayın millet, kaçmak için yedi çanta lazım."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN YEDİ ÇANTA LAZIM.",
["Unutmayın millet, kaçmak için üç çanta lazım."] = "UNUTMAYIN MİLLET, KAÇMAK İÇİN ÜÇ ÇANTA LAZIM.",
["Unutmayın! En az dört çanta!"] = "UNUTMAYIN! EN AZ DÖRT ÇANTA!",
["Unutmayın! Taxman'i gerçekten vurmayın, sadece limuzinde siper almaya zorlayın. Baskı ateşi açın."] = "UNUTMAYIN! TAXMAN'İ GERÇEKTEN VURMAYIN, SADECE LİMUZİNDE SİPER ALMAYA ZORLAYIN. BASKI ATEŞİ AÇIN.",
["Unutmayın, Anahtar Kartı'nı şu kilide okutacaksınız. Roket bilimi değil lan."] = "UNUTMAYIN, ANAHTAR KARTI'NI ŞU KİLİDE OKUTACAKSINIZ. ROKET BİLİMİ DEĞİL LAN.",
["Unutmayın, C4 X işaretli dolaplara saklandı."] = "UNUTMAYIN, C4 X İŞARETLİ DOLAPLARA SAKLANDI.",
["Unutmayın, C4 arıyoruz. X işaretli dolaplarda bulacaksınız."] = "UNUTMAYIN, C4 ARIYORUZ. X İŞARETLİ DOLAPLARDA BULACAKSINIZ.",
["Unutmayın, C4'ü garaja yerleştirmelisiniz."] = "UNUTMAYIN, C4'Ü GARAJA YERLEŞTİRMELİSİNİZ.",
["Unutmayın, Downtown Washington hakkında ipucu arıyorsunuz. Dosya, işaret, herhangi bir şey. Nerede olduğunu bulun."] = "UNUTMAYIN, DOWNTOWN WASHINGTON HAKKINDA İPUCU ARIYORSUNUZ. DOSYA, İŞARET, HERHANGİ BİR ŞEY. NEREDE OLDUĞUNU BULUN.",
["Unutmayın, Gemma bize silah atölyesini yok etmemiz için para veriyor. İçerideki adamımız kanıtları yok etmek için tesiste hidroklorik asit tuttuklarını söylüyor. Çeliği güzel ve sessizce eritebilir."] = "UNUTMAYIN, GEMMA BİZE SİLAH ATÖLYESİNİ YOK ETMEMİZ İÇİN PARA VERİYOR. İÇERİDEKİ ADAMIMIZ KANITLARI YOK ETMEK İÇİN TESİSTE HİDROKLORİK ASİT TUTTUKLARINI SÖYLÜYOR. ÇELİĞİ GÜZEL VE SESSİZCE ERİTEBİLİR.",
["Unutmayın, Kasa Dairesi için Murkywater sevkiyat konteynerlerine bakın."] = "UNUTMAYIN, KASA DAİRESİ İÇİN MURKYWATER SEVKİYAT KONTEYNERLERİNE BAKIN.",
["Unutmayın, altı çantaya ihtiyacımız var!"] = "UNUTMAYIN, ALTI ÇANTAYA İHTİYACIMIZ VAR!",
["Unutmayın, anahtar kartı arıyorsunuz. Binaları kontrol edin."] = "UNUTMAYIN, ANAHTAR KARTI ARIYORSUNUZ. BİNALARI KONTROL EDİN.",
["Unutmayın, arabanın anahtarları lazım!"] = "UNUTMAYIN, ARABANIN ANAHTARLARI LAZIM!",
["Unutmayın, banka müdürü. Anahtar Kartı'nı ondan alın."] = "UNUTMAYIN, BANKA MÜDÜRÜ. ANAHTAR KARTI'NI ONDAN ALIN.",
["Unutmayın, banka soymaya geldik. Ama kazara bir iki oy makinesini kurşunlarsak da kader işte. Anlaşıldı mı?"] = "UNUTMAYIN, BANKA SOYMAYA GELDİK. AMA KAZARA BİR İKİ OY MAKİNESİNİ KURŞUNLARSAK DA KADER İŞTE. ANLAŞILDI MI?",
["Unutmayın, banka soymaya geldik. Bu sırada bazı seçim ekipmanları yok olursa ne yazık. Oy sonuçları da bir şekilde kullanılamaz olsa gerçekten çok yazık olur..."] = "UNUTMAYIN, BANKA SOYMAYA GELDİK. BU SIRADA BAZI SEÇİM EKİPMANLARI YOK OLURSA NE YAZIK. OY SONUÇLARI DA BİR ŞEKİLDE KULLANILAMAZ OLSA GERÇEKTEN ÇOK YAZIK OLUR...",
["Unutmayın, baştaki herifin bilgisayarını arıyorsunuz."] = "UNUTMAYIN, BAŞTAKİ HERİFİN BİLGİSAYARINI ARIYORSUNUZ.",
["Unutmayın, biraz benzin bulup lastiklere dökmeniz gerekiyor!"] = "UNUTMAYIN, BİRAZ BENZİN BULUP LASTİKLERE DÖKMENİZ GEREKİYOR!",
["Unutmayın, boş bir anahtarlık bulmalısınız."] = "UNUTMAYIN, BOŞ BİR ANAHTARLIK BULMALISINIZ.",
["Unutmayın, bu arabalar kusursuz kalmalı. Çizik yok, kurşun deliği kesinlikle yok. Yani polis de yok. Sessiz kalın."] = "UNUTMAYIN, BU ARABALAR KUSURSUZ KALMALI. ÇİZİK YOK, KURŞUN DELİĞİ KESİNLİKLE YOK. YANİ POLİS DE YOK. SESSİZ KALIN.",
["Unutmayın, buna banka soygunu süsü vermek için buradayız. Bu sırada bazı seçim ekipmanları parçalanırsa ne yazık. Oy sonuçları bir şekilde kullanılamaz hâle gelirse de gerçekten çok yazık olur..."] = "UNUTMAYIN, BUNA BANKA SOYGUNU SÜSÜ VERMEK İÇİN BURADAYIZ. BU SIRADA BAZI SEÇİM EKİPMANLARI PARÇALANIRSA NE YAZIK. OY SONUÇLARI BİR ŞEKİLDE KULLANILAMAZ HÂLE GELİRSE DE GERÇEKTEN ÇOK YAZIK OLUR...",
["Unutmayın, bundan sonra böyle ‘özel’ iyilikler için para ödemeniz gerekecek. Bağlantılarım bedavaya çalışmaz."] = "UNUTMAYIN, BUNDAN SONRA BÖYLE ‘ÖZEL’ İYİLİKLER İÇİN PARA ÖDEMENİZ GEREKECEK. BAĞLANTILARIM BEDAVAYA ÇALIŞMAZ.",
["Unutmayın, bunu sessizce yapıyoruz. Alarm çalarsa hapı yutarız."] = "UNUTMAYIN, BUNU SESSİZCE YAPIYORUZ. ALARM ÇALARSA HAPI YUTARIZ.",
["Unutmayın, burası tahkim edilmiş bir tesis. Sert direniş bekleyin."] = "UNUTMAYIN, BURASI TAHKİM EDİLMİŞ BİR TESİS. SERT DİRENİŞ BEKLEYİN.",
["Unutmayın, cephaneliği arıyorsunuz."] = "UNUTMAYIN, CEPHANELİĞİ ARIYORSUNUZ.",
["Unutmayın, diğer kamyonlar bizim! Ama ganimetimizi geri istiyoruz. Polislerin dikkatini oy makinelerinden uzaklaştırmak için onları kullanın."] = "UNUTMAYIN, DİĞER KAMYONLAR BİZİM! AMA GANİMETİMİZİ GERİ İSTİYORUZ. POLİSLERİN DİKKATİNİ OY MAKİNELERİNDEN UZAKLAŞTIRMAK İÇİN ONLARI KULLANIN.",
["Unutmayın, dört çanta lazım!"] = "UNUTMAYIN, DÖRT ÇANTA LAZIM!",
["Unutmayın, en az 3 çanta metamfetamin lazım."] = "UNUTMAYIN, EN AZ 3 ÇANTA METAMFETAMİN LAZIM.",
["Unutmayın, en az dört çanta metamfetamin lazım."] = "UNUTMAYIN, EN AZ DÖRT ÇANTA METAMFETAMİN LAZIM.",
["Unutmayın, eğilin, karanlıkta kalın. Ve sessiz olun. Başlıyoruz."] = "UNUTMAYIN, EĞİLİN, KARANLIKTA KALIN. VE SESSİZ OLUN. BAŞLIYORUZ.",
["Unutmayın, ganimeti havalandırmaya saklayın."] = "UNUTMAYIN, GANİMETİ HAVALANDIRMAYA SAKLAYIN.",
["Unutmayın, hasarlı arabaları satamayız. Polis yok yani. Sessiz kalın. Yola C4'ü ne zaman yerleştireceğinizi söyleyeceğim."] = "UNUTMAYIN, HASARLI ARABALARI SATAMAYIZ. POLİS YOK YANİ. SESSİZ KALIN. YOLA C4'Ü NE ZAMAN YERLEŞTİRECEĞİNİZİ SÖYLEYECEĞİM.",
["Unutmayın, iskeleye sıkışmış bir keçi var."] = "UNUTMAYIN, İSKELEYE SIKIŞMIŞ BİR KEÇİ VAR.",
["Unutmayın, keçiyi indirmek için sokak lambasına testere takmalısınız."] = "UNUTMAYIN, KEÇİYİ İNDİRMEK İÇİN SOKAK LAMBASINA TESTERE TAKMALISINIZ.",
["Unutmayın, levye bulup Kasa Dairesi'nin fanlarına sıkıştırmalısınız. Büyük ihtimalle deponun içindedirler."] = "UNUTMAYIN, LEVYE BULUP KASA DAİRESİ'NİN FANLARINA SIKIŞTIRMALISINIZ. BÜYÜK İHTİMALLE DEPONUN İÇİNDEDİRLER.",
["Unutmayın, mafyacıları bulun. İzlerini sürüp indirin."] = "UNUTMAYIN, MAFYACILARI BULUN. İZLERİNİ SÜRÜP İNDİRİN.",
["Unutmayın, merdivenle vagonların üstüne çıkabilirsiniz."] = "UNUTMAYIN, MERDİVENLE VAGONLARIN ÜSTÜNE ÇIKABİLİRSİNİZ.",
["Unutmayın, muhafızlar yeri değişen kitaplığı fark eder."] = "UNUTMAYIN, MUHAFIZLAR YERİ DEĞİŞEN KİTAPLIĞI FARK EDER.",
["Unutmayın, muhbirin peşindeyiz. Otobüse yönelin. Başınızı eğip siperden sipere ilerleyin."] = "UNUTMAYIN, MUHBİRİN PEŞİNDEYİZ. OTOBÜSE YÖNELİN. BAŞINIZI EĞİP SİPERDEN SİPERE İLERLEYİN.",
["Unutmayın, o anahtar etiketinin yeniden kodlanması gerek."] = "UNUTMAYIN, O ANAHTAR ETİKETİNİN YENİDEN KODLANMASI GEREK.",
["Unutmayın, o dizüstü bilgisayarları bulun."] = "UNUTMAYIN, O DİZÜSTÜ BİLGİSAYARLARI BULUN.",
["Unutmayın, o ganimeti havalandırmalardan birine doldurun."] = "UNUTMAYIN, O GANİMETİ HAVALANDIRMALARDAN BİRİNE DOLDURUN.",
["Unutmayın, o kafesi kurmazsanız parayı taşıyamayız. Halledin!"] = "UNUTMAYIN, O KAFESİ KURMAZSANIZ PARAYI TAŞIYAMAYIZ. HALLEDİN!",
["Unutmayın, o kamyonlardaki her şey sizin. Geri götürmezseniz para kaybedersiniz."] = "UNUTMAYIN, O KAMYONLARDAKİ HER ŞEY SİZİN. GERİ GÖTÜRMEZSENİZ PARA KAYBEDERSİNİZ.",
["Unutmayın, o metamfetamini parçalamanız gerek."] = "UNUTMAYIN, O METAMFETAMİNİ PARÇALAMANIZ GEREK.",
["Unutmayın, o radarların her birine C4 yerleştirmeniz gerekiyor."] = "UNUTMAYIN, O RADARLARIN HER BİRİNE C4 YERLEŞTİRMENİZ GEREKİYOR.",
["Unutmayın, o ses kayıt cihazını bulmalısınız."] = "UNUTMAYIN, O SES KAYIT CİHAZINI BULMALISINIZ.",
["Unutmayın, oy makinelerini arıyoruz. Bence etrafa dağılmış nakliye sandıklarındalar."] = "UNUTMAYIN, OY MAKİNELERİNİ ARIYORUZ. BENCE ETRAFA DAĞILMIŞ NAKLİYE SANDIKLARINDALAR.",
["Unutmayın, oy makinelerinin peşindeyiz. Sonucu McKendrick'in lehine çevirmek için sistemlerini kırmamız gerekiyor. Nakliye sandıklarına bakın."] = "UNUTMAYIN, OY MAKİNELERİNİN PEŞİNDEYİZ. SONUCU MCKENDRİCK'İN LEHİNE ÇEVİRMEK İÇİN SİSTEMLERİNİ KIRMAMIZ GEREKİYOR. NAKLİYE SANDIKLARINA BAKIN.",
["Unutmayın, patlama ganimeti odanın öbür ucuna fırlatmış olabilir."] = "UNUTMAYIN, PATLAMA GANİMETİ ODANIN ÖBÜR UCUNA FIRLATMIŞ OLABİLİR.",
["Unutmayın, patlama ganimeti zeminin her yanına saçmış olabilir."] = "UNUTMAYIN, PATLAMA GANİMETİ ZEMİNİN HER YANINA SAÇMIŞ OLABİLİR.",
["Unutmayın, patlayıcıları kapının yakınına bırakın."] = "UNUTMAYIN, PATLAYICILARI KAPININ YAKININA BIRAKIN.",
["Unutmayın, rolden çıkmayın."] = "UNUTMAYIN, ROLDEN ÇIKMAYIN.",
["Unutmayın, sekiz çanta lazım!"] = "UNUTMAYIN, SEKİZ ÇANTA LAZIM!",
["Unutmayın, sevgili dostlar. Kargo bölmesinin kapılarını açmanız gerek."] = "UNUTMAYIN, SEVGİLİ DOSTLAR. KARGO BÖLMESİNİN KAPILARINI AÇMANIZ GEREK.",
["Unutmayın, sivil hâldesiniz. Yani silah ve maske yok. Görünmezsiniz. İçerideki adamımız Micho, ekipmanınızı bir gitar kutusunda bir yere bıraktı."] = "UNUTMAYIN, SİVİL HÂLDESİNİZ. YANİ SİLAH VE MASKE YOK. GÖRÜNMEZSİNİZ. İÇERİDEKİ ADAMIMIZ MİCHO, EKİPMANINIZI BİR GİTAR KUTUSUNDA BİR YERE BIRAKTI.",
["Unutmayın, sıçanın peşindeyiz. Otobüse gidin, başınızı eğin, siperden sipere ilerleyin."] = "UNUTMAYIN, SIÇANIN PEŞİNDEYİZ. OTOBÜSE GİDİN, BAŞINIZI EĞİN, SİPERDEN SİPERE İLERLEYİN.",
["Unutmayın, tabloları ateşe vermek için benzin bidonu lazım. Bidona ateş edin."] = "UNUTMAYIN, TABLOLARI ATEŞE VERMEK İÇİN BENZİN BİDONU LAZIM. BİDONA ATEŞ EDİN.",
["Unutmayın, tamirci bir sığınaktan söz etmişti. Motorun selesini orada bulacaktınız."] = "UNUTMAYIN, TAMİRCİ BİR SIĞINAKTAN SÖZ ETMİŞTİ. MOTORUN SELESİNİ ORADA BULACAKTINIZ.",
["Unutmayın, tuzağı tetikleyin!"] = "UNUTMAYIN, TUZAĞI TETİKLEYİN!",
