["Uçakla Kaçış"] = "UÇAKLA KAÇIŞ",
["Uçaksavar devre dışı! Şimdi dizüstü bilgisayarı alıp sonrakine gidin!"] = "UÇAKSAVAR DEVRE DIŞI! ŞİMDİ DİZÜSTÜ BİLGİSAYARI ALIP SONRAKİNE GİDİN!",
